TELEGRAM_API = "https://api.telegram.org"
LANGS = ("de", "fr", "it", "rm", "en")            # the five languages (Swiss national languages + English)
LANG_NAMES = {"de": "Deutsch", "fr": "Français", "it": "Italiano", "rm": "Rumantsch", "en": "English"}
LOCALES = {"de": "de-CH", "fr": "fr-CH", "it": "it-CH", "rm": "de-CH", "en": "en-GB"}
TRX = {"fr": {}, "it": {}, "rm": {}}     # English text -> French / Italian / Romansh (filled at the end of the file)
HELP_X = {}                             # the manual in French / Italian / Romansh (filled at the end of the file)
LANG_JS = r"""
// ---- language: menu with the five languages (the choice is kept per device) ----
var LANGN = {de: "Deutsch", fr: "Français", it: "Italiano", rm: "Rumantsch", en: "English"};
var LOCALE = l => ({de: "de-CH", fr: "fr-CH", it: "it-CH", rm: "de-CH"})[l] || "en-GB";
function langSet(k) {      // keep the language (also on the Pi, for the other pages / devices), then load the page in it
  try { localStorage.setItem("mw-lang", k); } catch (e) {}
  const go = () => location.reload();
  try { fetch("/api/ui", {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({set: {"mw-lang": k}})}).then(go, go); setTimeout(go, 1500); }
  catch (e) { go(); }
}
function langMenu(anchor) {
  let m = document.getElementById("langmenu"); if (m) { m.remove(); return; }
  m = document.createElement("div"); m.id = "langmenu"; m.setAttribute("role", "menu");
  Object.keys(LANGN).forEach(k => { const b = document.createElement("button"); b.type = "button"; b.textContent = LANGN[k];
    if (k === (typeof LANG !== "undefined" ? LANG : "")) b.className = "on";
    b.onclick = () => langSet(k); m.appendChild(b); });
  document.body.appendChild(m);
  let r = anchor ? anchor.getBoundingClientRect() : null;
  if (!r || !r.width) r = {right: innerWidth - 10, bottom: 56};          // the button is hidden (compact header): top right
  m.style.top = Math.round(r.bottom + 6) + "px"; m.style.right = Math.max(8, Math.round(innerWidth - r.right)) + "px";
  setTimeout(() => { const off = e => { if (!m.contains(e.target)) { m.remove(); removeEventListener("pointerdown", off, true); } };
    addEventListener("pointerdown", off, true); }, 0);
}
"""   # in the first script of every page (the language button and the setup assistant use it)


def norm_lang(lang):
    lang = str(lang or "").lower()[:2]
    return lang if lang in LANGS else "en"


def cur_lang(lang=None):
    return norm_lang(lang or CFG.get("lang") or "en")


def msg_defaults(lang=None):
    L = cur_lang(lang)
    return MSG_DEFAULTS.get(L) or MSG_DEFAULTS["de" if L == "rm" else "en"]


MSG_DEFAULTS = {
    "de": {"person": ("{name}: Person erkannt", "{count} Person(en) erkannt um {time} - Kamera: {camera}"),
           "prealarm": ("{name}: Bewegung (Voralarm)", "Voralarm: Bewegung um {time} - Kamera: {camera}"),
           "warm": ("{name}: Wärme erkannt", "Wärmebild: warmer Körper in der Zone um {time} - Kamera: {camera}"),
           "noise": ("{name}: Geräusch", "Geräusch-Alarm: laut ({db} dB) um {time} - Kamera: {camera}")},
    "en": {"person": ("{name}: person detected", "{count} person(s) detected at {time} - camera: {camera}"),
           "prealarm": ("{name}: movement (pre-alarm)", "Pre-alarm: movement at {time} - camera: {camera}"),
           "warm": ("{name}: warm body detected", "Thermal camera: warm body in the zone at {time} - camera: {camera}"),
           "noise": ("{name}: noise", "Noise alarm: loud ({db} dB) at {time} - camera: {camera}")},
}
MSG_PLACEHOLDERS = "{name} {time} {date} {count} {camera} {link} {db}"


def msg_template(kind, part):
    """Own text if set, otherwise the standard text in the language of the program. part = 0 title, 1 text."""
    own = CFG.get(f"msg_{kind}_{'title' if part == 0 else 'text'}", "")
    return own if own.strip() else msg_defaults()[kind][part]


def render_msg(tpl, p):
    t = p.get("time", "")
    vals = {"name": CFG["device_name"].strip() or "Motion Watch", "time": t[11:19], "count": str(p.get("persons", 0)),
            "date": f"{t[8:10]}.{t[5:7]}.{t[0:4]}" if len(t) >= 10 else "", "camera": p.get("source", ""), "link": p.get("link", ""),
            "db": str(p.get("db", ""))}
    return re.sub(r"\{(\w+)\}", lambda m: vals.get(m.group(1), m.group(0)), tpl)     # only known placeholders, nothing else


def _hdr(v):
    """HTTP headers are latin-1: umlauts / emoji go as RFC 2047 (ntfy understands that)."""
    import base64
    v = " ".join(str(v).split())
    return v if v.isascii() else "=?UTF-8?B?" + base64.b64encode(v.encode()).decode() + "?="


# ----------------------------------------------------------------------------
# Web push: alarm messages straight to the phone / PC browser - no extra app. The page must be opened over https (Tailscale:
#   «https über Tailscale» gives https://<name>.<tailnet>.ts.net with a real certificate); on the iPhone the page must be on the
#   home screen. Standard Web Push (RFC 8030 / 8291 / 8292) with python3-cryptography (part of Raspberry Pi OS).
# ----------------------------------------------------------------------------
WEBPUSH = {"lock": threading.Lock(), "subs": None, "key": None, "status": ""}


def _b64u(b):
    import base64
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()


def _b64u_dec(s_):
    import base64
    s_ = str(s_ or "")
    return base64.urlsafe_b64decode(s_ + "=" * (-len(s_) % 4))


def webpush_supported():
    try:
        import cryptography  # noqa: F401
        return True
    except ImportError:
        return False


def _wp_file(name):
    return os.path.join(DATA_DIR, name)


def webpush_key():
    """The server's own key pair (VAPID, P-256); made once and kept in the data folder (never sent anywhere)."""
    if WEBPUSH["key"] is not None:
        return WEBPUSH["key"]
    from cryptography.hazmat.primitives import serialization
    from cryptography.hazmat.primitives.asymmetric import ec
    p_ = _wp_file("webpush_vapid.pem")
    key = None
    try:
        with open(p_, "rb") as f:
            key = serialization.load_pem_private_key(f.read(), None)
    except (OSError, ValueError):
        key = ec.generate_private_key(ec.SECP256R1())
        try:
            fd = os.open(p_, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
            with os.fdopen(fd, "wb") as f:
                f.write(key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
        except OSError:
            pass
    WEBPUSH["key"] = key
    return key


def webpush_public():
    from cryptography.hazmat.primitives import serialization
    return _b64u(webpush_key().public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint))


def webpush_subs():
    with WEBPUSH["lock"]:
        if WEBPUSH["subs"] is None:
            try:
                with open(_wp_file("webpush_subs.json")) as f:
                    WEBPUSH["subs"] = [x for x in json.load(f) if isinstance(x, dict) and x.get("endpoint")][:50]
            except (OSError, ValueError):
                WEBPUSH["subs"] = []
        return list(WEBPUSH["subs"])


def _webpush_save(subs):
    with WEBPUSH["lock"]:
        WEBPUSH["subs"] = subs[:50]
        try:
            tmp = _wp_file("webpush_subs.json.part")
            with open(tmp, "w") as f:
                json.dump(WEBPUSH["subs"], f)
            os.replace(tmp, _wp_file("webpush_subs.json"))
        except OSError:
            pass


_WP_HOST = re.compile(r"^https://[A-Za-z0-9.\-]+(:\d+)?/[^\s]{1,900}$")


def webpush_add(sub, label=""):
    try:
        ep = str(sub["endpoint"]); keys = sub.get("keys") or {}
        p256, auth = _b64u_dec(keys["p256dh"]), _b64u_dec(keys["auth"])
    except (KeyError, TypeError, ValueError):
        return False, "invalid subscription"
    if not _WP_HOST.match(ep) or len(p256) != 65 or len(auth) != 16:
        return False, "invalid subscription"
    subs = [x for x in webpush_subs() if x["endpoint"] != ep]
    subs.append({"endpoint": ep, "p256dh": _b64u(p256), "auth": _b64u(auth), "label": str(label or "")[:60],
                 "added": datetime.now().strftime("%Y-%m-%d %H:%M")})
    _webpush_save(subs)
    log_event("web", f"Web push switched on for {str(label or 'a device')[:60]}")
    return True, ""


def webpush_remove(endpoint):
    subs = webpush_subs()
    new = [x for x in subs if x["endpoint"] != endpoint]
    _webpush_save(new)
    return len(new) != len(subs)


def _webpush_encrypt(payload, p256dh, auth):
    """RFC 8291 (aes128gcm): encrypt the message for one browser."""
    from cryptography.hazmat.primitives import hashes, hmac as chmac, serialization
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM

    def hm(key, data):
        h = chmac.HMAC(key, hashes.SHA256()); h.update(data); return h.finalize()
    ua_pub = _b64u_dec(p256dh); secret = _b64u_dec(auth)
    eph = ec.generate_private_key(ec.SECP256R1())
    as_pub = eph.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    shared = eph.exchange(ec.ECDH(), ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), ua_pub))
    ikm = hm(hm(secret, shared), b"WebPush: info\x00" + ua_pub + as_pub + b"\x01")
    salt = os.urandom(16)
    prk = hm(salt, ikm)
    cek = hm(prk, b"Content-Encoding: aes128gcm\x00\x01")[:16]
    nonce = hm(prk, b"Content-Encoding: nonce\x00\x01")[:12]
    ct = AESGCM(cek).encrypt(nonce, payload + b"\x02", None)
    return salt + (4096).to_bytes(4, "big") + bytes([len(as_pub)]) + as_pub + ct


def _vapid_header(endpoint):
    """RFC 8292: a short signed note (JWT, ES256) that says which server sends."""
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
    m = re.match(r"^(https://[^/]+)", endpoint)
    head = _b64u(json.dumps({"typ": "JWT", "alg": "ES256"}, separators=(",", ":")).encode())
    claims = _b64u(json.dumps({"aud": m.group(1), "exp": int(time.time()) + 12 * 3600, "sub": "mailto:motionwatch@example.invalid"},
                              separators=(",", ":")).encode())
    r, s_ = decode_dss_signature(webpush_key().sign((head + "." + claims).encode(), ec.ECDSA(hashes.SHA256())))
    jwt = head + "." + claims + "." + _b64u(r.to_bytes(32, "big") + s_.to_bytes(32, "big"))
    return f"vapid t={jwt}, k={webpush_public()}"


def webpush_send(sub, msg, ttl=86400, urgent=True):
    body_ = _webpush_encrypt(json.dumps(msg, ensure_ascii=False).encode()[:3000], sub["p256dh"], sub["auth"])
    req = urllib.request.Request(sub["endpoint"], data=body_, method="POST", headers={
        "Content-Encoding": "aes128gcm", "Content-Type": "application/octet-stream", "TTL": str(int(ttl)),
        "Urgency": "high" if urgent else "normal", "Authorization": _vapid_header(sub["endpoint"])})
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            return r.status
    except urllib.error.HTTPError as e:
        return e.code


def webpush_all(title, text, url="/", tag="mw", urgent=True):
    """Send to every browser that switched web push on; browsers that are gone (404 / 410) are removed."""
    subs = webpush_subs()
    if not subs or not webpush_supported():
        return 0
    ok = 0; gone = []
    for sb in subs:
        try:
            code = webpush_send(sb, {"title": title[:120], "body": text[:400], "url": url or "/", "tag": tag, "urgent": bool(urgent)},
                                urgent=urgent)
        except Exception as e:
            code = 0; WEBPUSH["status"] = f"error: {str(e)[:120]}"
        if code in (404, 410):
            gone.append(sb["endpoint"])
        elif 200 <= code < 300:
            ok += 1
    if gone:
        _webpush_save([x for x in webpush_subs() if x["endpoint"] not in gone])
        log_event("web", f"Web push: {len(gone)} device(s) no longer subscribed - removed")
    WEBPUSH["status"] = f"{datetime.now().strftime('%H:%M:%S')}: {ok}/{len(subs)}"
    return ok


def tailscale_https(on=True):
    """«https über Tailscale»: tailscale serve passes https://<name>.ts.net (real certificate) on to this page."""
    exe = shutil.which("tailscale")
    if not exe:
        return False, "Tailscale is not installed"
    args = ["serve", "--bg", str(CFG["web_port"])] if on else ["serve", "--https=443", "off"]
    err = ""
    for c in ([exe] + args, ["sudo", "-n", exe] + args):
        rc, out, e = _run(c, timeout=30)
        if rc == 0:
            log_event("web", "https over Tailscale " + ("switched on" if on else "switched off"))
            return True, ""
        err = (e or out or f"exit {rc}").strip()[:200]
    if "HTTPS" in err or "certificate" in err.lower():
        err += " - in the Tailscale admin page switch on «HTTPS certificates» (DNS)"
    return False, err


def tailscale_https_url():
    ts = tailscale_status()
    exe = shutil.which("tailscale")
    if not exe or ts.get("state") != "Running" or not ts.get("name"):
        return ""
    rc, out, _e = _run([exe, "serve", "status"], timeout=8)
    return f"https://{ts['name']}/" if rc == 0 and ts["name"] in (out or "") else ""


# ----------------------------------------------------------------------------
# Backup: copy finished alarm recordings away from the device (if it is stolen or broken the clips are safe):
#   WebDAV (Nextcloud, Synology / QNAP NAS, many clouds), a folder (USB stick, mounted NAS) or Telegram (video).
#   Waits until the recording is complete (also the sound), tries 3 times. One sub-folder per day.
# ----------------------------------------------------------------------------
class Backup:
    def __init__(self):
        self.q = queue.Queue(maxsize=200)
        threading.Thread(target=self.loop, daemon=True).start()

    def add(self, path, meta=None):
        if CFG.get("sim_on"):
            return
        if CFG["backup_type"] == "off" or not path:
            return
        try:
            self.q.put_nowait((path, dict(meta or {}), 0))
            STATE["backup_status"] = f"{tr('waiting')}: {os.path.basename(path)}"
        except queue.Full:
            log_event("rec", "Backup: too many recordings waiting - one skipped")

    def loop(self):
        while True:
            path, meta, tries = self.q.get()
            if not self._wait_ready(path):
                continue
            ok, err = backup_copy(path, meta)
            name = os.path.basename(path)
            if ok:
                STATE["backup_status"] = f"✓ {datetime.now().strftime('%H:%M')} {name}"
                log_event("rec", f"Backup: {name} copied ({CFG['backup_type']})")
            else:
                STATE["backup_status"] = f"⚠ {err}"[:200]
                log_event("rec", f"Backup of {name} failed: {err}"[:220])
                if tries < 2:
                    threading.Timer(60 * (1 + 4 * tries), lambda p_=path, m_=meta, t_=tries + 1: self._retry(p_, m_, t_)).start()

    def _retry(self, path, meta, tries):
        try:
            self.q.put_nowait((path, meta, tries))
        except queue.Full:
            pass

    @staticmethod
    def _wait_ready(path, limit=240):
        """The sound is added after the recording ends (the file is replaced) - wait until the file does not change for 6 s."""
        end = time.time() + limit; last = None; same = 0.0
        while time.time() < end:
            try:
                st = os.stat(path); cur = (st.st_size, st.st_mtime)
            except OSError:
                cur = None
            if cur and cur == last and time.time() - cur[1] > 4:
                same += 1
                if same >= 3:
                    return True
            else:
                same = 0
            last = cur; time.sleep(2)
        return os.path.isfile(path)


def _dav_request(url, method, data=None, length=None):
    import base64
    h = {}
    if CFG["backup_user"] or CFG["backup_password"]:
        h["Authorization"] = "Basic " + base64.b64encode(f"{CFG['backup_user']}:{CFG['backup_password']}".encode()).decode()
    if length is not None:
        h["Content-Length"] = str(length); h["Content-Type"] = "application/octet-stream"
    req = urllib.request.Request(url, data=data, method=method, headers=h)
    try:
        with urllib.request.urlopen(req, timeout=120) as r:
            return r.status
    except urllib.error.HTTPError as e:
        return e.code


def _shrink_video(path):
    """A smaller copy (640 px wide, lower quality) for services with a size limit. Returns the path or None."""
    if not shutil.which("ffmpeg"):
        return None
    dst = os.path.join(tempfile.gettempdir(), "mw_small_" + os.path.basename(path))
    try:
        r = subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", path, "-vf", "scale=640:-2", "-c:v", "libx264", "-preset", "veryfast",
                            "-crf", "32", "-c:a", "aac", "-b:a", "48k", "-movflags", "+faststart", dst], capture_output=True, timeout=900)
        if r.returncode == 0 and os.path.isfile(dst) and 0 < os.path.getsize(dst) < 49 * 1024 * 1024:
            return dst
    except (OSError, subprocess.SubprocessError):
        pass
    try:
        os.remove(dst)
    except OSError:
        pass
    return None


def backup_copy(path, meta=None, test=False):
    """Copy one file to the chosen place. test=True: a small text file to check the settings."""
    kind = CFG["backup_type"]
    day = datetime.now().strftime("%Y-%m-%d")
    name = os.path.basename(path) if path else "motionwatch_test.txt"
    dev = (CFG["device_name"] or "Motion Watch").strip()
    try:
        if test:
            data = f"Motion Watch {APP_VERSION} - backup test {datetime.now().isoformat(timespec='seconds')} ({dev})\n".encode()
        if kind == "folder":
            base = CFG["backup_folder"].strip()
            if not base.startswith("/"):
                return False, "no folder set"
            if not os.path.isdir(os.path.dirname(base.rstrip("/")) or "/"):
                return False, "folder not found (USB stick / NAS connected?)"
            dst = os.path.join(base, day); os.makedirs(dst, exist_ok=True)
            if test:
                with open(os.path.join(dst, name), "wb") as f:
                    f.write(data)
            else:
                shutil.copy2(path, os.path.join(dst, name) + ".part"); os.replace(os.path.join(dst, name) + ".part", os.path.join(dst, name))
            return True, ""
        if kind == "webdav":
            base = CFG["backup_url"].strip()
            if not base:
                return False, "no WebDAV folder set"
            base = base.rstrip("/") + "/"
            code = _dav_request(base, "MKCOL")
            if code in (401, 403):
                return False, f"login refused (HTTP {code}) - user name / app password?"
            code = _dav_request(base + day + "/", "MKCOL")
            if code not in (201, 405, 301, 200):
                return False, f"cannot create the day folder (HTTP {code})"
            if test:
                code = _dav_request(base + day + "/" + name, "PUT", data, len(data))
            else:
                size = os.path.getsize(path)
                with open(path, "rb") as f:
                    code = _dav_request(base + day + "/" + urllib.request.quote(name), "PUT", f, size)
            return (True, "") if code in (200, 201, 204) else (False, f"upload refused (HTTP {code})")
        if kind == "telegram":
            if not (CFG["telegram_token"] and CFG["telegram_chat"]):
                return False, "Telegram bot token / chat id missing (Notifications)"
            base = f"{TELEGRAM_API}/bot{CFG['telegram_token']}"
            b = uuid.uuid4().hex
            cap = f"{dev}: " + (("Test" if test else tr("recording") + " " + name))
            if test:
                req = urllib.request.Request(base + "/sendMessage", data=json.dumps({"chat_id": CFG["telegram_chat"], "text": cap + " ✓"}).encode(),
                                             headers={"Content-Type": "application/json"})
            else:
                is_pic = name.lower().endswith(".jpg")
                src, small = path, None
                if not is_pic and os.path.getsize(path) > 45 * 1024 * 1024:     # too big for Telegram: a smaller copy
                    small = _shrink_video(path)
                    if not small:
                        return False, "too big for Telegram (max. 50 MB) and could not be made smaller (ffmpeg?)"
                    src = small
                try:
                    with open(src, "rb") as f:
                        vid = f.read()
                finally:
                    if small:
                        try:
                            os.remove(small)
                        except OSError:
                            pass
                field, ctype, ep = ("photo", "image/jpeg", "/sendPhoto") if is_pic else ("video", "video/mp4", "/sendVideo")
                parts = [f'--{b}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode()
                         for k, v in (("chat_id", CFG["telegram_chat"]), ("caption", cap), ("supports_streaming", "true"))]
                parts.append((f'--{b}\r\nContent-Disposition: form-data; name="{field}"; filename="{name}"\r\nContent-Type: {ctype}\r\n\r\n').encode()
                             + vid + b"\r\n")
                parts.append(f"--{b}--\r\n".encode())
                req = urllib.request.Request(base + ep, data=b"".join(parts), headers={"Content-Type": "multipart/form-data; boundary=" + b})
            try:
                with urllib.request.urlopen(req, timeout=180) as r:
                    return (True, "") if r.status == 200 else (False, f"Telegram HTTP {r.status}")
            except urllib.error.HTTPError as e:
                return False, f"Telegram HTTP {e.code}"
        return False, "backup is off"
    except Exception as e:
        msg = str(e)
        for sec_ in (CFG["telegram_token"], CFG["backup_password"]):
            if sec_:
                msg = msg.replace(sec_, "***")
        return False, msg[:200]


BACKUP = None


# ----------------------------------------------------------------------------
# Theft / sabotage protection: camera covered or turned away (picture), device moved / knocked over (optional motion
#   sensor MPU-6050 / 6500 on I2C 0x68), power cut while armed. When armed: push message (high priority) + siren.
#   While the camera head moves itself (patrol, tracking, joystick, timelapse) the picture check waits and learns anew.
# ----------------------------------------------------------------------------
class TamperGuard:
    def __init__(self):
        self.ref = None; self.ref_mean = 0.0; self.t_last = 0.0; self.settle = time.time() + 15
        self.pos = None; self.n_cov = 0; self.n_mov = 0; self.cool = 0.0
        self.acc = None; self.base = None; self.n_tilt = 0; self.armed_was = None
        STATE["tamper"] = {"sensor": False, "last": "", "state": "learning"}
        threading.Thread(target=self.sensor_loop, daemon=True, name="tamper").start()

    # ---- picture: covered / turned ----
    def feed(self, small, t0):
        if not CFG["tamper_on"] or t0 - self.t_last < 1.0:
            return
        self.t_last = t0
        pos = (round(CFG["pan"], 1), round(CFG["tilt"], 1))
        if pos != self.pos or manual_active() or STATE.get("tracking") or STATE.get("patrol_moving") or TL_HOLD.get("on"):
            self.pos = pos; self.settle = t0 + 8; self.ref = None; self.n_cov = self.n_mov = 0
            STATE["tamper"]["state"] = "learning"; return
        if t0 < self.settle:
            return
        g = cv2.resize(cv2.cvtColor(small, cv2.COLOR_BGR2GRAY) if small.ndim == 3 else small, (80, 60), interpolation=cv2.INTER_AREA).astype(np.float32)
        mean, std = float(g.mean()), float(g.std())
        e = cv2.magnitude(cv2.Sobel(g, cv2.CV_32F, 1, 0), cv2.Sobel(g, cv2.CV_32F, 0, 1))
        if self.ref is None:
            self.ref, self.ref_e, self.ref_mean, self.ref_std = g, e, mean, std
            STATE["tamper"]["state"] = "watching"; return
        covered = mean < 18 and std < 7 and self.ref_mean > 35 and self.ref_std > 8
        a, b = e - e.mean(), self.ref_e - self.ref_e.mean()
        corr = float((a * b).sum() / (math.sqrt(float((a * a).sum()) * float((b * b).sum())) + 1e-6))
        moved = (not covered) and self.ref_std > 10 and std > 8 and corr < 0.3 and not STATE.get("persons")
        self.n_cov = self.n_cov + 1 if covered else 0
        self.n_mov = self.n_mov + 1 if moved else 0
        if self.n_cov >= 3:
            self.alarm("covered"); self.ref = None; self.n_cov = 0; self.settle = t0 + 10
        elif self.n_mov >= 5:
            self.alarm("turned"); self.ref = None; self.n_mov = 0; self.settle = t0 + 10
        elif not covered and corr > 0.6:                      # slowly follow the light of the day
            self.ref = self.ref * 0.9 + g * 0.1; self.ref_e = self.ref_e * 0.9 + e * 0.1
            self.ref_mean = self.ref_mean * 0.9 + mean * 0.1; self.ref_std = self.ref_std * 0.9 + std * 0.1

    # ---- motion sensor (MPU-6050 / 6500 / 9250 at I2C 0x68) ----
    @staticmethod
    def _mpu_open():
        import fcntl
        try:
            fd = os.open("/dev/i2c-1", os.O_RDWR)
        except OSError:
            return None
        try:
            fcntl.ioctl(fd, I2C_SLAVE, 0x68)
            os.write(fd, bytes([0x75])); who = os.read(fd, 1)[0]
            if who not in (0x68, 0x70, 0x71, 0x73):             # not a motion sensor (e.g. a clock chip at 0x68)
                os.close(fd); return None
            os.write(fd, bytes([0x6B, 0x00]))                    # wake up
            os.write(fd, bytes([0x1C, 0x00]))                    # +-2 g
            return fd
        except OSError:
            os.close(fd); return None

    @staticmethod
    def _mpu_read(fd):
        os.write(fd, bytes([0x3B])); b = os.read(fd, 6)
        v = [((b[i] << 8) | b[i + 1]) for i in (0, 2, 4)]
        return [(x - 65536 if x > 32767 else x) / 16384.0 for x in v]

    def sensor_loop(self):
        fd = None; tried = 0.0
        while True:
            time.sleep(0.5)
            if not CFG["tamper_motion"]:
                continue
            if fd is None:
                if time.time() - tried < 60:
                    continue
                tried = time.time(); fd = self._mpu_open()
                if fd is None:
                    STATE["tamper"]["sensor"] = False; continue
                STATE["tamper"]["sensor"] = True; self.base = None
                log_event("sys", "Motion sensor found (I2C 0x68) - alarm when the device is moved")
            try:
                a = self._mpu_read(fd)
            except OSError:
                try:
                    os.close(fd)
                except OSError:
                    pass
                fd = None; continue
            self.check_motion(a)

    def check_motion(self, a):
        armed = is_armed()
        n = math.sqrt(sum(x * x for x in a)) or 1.0
        if self.base is None or not armed or self.armed_was is False:
            self.base = [x / n for x in a]; self.armed_was = armed; self.n_tilt = 0; return
        self.armed_was = armed
        cos = sum(x / n * y for x, y in zip(a, self.base))
        ang = math.degrees(math.acos(max(-1.0, min(1.0, cos))))
        shake = abs(n - 1.0) > 0.45
        self.n_tilt = self.n_tilt + 1 if (ang > float(CFG["tamper_tilt"]) or shake) else 0
        if self.n_tilt >= 2:
            self.alarm("knocked" if ang > 60 else "moved"); self.n_tilt = 0
            self.base = [x / n for x in a]

    # ---- alarm ----
    def alarm(self, what):
        now = time.time()
        de = CFG["lang"] == "de"
        txt = {"covered": ("Kamera abgedeckt", "camera covered"), "turned": ("Kamera verdreht / Bild verändert", "camera turned / picture changed"),
               "moved": ("Gerät bewegt", "device moved"), "knocked": ("Gerät umgeworfen", "device knocked over"),
               "power": ("Strom getrennt (scharf)", "power cut while armed")}[what]
        STATE["tamper"]["last"] = datetime.now().strftime("%H:%M") + " " + tr(txt[1])
        log_event("sys", f"SABOTAGE: {txt[1]}" + ("" if is_armed() else " (disarmed - no alarm)"))
        if not is_armed() or now - self.cool < 120:
            return
        self.cool = now
        w = WATCH_REF["w"]
        if w is not None:
            w.notifier.tamper(tr(txt[1]), w.frame_out)
        siren_alarm("tamper")


TAMPER = None


# ----------------------------------------------------------------------------
# Lens check: dew at night, dust or a spider web make the picture blurred and flat. Every 15 s the sharpness (variance of the
#   Laplacian) and the contrast of a small grey picture; compared with what is normal for day or night (the best 20 % of the
#   last 24 hours). Clearly worse for 15 minutes = push message (at most every 6 hours).
# ----------------------------------------------------------------------------
class LensCheck:
    def __init__(self):
        self.t_last = 0.0; self.base = {True: deque(maxlen=6000), False: deque(maxlen=6000)}; self.recent = deque(maxlen=60)
        self.bad_since = 0.0; self.warned = 0.0; self.state = "learning"
        STATE["lens"] = {"state": "learning", "pct": None}

    def feed(self, small, t0):
        if not CFG["lens_check"]:
            STATE["lens"] = {"state": "off", "pct": None}; return
        if t0 - self.t_last < 15:
            return
        self.t_last = t0
        if manual_active() or STATE.get("tracking") or STATE.get("patrol_moving") or STATE.get("persons"):
            return
        g = cv2.resize(cv2.cvtColor(small, cv2.COLOR_BGR2GRAY) if small.ndim == 3 else small, (160, 120), interpolation=cv2.INTER_AREA)
        if float(g.mean()) < 12:
            return                                        # black: covered (theft protection) or no light at all
        sharp = float(cv2.Laplacian(g, cv2.CV_32F).var()); con = float(g.std())
        self.add(t0, sharp, con, bool(is_dark()))

    def add(self, t0, sharp, con, dark):
        b = self.base[dark]; b.append((t0, sharp, con))
        while b and t0 - b[0][0] > 86400:
            b.popleft()
        self.recent.append((t0, sharp, con, dark))
        rec = [x for x in self.recent if t0 - x[0] <= 600 and x[3] == dark]
        if len(b) < 240 or len(rec) < 20:                 # one hour of pictures before it judges
            STATE["lens"] = {"state": "learning", "pct": None}; return
        ss = sorted(x[1] for x in b); cs = sorted(x[2] for x in b)
        ref_s, ref_c = ss[int(len(ss) * 0.8)], cs[int(len(cs) * 0.8)]
        cur_s = sorted(x[1] for x in rec)[len(rec) // 2]; cur_c = sorted(x[2] for x in rec)[len(rec) // 2]
        pct = int(round(100.0 * cur_s / max(ref_s, 1e-3)))
        bad = cur_s < 0.35 * ref_s and cur_c < 0.8 * ref_c
        if bad:
            self.bad_since = self.bad_since or t0
            if t0 - self.bad_since >= 900 and self.state != "fogged":
                self.state = "fogged"
                log_event("sys", f"Lens fogged or dirty? Sharpness {pct} % of normal for 15 minutes")
                if t0 - self.warned > 6 * 3600:
                    self.warned = t0
                    w = WATCH_REF["w"]
                    if w is not None:
                        w.notifier.info(trf("The picture has been blurred for 15 minutes (sharpness {p} % of normal). Wipe the lens and look for dew or a spider web.", p=pct),
                                        title="{name}: " + tr("Lens fogged or dirty"))
        else:
            self.bad_since = 0.0
            if self.state == "fogged" and cur_s > 0.6 * ref_s:
                log_event("sys", "Lens: the picture is clear again")
            if self.state != "fogged" or cur_s > 0.6 * ref_s:
                self.state = "clear"
        STATE["lens"] = {"state": self.state, "pct": pct}


LENS = None


# ---- temperature alarm (the temperature sensor; e.g. a pet in the caravan) ----
TEMPA = {"state": "ok", "t": 0.0}


def temp_check(env):
    if not CFG["temp_alarm_on"] or not env or env.get("t") is None:
        TEMPA["state"] = "ok"; return
    t, hot, cold = float(env["t"]), float(CFG["temp_hot"]), float(CFG["temp_cold"])
    prev = TEMPA["state"]
    st = "hot" if t >= hot else "cold" if t <= cold else ("ok" if cold + 1.0 < t < hot - 1.0 else prev)   # 1 °C hysteresis
    now = time.time(); w = WATCH_REF["w"]
    if st in ("hot", "cold") and (st != prev or now - TEMPA["t"] >= 2 * 3600):
        TEMPA["t"] = now
        txt = trf("Too hot: {t:.1f} °C (limit {l:.0f} °C)", t=t, l=hot) if st == "hot" else trf("Too cold: {t:.1f} °C (limit {l:.0f} °C)", t=t, l=cold)
        log_event("sys", f"TEMPERATURE ALARM: {t:.1f} °C ({st})")
        if w is not None:
            w.notifier.alert("{name}: " + tr("TEMPERATURE ALARM"), txt, None)
    elif st == "ok" and prev in ("hot", "cold"):
        log_event("sys", f"Temperature fine again: {t:.1f} °C")
        if w is not None:
            w.notifier.info(trf("Temperature fine again: {t:.1f} °C", t=t), title="{name}: " + tr("Temperature"))
    TEMPA["state"] = st


# ----------------------------------------------------------------------------
# Climate: temperature / humidity / air pressure sensor (BME280 / BMP280 at I2C 0x76 / 0x77, or DS18B20 on 1-Wire GPIO 4).
#   Read every 30 s; every 10 minutes one line goes into <data>/climate/YYYY-MM-DD.json (also CPU temperature and battery)
#   - the day overview of the diary draws its curves from there. The sensor must sit outside the warm housing.
# ----------------------------------------------------------------------------
class EnvSensor:
    def __init__(self):
        self.fd = None; self.addr = None; self.cal = None; self.bmp = False; self.tried = 0.0; self.last_log = 0.0
        STATE["env"] = None
        threading.Thread(target=self.loop, daemon=True, name="climate").start()

    # ---- BME280 / BMP280 ----
    def _rd(self, reg, n):
        os.write(self.fd, bytes([reg])); return os.read(self.fd, n)

    def _open(self):
        import fcntl, struct
        try:
            fd = os.open("/dev/i2c-1", os.O_RDWR)
        except OSError:
            return False
        for addr in (0x76, 0x77):
            try:
                fcntl.ioctl(fd, I2C_SLAVE, addr)
                os.write(fd, bytes([0xD0])); cid = os.read(fd, 1)[0]
                if cid not in (0x60, 0x58):
                    continue
                self.fd, self.addr, self.bmp = fd, addr, cid == 0x58
                c = self._rd(0x88, 24)
                T1, T2, T3, P1, P2, P3, P4, P5, P6, P7, P8, P9 = struct.unpack("<HhhHhhhhhhhh", c)
                H1 = H2 = H3 = H4 = H5 = H6 = 0
                if not self.bmp:
                    H1 = self._rd(0xA1, 1)[0]
                    h = self._rd(0xE1, 7)
                    H2 = struct.unpack("<h", h[0:2])[0]; H3 = h[2]
                    H4 = (struct.unpack("b", h[3:4])[0] << 4) | (h[4] & 0x0F)
                    H5 = (struct.unpack("b", h[5:6])[0] << 4) | (h[4] >> 4)
                    H6 = struct.unpack("b", h[6:7])[0]
                self.cal = (T1, T2, T3, P1, P2, P3, P4, P5, P6, P7, P8, P9, H1, H2, H3, H4, H5, H6)
                log_event("sys", f"Climate sensor {'BMP280' if self.bmp else 'BME280'} found (I2C 0x{addr:02x})")
                return True
            except OSError:
                continue
        os.close(fd)
        return False

    def _bme(self):
        T1, T2, T3, P1, P2, P3, P4, P5, P6, P7, P8, P9, H1, H2, H3, H4, H5, H6 = self.cal
        if not self.bmp:
            os.write(self.fd, bytes([0xF2, 0x01]))                       # humidity x1
        os.write(self.fd, bytes([0xF4, 0x25]))                           # temperature x1, pressure x1, one measurement
        time.sleep(0.05)
        d = self._rd(0xF7, 8)
        adc_p = (d[0] << 12) | (d[1] << 4) | (d[2] >> 4); adc_t = (d[3] << 12) | (d[4] << 4) | (d[5] >> 4); adc_h = (d[6] << 8) | d[7]
        v1 = (adc_t / 16384.0 - T1 / 1024.0) * T2
        v2 = ((adc_t / 131072.0 - T1 / 8192.0) ** 2) * T3
        tf = v1 + v2; t = tf / 5120.0
        v1 = tf / 2.0 - 64000.0; v2 = v1 * v1 * P6 / 32768.0 + v1 * P5 * 2.0; v2 = v2 / 4.0 + P4 * 65536.0
        v1 = (P3 * v1 * v1 / 524288.0 + P2 * v1) / 524288.0; v1 = (1.0 + v1 / 32768.0) * P1
        pr = None
        if v1:
            pp = 1048576.0 - adc_p; pp = (pp - v2 / 4096.0) * 6250.0 / v1
            v1 = P9 * pp * pp / 2147483648.0; v2 = pp * P8 / 32768.0; pr = (pp + (v1 + v2 + P7) / 16.0) / 100.0
        hum = None
        if not self.bmp:
            h = tf - 76800.0
            h = (adc_h - (H4 * 64.0 + H5 / 16384.0 * h)) * (H2 / 65536.0 * (1.0 + H6 / 67108864.0 * h * (1.0 + H3 / 67108864.0 * h)))
            hum = max(0.0, min(100.0, h * (1.0 - H1 * h / 524288.0)))
        return t, hum, pr

    # ---- DS18B20 ----
    @staticmethod
    def _ds18b20():
        out = []
        for path in sorted(glob.glob("/sys/bus/w1/devices/28-*")):
            try:
                with open(os.path.join(path, "w1_slave")) as f:
                    txt = f.read()
                if "YES" in txt and "t=" in txt:
                    v = int(txt.rsplit("t=", 1)[1]) / 1000.0
                    if -55 < v < 125 and v != 85.0:                   # 85.0 = the power-on value, not a measurement
                        out.append(round(v, 2))
            except (OSError, ValueError):
                continue
        return out

    def read(self):
        if CFG.get("sim_on") and time.time() - SIM["t"] < 10:
            return {"t": round(float(SIM["ambient"]), 1), "h": None, "p": round(float(SIM["pressure"]), 1), "src": "Simulator", "ds": [], "time": time.time()}
        if self.fd is None and time.time() - self.tried > 120:
            self.tried = time.time(); self._open()
        t = hum = pr = None; src = ""
        if self.fd is not None:
            try:
                t, hum, pr = self._bme(); src = "BMP280" if self.bmp else "BME280"
            except (OSError, ZeroDivisionError):
                try:
                    os.close(self.fd)
                except OSError:
                    pass
                self.fd = None
        ds = self._ds18b20()
        if t is None and ds:
            t, src = ds[0], "DS18B20"
        if t is None:
            return None
        off = float(CFG["env_offset"])
        return {"t": round(t + off, 1), "h": round(hum) if hum is not None else None, "p": round(pr, 1) if pr else None,
                "src": src, "ds": [round(x + off, 1) for x in ds], "time": time.time()}

    def loop(self):
        while True:
            try:
                STATE["env"] = self.read() if CFG["env_on"] else None
                temp_check(STATE["env"])
                if time.time() - self.last_log >= 600:
                    self.last_log = time.time(); climate_log(STATE["env"])
            except Exception as e:
                log_event("sys", f"Climate sensor: {e}"[:160])
            time.sleep(30)


def climate_dir():
    return os.path.join(DATA_DIR, "climate")


def climate_log(env):
    """One line every 10 minutes: time, temperature, humidity, pressure, CPU temperature, battery (%)."""
    bt = STATE.get("battery") or {}
    row = [datetime.now().strftime("%H:%M"), env["t"] if env else None, env["h"] if env else None, env["p"] if env else None,
           STATE.get("cpu_temp"), bt.get("pct") if bt.get("on") else None]
    path = os.path.join(climate_dir(), datetime.now().strftime("%Y-%m-%d") + ".json")
    try:
        os.makedirs(climate_dir(), exist_ok=True)
        try:
            with open(path) as f:
                rows = json.load(f)
        except (OSError, ValueError):
            rows = []
        rows.append(row)
        with open(path + ".tmp", "w") as f:
            json.dump(rows, f, separators=(",", ":"))
        os.replace(path + ".tmp", path)
        keep = max(30, int(CFG["diary_keep_days"]))
        cut = (datetime.now() - timedelta(days=keep)).strftime("%Y-%m-%d")
        for p_ in glob.glob(os.path.join(climate_dir(), "*.json")):
            if os.path.basename(p_)[:10] < cut:
                os.remove(p_)
    except OSError:
        pass


def climate_day(day):
    try:
        with open(os.path.join(climate_dir(), day + ".json")) as f:
            return json.load(f)
    except (OSError, ValueError):
        return []


ENV = None


# ---- weather from the internet (Open-Meteo, free, no account) for the day overview of the diary ----
WMO = [((0,), "☀️", "clear"), ((1, 2), "🌤", "partly cloudy"), ((3,), "☁️", "cloudy"), ((45, 48), "🌫", "fog"), ((51, 53, 55, 56, 57), "🌦", "drizzle"),
       ((61, 63, 65, 66, 67), "🌧", "rain"), ((71, 73, 75, 77, 85, 86), "🌨", "snow"), ((80, 81, 82), "🌦", "showers"), ((95, 96, 99), "⛈", "thunderstorm")]
WEATHER = {"t": 0.0, "status": "off"}


def wmo_text(code):
    for codes, icon, key in WMO:
        if code in codes:
            return icon, key
    return "·", ""


def weather_dir():
    return os.path.join(DATA_DIR, "weather")


def weather_fetch():
    """The last 7 days and today, hour by hour, one file per day (kept like the diary)."""
    g = gps_now()
    if not g:
        WEATHER["status"] = "no location"; return False
    url = ("https://api.open-meteo.com/v1/forecast?latitude=%.3f&longitude=%.3f&timezone=auto&past_days=7&forecast_days=2"
           "&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,wind_speed_10m_max,wind_gusts_10m_max"
           "&hourly=temperature_2m,precipitation,relative_humidity_2m,weather_code,wind_gusts_10m" % (g[0], g[1]))
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
        with urllib.request.urlopen(req, timeout=20) as r:
            j = json.loads(r.read().decode())
    except Exception as e:
        WEATHER["status"] = f"failed: {e}"[:120]; return False
    weather_store(j)
    WEATHER["t"] = time.time(); WEATHER["status"] = "ok"
    return True


def weather_store(j):
    dl, hl = j.get("daily") or {}, j.get("hourly") or {}
    days = {}
    for i, day in enumerate(dl.get("time") or []):
        days[day] = {"daily": {k: (dl.get(k) or [None] * (i + 1))[i] for k in dl if k != "time"}, "hourly": {}}
    for i, ts in enumerate(hl.get("time") or []):
        day, hh = ts[:10], ts[11:13]
        if day in days:
            days[day]["hourly"][hh] = [(hl.get(k) or [None] * (i + 1))[i] for k in ("temperature_2m", "precipitation", "relative_humidity_2m", "weather_code", "wind_gusts_10m")]
    os.makedirs(weather_dir(), exist_ok=True)
    for day, v in days.items():
        with open(os.path.join(weather_dir(), day + ".json"), "w") as f:
            json.dump(v, f, separators=(",", ":"))


def weather_day(day):
    try:
        with open(os.path.join(weather_dir(), day + ".json")) as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


def weather_loop():
    time.sleep(90)
    while True:
        if CFG["weather_on"] or (CFG["storm_on"] and CFG["storm_forecast"]):
            if time.time() - WEATHER["t"] > 3 * 3600:
                weather_fetch()
        else:
            WEATHER["status"] = "off"
        time.sleep(120)


def moon_phase(d):
    """(emoji, name) of the moon phase on a date (mean lunar month since a known new moon)."""
    age = ((datetime(d.year, d.month, d.day, 12) - datetime(2000, 1, 6, 18, 14)).total_seconds() / 86400.0) % 29.530588853
    names = ((1.84, "🌑", "new moon"), (5.53, "🌒", "waxing crescent"), (9.23, "🌓", "first quarter"), (12.92, "🌔", "waxing gibbous"),
             (16.61, "🌕", "full moon"), (20.30, "🌖", "waning gibbous"), (23.99, "🌗", "last quarter"), (27.68, "🌘", "waning crescent"), (30, "🌑", "new moon"))
    for lim, icon, name in names:
        if age < lim:
            return icon, name


def day_summary(day, lang="en"):
    """Everything about one day for the diary: visits, recordings, climate curve, weather, sun, moon, place, night report."""
    try:
        d = datetime.strptime(day, "%Y-%m-%d")
    except ValueError:
        return None
    sight_load()
    with SIGHT_LOCK:
        ev = [dict(e) for e in SIGHT["list"] if e["start"][:10] == day]
    ev.sort(key=lambda e: e["start"])
    counts = {}
    for e in ev:
        counts[e["label"]] = counts.get(e["label"], 0) + 1
    animals = sorted(((k, c) for k, c in counts.items() if k in ANIMALS), key=lambda x: -x[1])
    best = sorted((e for e in ev if e.get("img") and e["kind"] == "animal"), key=lambda e: (e.get("fav", False), e.get("conf", 0)), reverse=True)[:4]
    stamp = d.strftime("%Y%m%d"); recs = 0; mb = 0.0; photos = 0; alarm_recs = 0
    try:
        for n in os.listdir(rec_dir()):
            if stamp in n:
                if n.endswith(".mp4"):
                    recs += 1
                    try:
                        mb += os.path.getsize(os.path.join(rec_dir(), n)) / 1048576.0
                        with open(os.path.join(rec_dir(), n[:-4] + ".json")) as f:
                            alarm_recs += 1 if json.load(f).get("persons") else 0
                    except (OSError, ValueError):
                        pass
                elif n.endswith(".jpg"):
                    photos += 1
    except OSError:
        pass
    g = next((e["gps"] for e in ev if e.get("gps")), None)
    if g is None:
        gg = gps_now(); g = [gg[0], gg[1]] if gg else None
    lat, lon = (g[0], g[1]) if g else (float(CFG["latitude"]), float(CFG["longitude"]))
    st = sun_times(d.date(), lat, lon)
    sun = {"rise": f"{int(st[0] // 60):02d}:{int(st[0] % 60):02d}", "set": f"{int(st[1] // 60):02d}:{int(st[1] % 60):02d}",
           "len": f"{int((st[1] - st[0]) // 60)} h {int((st[1] - st[0]) % 60):02d}"} if isinstance(st, tuple) else {"polar": st}
    mi, mn = moon_phase(d)
    w = weather_day(day) if CFG["weather_on"] or weather_day(day) else None
    if w:
        dd = w.get("daily") or {}
        icon, key = wmo_text(dd.get("weather_code"))
        w = {"icon": icon, "text": tr(key, lang) if key else "", "tmax": dd.get("temperature_2m_max"), "tmin": dd.get("temperature_2m_min"),
             "rain": dd.get("precipitation_sum"), "wind": dd.get("wind_speed_10m_max"), "gust": dd.get("wind_gusts_10m_max"), "hourly": w.get("hourly") or {}}
    rep_txt = ""
    if d.date() <= datetime.now().date():
        hr, fr = int(CFG["report_hour"]) % 24, int(CFG["report_from"]) % 24
        end = d.replace(hour=hr); start = end - timedelta(hours=((hr - fr) % 24) or 24)
        if end > datetime.now():
            end = datetime.now()
        if start < end:
            rep_txt = report_build(lang, start, end)["text"]
    clim = climate_day(day)
    temps = [r[1] for r in clim if r[1] is not None]
    hums = [r[2] for r in clim if r[2] is not None]
    press = [r[3] for r in clim if r[3] is not None]
    return {"day": day, "weekday": d.weekday(),
            "counts": {"persons": counts.get("person", 0), "animals": sum(c for _k, c in animals), "warm": counts.get("warm", 0),
                       "noise": counts.get("noise", 0), "sneezes": (sneeze_count() and _SNEEZE_DAYS["days"].get(day, 0)) or _SNEEZE_DAYS["days"].get(day, 0), "recordings": recs, "alarm_recordings": alarm_recs, "photos": photos, "mb": round(mb, 1)},
            "animals": [{"key": k, "label": tr_trigger(k, lang), "count": c} for k, c in animals],
            "best": [{"img": e["img"], "label": tr_trigger(e["label"], lang), "t": e["start"][11:16]} for e in best],
            "events": [{"t": e["start"][11:16], "kind": e["kind"], "label": tr_trigger(e["label"], lang) if e["kind"] in ("animal", "person", "object") else tr(e["label"], lang)} for e in ev][:400],
            "climate": clim,
            "climate_sum": {"tmin": min(temps) if temps else None, "tmax": max(temps) if temps else None, "hmin": min(hums) if hums else None,
                            "hmax": max(hums) if hums else None, "pmin": min(press) if press else None, "pmax": max(press) if press else None},
            "weather": w, "weather_on": bool(CFG["weather_on"]), "weather_status": WEATHER["status"],
            "sun": sun, "moon": {"icon": mi, "name": tr(mn, lang)}, "gps": g, "report": rep_txt}


class Notifier:
    """Alarm message when a person is detected (with cooldown). Three kinds:
         webhook   JSON POST to a URL (Home Assistant, IFTTT, ...)
         ntfy      push to the ntfy app: the snapshot is attached, a tap opens the recordings page
         telegram  photo + caption to a Telegram chat (bot token + chat id)"""
    def __init__(self):
        self.last = 0.0; self.last_pre = 0.0; self.last_warm = 0.0; self.last_noise = 0.0

    @staticmethod
    def main_configured():
        if CFG["notify_type"] == "telegram":
            return bool(CFG["telegram_token"] and CFG["telegram_chat"])
        return bool(CFG["notify_url"].strip())

    @staticmethod
    def configured():
        return Notifier.main_configured() or bool(CFG["webpush_on"] and webpush_subs()) or bool(CFG["sms_on"] and sms_numbers())

    def person(self, count, snapshot_path=None, frame=None):
        if count and not is_armed():
            STATE["notify_status"] = "disarmed"; return
        if not self.configured():
            STATE["notify_status"] = "off"; return
        if not CFG["notify_on"]:
            STATE["notify_status"] = "paused"; return
        now = time.time()
        if now - self.last < CFG["notify_cooldown"]:
            return
        self.last = now
        jpg, fname = None, "snapshot.jpg"
        try:
            if snapshot_path and os.path.isfile(snapshot_path) and os.path.getsize(snapshot_path) < 8 * 1024 * 1024:
                with open(snapshot_path, "rb") as f:
                    jpg = f.read()
                fname = os.path.basename(snapshot_path)
            elif frame is not None:
                ok, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 85])
                jpg = buf.tobytes() if ok else None
        except OSError:
            jpg = None
        pub = CFG["public_url"].strip().rstrip("/")
        payload = {"event": "person" if count else "test", "persons": int(count), "time": datetime.now().isoformat(timespec="seconds"),
                   "snapshot": snapshot_path, "rain": bool(STATE["rain_mode"]), "wind": STATE["wind_level"],
                   "source": STATE["source_label"], "link": pub + "/recordings" if pub else ""}
        threading.Thread(target=self._dispatch, args=(payload, jpg, fname), daemon=True).start()

    def test(self, frame):
        self.last = 0.0
        self.person(0, None, frame)

    def prealarm(self, frame, event="prealarm"):
        """Pre-alarm push: something moves in the picture. Own cooldown; skipped right after a person alarm (that one says more).
        The picture is small (640 px) so it costs little mobile data. event="warm": the thermal camera saw a warm body,
        event="noise": the microphone heard a noise."""
        want = {"warm": True, "noise": CFG["noise_push"]}.get(event, CFG["notify_prealarm"])
        if not (want and CFG["notify_on"] and self.configured() and is_armed()):
            return False
        now = time.time()
        if event == "warm":
            if now - self.last_warm < CFG["notify_cooldown"]:
                return False
            self.last_warm = now
        elif event == "noise":
            if now - self.last_noise < CFG["notify_cooldown"]:
                return False
            self.last_noise = now
        else:
            if now - self.last_pre < CFG["prealarm_cooldown"] or now - self.last < CFG["prealarm_cooldown"]:
                return False
            self.last_pre = now
        jpg = None
        if CFG["prealarm_photo"] and frame is not None:
            h, w = frame.shape[:2]
            small = cv2.resize(frame, (640, int(h * 640 / w)), interpolation=cv2.INTER_AREA) if w > 640 else frame
            ok, buf = cv2.imencode(".jpg", small, [cv2.IMWRITE_JPEG_QUALITY, 70])
            jpg = buf.tobytes() if ok else None
        pub = CFG["public_url"].strip().rstrip("/")
        payload = {"event": event, "persons": 0, "time": datetime.now().isoformat(timespec="seconds"), "snapshot": None,
                   "rain": bool(STATE["rain_mode"]), "wind": STATE["wind_level"], "source": STATE["source_label"],
                   "link": pub + "/" if pub else ""}
        if event == "noise" and AUDIO is not None and AUDIO.level is not None:
            payload["db"] = int(round(AUDIO.level))
        threading.Thread(target=self._dispatch, args=(payload, jpg, "prealarm.jpg"), daemon=True).start()
        return True

    def tamper(self, text, frame=None):
        """Sabotage / theft alarm: always sent (no cooldown of the person alarm), high priority, with the current picture."""
        if not (self.configured() and CFG["notify_on"]):
            return False
        jpg = None
        if frame is not None:
            ok, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 75]); jpg = buf.tobytes() if ok else None
        pub = CFG["public_url"].strip().rstrip("/")
        payload = {"event": "tamper", "persons": 0, "time": datetime.now().isoformat(timespec="seconds"), "text": text,
                   "info_title": "{name}: " + tr("TAMPER ALARM"),
                   "snapshot": None, "rain": False, "wind": "", "source": STATE["source_label"], "link": pub + "/" if pub else ""}
        threading.Thread(target=self._dispatch, args=(payload, jpg, "tamper.jpg"), daemon=True).start()
        return True

    def alert(self, title, text, frame=None):
        """Urgent alarm with a custom title (extra sensors): like the sabotage alarm."""
        if not (self.configured() and CFG["notify_on"]):
            return False
        jpg = None
        if frame is not None:
            ok, buf = cv2.imencode(".jpg", frame, [cv2.IMWRITE_JPEG_QUALITY, 75]); jpg = buf.tobytes() if ok else None
        pub = CFG["public_url"].strip().rstrip("/")
        payload = {"event": "tamper", "persons": 0, "time": datetime.now().isoformat(timespec="seconds"), "text": text, "info_title": title,
                   "snapshot": None, "rain": False, "wind": "", "source": STATE["source_label"], "link": pub + "/" if pub else ""}
        threading.Thread(target=self._dispatch, args=(payload, jpg, "alarm.jpg"), daemon=True).start()
        return True

    def info(self, text, link="", title="", jpg=None, fname="info.jpg"):
        """Short information message (e.g. the new address of the page, the night report). Not limited by the alarm cooldown."""
        if not (self.configured() and CFG["notify_on"]):
            return False
        payload = {"event": "info", "persons": 0, "time": datetime.now().isoformat(timespec="seconds"), "text": text, "info_title": title,
                   "snapshot": None, "rain": False, "wind": "", "source": STATE["source_label"], "link": link}
        threading.Thread(target=self._dispatch, args=(payload, jpg, fname if jpg else ""), daemon=True).start()
        return True

    @staticmethod
    def _event(p):
        return p.get("event") if p.get("event") in ("person", "prealarm", "info", "warm", "noise", "tamper") else "test"

    @staticmethod
    def _title(p):
        t_ = Notifier._title0(p)
        return ("[SIM] " + t_) if CFG.get("sim_on") else t_

    @staticmethod
    def _title0(p):
        ev = Notifier._event(p)
        if ev == "tamper":
            return render_msg(p.get("info_title"), p)
        if ev == "info":
            return render_msg(p.get("info_title") or ("{name}: " + tr("network")), p)
        if ev == "test":                                  # the test shows your own person message
            return "[Test] " + render_msg(msg_template("person", 0), dict(p, persons=1))
        return render_msg(msg_template(ev, 0), p)

    @staticmethod
    def _text(p):
        ev = Notifier._event(p)
        if ev in ("info", "tamper"):
            return p.get("text", "")
        if ev == "test":
            return render_msg(msg_template("person", 1), dict(p, persons=1))
        return render_msg(msg_template(ev, 1), p)

    def _dispatch(self, p, jpg, fname):
        if CFG["webpush_on"] and webpush_subs():
            threading.Thread(target=self._webpush, args=(p,), daemon=True).start()
        ev = self._event(p)
        if CFG["sms_on"] and ev in ("person", "tamper", "warm", "noise", "test") and sms_numbers():
            offline = STATE.get("net", {}).get("online") is False
            if not CFG["sms_only_offline"] or offline or not self.main_configured() or ev == "test":
                threading.Thread(target=lambda: sms_send(self._title(p) + ": " + self._text(p), force=ev == "test"), daemon=True).start()
        if not self.main_configured():
            return
        kind, secret = CFG["notify_type"], CFG["telegram_token"]
        try:
            if kind == "telegram":
                code = self._telegram(p, jpg, fname); where = "Telegram"
            elif kind == "ntfy":
                code = self._ntfy(p, jpg, fname); where = "ntfy " + CFG["notify_url"][:40]
            else:
                url = CFG["notify_url"].strip()
                body_ = dict(p, title=self._title(p), text=self._text(p))
                req = urllib.request.Request(url, data=json.dumps(body_).encode(),
                                             headers={"Content-Type": "application/json", "Title": _hdr(self._title(p))})
                with urllib.request.urlopen(req, timeout=8) as r:
                    code = r.status
                where = url[:40]
            STATE["notify_status"] = f"sent {datetime.now().strftime('%H:%M:%S')} (HTTP {code})"
            log_event("web", f"Notification sent to {where}… (HTTP {code})")
        except Exception as e:
            msg = str(e).replace(secret, "***") if secret else str(e)
            STATE["notify_status"] = f"error: {msg}"[:200]
            log_event("web", f"Notification failed: {msg}"[:200])

    def _webpush(self, p):
        ev = self._event(p)
        try:
            n = webpush_all(self._title(p), self._text(p), "/" if ev != "info" else (p.get("link") or "/"), tag="mw-" + ev,
                            urgent=ev in ("person", "warm", "noise", "test", "tamper"))
            log_event("web", f"Web push sent to {n} device(s)")
        except Exception as e:
            log_event("web", f"Web push failed: {str(e)[:150]}")

    def _ntfy(self, p, jpg, fname):
        ev = self._event(p)
        h = {"Title": _hdr(self._title(p)), "Tags": {"person": "warning,camera", "prealarm": "eyes,camera", "info": "signal_strength", "warm": "fire,camera",
                                   "noise": "loud_sound,ear", "tamper": "rotating_light,warning"}.get(ev, "camera"),
             "Priority": {"person": "high", "warm": "high", "noise": "high", "prealarm": "default", "tamper": "urgent"}.get(ev, "default")}
        if p["link"]:
            h["Click"] = p["link"]
        text = self._text(p)
        if jpg:
            h["Filename"] = fname; h["Message"] = _hdr(text); h["Content-Type"] = "image/jpeg"
            req = urllib.request.Request(CFG["notify_url"].strip(), data=jpg, headers=h, method="PUT")
        else:
            req = urllib.request.Request(CFG["notify_url"].strip(), data=text.encode(), headers=h, method="POST")
        with urllib.request.urlopen(req, timeout=15) as r:
            return r.status

    def _telegram(self, p, jpg, fname):
        base = f"{TELEGRAM_API}/bot{CFG['telegram_token']}"
        body_txt = self._text(p)
        text = self._title(p) + "\n" + body_txt + (("\n" + p["link"]) if p["link"] and p["link"] not in body_txt else "")
        if jpg:
            b = uuid.uuid4().hex
            parts = []
            for k, v in (("chat_id", CFG["telegram_chat"]), ("caption", text)):
                parts.append(f'--{b}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode())
            parts.append((f'--{b}\r\nContent-Disposition: form-data; name="photo"; filename="{fname}"\r\n'
                          f'Content-Type: image/jpeg\r\n\r\n').encode() + jpg + b"\r\n")
            parts.append(f"--{b}--\r\n".encode())
            req = urllib.request.Request(base + "/sendPhoto", data=b"".join(parts), headers={"Content-Type": "multipart/form-data; boundary=" + b})
        else:
            req = urllib.request.Request(base + "/sendMessage", data=json.dumps({"chat_id": CFG["telegram_chat"], "text": text}).encode(),
                                         headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=15) as r:
            return r.status


# ----------------------------------------------------------------------------
# Hardware: servos + relays  (gpiozero -> pigpio -> simulation)
# ----------------------------------------------------------------------------
# ----------------------------------------------------------------------------
# PCA9685: 16-channel PWM chip on I2C (Adafruit board). Drives the two servos (50 Hz, no jitter - the Pi 5 can only make
#   servo pulses in software) and switches the lights (channel fully on / off: no flicker in the video).
#   Talks to /dev/i2c-1 directly, no extra library. I2C must be on (sudo raspi-config -> Interface Options -> I2C).
# ----------------------------------------------------------------------------
I2C_SLAVE = 0x0703
SERVO_MOVE = {"t": 0.0}            # time of the last servo movement (the noise alarm ignores the servo motors)


class PCA9685:
    def __init__(self, addr, bus=1, freq=50.0):
        import fcntl
        self.addr, self.freq = addr, float(freq)
        self.fd = os.open(f"/dev/i2c-{bus}", os.O_RDWR)
        try:
            fcntl.ioctl(self.fd, I2C_SLAVE, addr)
            # read-only check first: MODE2 bits 7..5 are always 0 and ALLCALLADR is 0xE0 after power-on. Anything else at
            # this address (e.g. the thermal camera on 0x40) must not get our register writes.
            if self._r(0x01) & 0xE0 or self._r(0x05) != 0xE0:
                raise OSError(f"the chip at 0x{addr:02x} is not a PCA9685")
            pre = int(round(25e6 / (4096 * self.freq))) - 1
            self._w(0x00, 0x10)                    # sleep: needed to change the prescaler
            self._w(0xFE, pre)
            self._w(0x01, 0x04)                    # MODE2: totem-pole outputs
            self._w(0x00, 0x20)                    # wake up, register auto-increment
            time.sleep(0.005)
            self._w(0x00, 0xA0)                    # restart the PWM
            if self._r(0xFE) != pre:
                raise OSError("PCA9685 does not answer correctly")
        except Exception:
            os.close(self.fd); raise

    def _w(self, reg, val):
        os.write(self.fd, bytes([reg, val & 0xFF]))

    def _r(self, reg):
        os.write(self.fd, bytes([reg]))
        return os.read(self.fd, 1)[0]

    def _set(self, ch, on, off):
        os.write(self.fd, bytes([0x06 + 4 * ch, on & 0xFF, (on >> 8) & 0xFF, off & 0xFF, (off >> 8) & 0xFF]))

    def pulse_us(self, ch, us):
        self._set(ch, 0, max(0, min(4095, int(round(us * 4096 * self.freq / 1e6)))))

    def switch(self, ch, on):
        self._set(ch, 0x1000, 0) if on else self._set(ch, 0, 0x1000)       # bit 12 = fully on / fully off

    def close(self):
        try:
            os.write(self.fd, bytes([0xFA, 0, 0, 0, 0x10]))                    # all channels off (servos go limp)
        except OSError:
            pass
        try:
            os.close(self.fd)
        except OSError:
            pass


def pca_present(addr, bus=1):
    try:
        p = PCA9685.__new__(PCA9685)
        import fcntl
        p.fd = os.open(f"/dev/i2c-{bus}", os.O_RDWR)
        try:
            fcntl.ioctl(p.fd, I2C_SLAVE, addr)
            return not (p._r(0x01) & 0xE0) and p._r(0x05) == 0xE0
        finally:
            os.close(p.fd)
    except Exception:
        return False


# ----------------------------------------------------------------------------
# Mover (from 2.94.0): an optional tracked vehicle under Motion Watch - forward, back, turn on the spot with a second stick.
#   Motor driver: a «Motor HAT» with a PCA9685 and two TB6612 motor bridges on I2C (Adafruit DC & Stepper Motor HAT, default
#   0x60, or the Waveshare Motor Driver HAT). Found by itself (setting «automatic»); not found = no second stick anywhere.
#   In the simulation the 3D simulator says whether it has a mover («Mover simulieren»); the tracks are driven there.
#   Safety: without a new command for 0.6 s (page closed, Wi-Fi gone) both tracks stop; starting and stopping are gentle.
# ----------------------------------------------------------------------------
MOVER = {"test": False, "avail": False, "hw": False, "sim": False, "v": 0.0, "w": 0.0, "l": 0.0, "r": 0.0, "cmd_t": 0.0, "by": "", "msg": "off"}
MOVER_MAP = {"adafruit": ((8, 10, 9), (13, 11, 12)),      # (PWM, IN1, IN2) of the left and the right motor (M1, M2)
             "waveshare": ((0, 1, 2), (5, 3, 4))}          # (PWMA, AIN1, AIN2), (PWMB, BIN1, BIN2)
MOVERCTL = None


def mover_drive(v, w, who="web"):
    """the second stick: v = forward (+) / back (-), w = turn right (+) / left (-), both -1 … 1"""
    try:
        v = max(-1.0, min(1.0, float(v))); w = max(-1.0, min(1.0, float(w)))
    except (TypeError, ValueError):
        return False
    if not MOVER["avail"]:
        return False
    MOVER.update(v=v, w=w, cmd_t=time.time(), by=who)
    if abs(v) > 0.05 or abs(w) > 0.05:
        MANUAL["until"] = time.time() + CFG["manual_hold"]          # driving pauses tracking and patrol like the camera stick
        mover_sim_wake()
    return True


_MOVER_WAKE = {"t": 0.0}


def mover_sim_wake():
    """driving in the simulation, but the simulator's vehicle is off: switch it on there (3D simulator: «Mover simulieren»)"""
    now = time.time()
    if not (CFG.get("sim_on") and SIM.get("ok")) or SIM.get("mover") or now - _MOVER_WAKE["t"] < 8.0:
        return
    _MOVER_WAKE["t"] = now

    def work():
        try:
            d = sim_control()
            if any(c.get("id") == "mover_on" for c in (d.get("controls") or [])):
                sim_control({"action": "set", "id": "mover_on", "value": True})
                log_event("sys", "Simulation: vehicle switched on in the simulator (driven with the second stick)")
        except Exception:
            pass
    threading.Thread(target=work, daemon=True, name="mover-wake").start()


def mover_choice_pairs(extra):
    if extra == "mover_mode":
        return [("auto", tr("automatic: on when the motor driver is found")), ("off", tr("off"))]
    if extra == "mover_driver":
        return [("adafruit", tr("Motor HAT (Adafruit or compatible): M1 left, M2 right")),
                ("waveshare", tr("Waveshare Motor Driver HAT: A left, B right"))]
    if extra == "mover_addr":
        return [(f"0x{a:02x}", f"0x{a:02x}") for a in list(range(0x60, 0x70)) + list(range(0x40, 0x48))]
    return []


class MoverControl:
    def __init__(self):
        self.pca = None; self.addr = None; self.next_look = 0.0
        threading.Thread(target=self.loop, daemon=True, name="mover").start()

    def _close(self):
        if self.pca is not None:
            try:
                self.pca.close()
            except Exception:
                pass
        self.pca = None; self.addr = None

    def _find(self):
        """the motor driver at its address (not the one of the servos)"""
        try:
            a = int(str(CFG["mover_addr"]), 16)
        except ValueError:
            a = 0x60
        if self.pca is not None and self.addr == a:
            return True
        self._close()
        try:
            if str(CFG.get("pca_address", "")).lower() == f"0x{a:02x}" and CFG.get("servo_driver") != "gpio":
                MOVER["msg"] = "the address is the one of the servo driver"; return False
        except Exception:
            pass
        if not pca_present(a):
            MOVER["msg"] = "no motor driver found"; return False
        try:
            self.pca = PCA9685(a, freq=1600.0); self.addr = a
            MOVER["msg"] = "motor driver found"
            return True
        except Exception as e:
            MOVER["msg"] = "motor driver: " + str(e)[:60]; self.pca = None
            return False

    def _motor(self, pins, s):
        pwm, in1, in2 = pins
        s = max(-1.0, min(1.0, s))
        if abs(s) < 0.02:
            self.pca.switch(in1, False); self.pca.switch(in2, False); self.pca._set(pwm, 0, 0x1000)
            return
        self.pca.switch(in1, s > 0); self.pca.switch(in2, s < 0)
        self.pca._set(pwm, 0, max(0, min(4095, int(abs(s) * 4095))))

    def loop(self):
        last = time.time()
        while True:
            time.sleep(0.05)
            now = time.time(); dt = min(0.2, now - last); last = now
            sim = bool(CFG.get("sim_on"))
            if CFG["mover_mode"] == "off":
                self._close(); MOVER.update(avail=False, hw=False, test=False, msg="off")
            elif sim:
                self._close(); MOVER["hw"] = False
                real = bool(SIM.get("ok")) and bool(SIM.get("mover"))
                MOVER["avail"] = real or bool(CFG.get("mover_sim_show"))        # stick for a look even without a mover (2.94.4)
                MOVER["test"] = MOVER["avail"] and not real
                MOVER["msg"] = "simulated" if real else ("stick shown for testing (the simulator has no mover)" if MOVER["avail"] else "the simulator has no mover")
            else:
                MOVER["test"] = False
                if self.pca is None and now >= self.next_look:
                    self.next_look = now + 15.0
                    self._find()
                MOVER["hw"] = self.pca is not None; MOVER["avail"] = MOVER["hw"]
            MOVER["sim"] = sim and MOVER["avail"]
            # target from the stick (stops by itself without new commands), gentle change
            fresh = now - MOVER["cmd_t"] < 0.6
            tv = MOVER["v"] if fresh and MOVER["avail"] else 0.0
            tw = MOVER["w"] if fresh and MOVER["avail"] else 0.0
            sp = float(CFG["mover_speed"]) / 100.0; tu = float(CFG["mover_turn"]) / 100.0
            tl, trr = tv * sp + tw * tu, tv * sp - tw * tu
            m = max(1.0, abs(tl), abs(trr)); tl /= m; trr /= m
            ramp = float(CFG["mover_ramp"])
            k = 1.0 if ramp <= 0.01 else dt / ramp
            stop_fast = not fresh                                  # connection gone: stop quickly (4 × faster)
            k2 = min(1.0, k * (4.0 if stop_fast else 1.0))
            l = MOVER["l"] + max(-k2, min(k2, tl - MOVER["l"]))
            r = MOVER["r"] + max(-k2, min(k2, trr - MOVER["r"]))
            MOVER["l"], MOVER["r"] = round(l, 3), round(r, 3)
            if self.pca is not None and not sim:
                ml, mr = l, r
                if CFG["mover_swap"]:
                    ml, mr = mr, ml
                if CFG["mover_inv_l"]:
                    ml = -ml
                if CFG["mover_inv_r"]:
                    mr = -mr
                pins = MOVER_MAP.get(CFG["mover_driver"], MOVER_MAP["adafruit"])
                try:
                    self._motor(pins[0], ml); self._motor(pins[1], mr)
                except OSError as e:
                    MOVER["msg"] = "motor driver: " + str(e)[:60]; self._close()


# ----------------------------------------------------------------------------
# Lights: white + infrared (850 nm), each on a PCA9685 channel or a GPIO (with a MOSFET). Off / On / Auto.
#   Auto: "dark" = the whole night (sunset - sunrise from latitude / longitude), "alarm_dark" = after an alarm, only at night,
#   "alarm" = after an alarm, day and night. An alarm = person, warm body or noise while armed; the light stays on light_hold s.
# ----------------------------------------------------------------------------
LIGHTS = {"alarm_t": 0.0, "dark": False, "dark_t": 0.0, "strobe_until": 0.0}
LIGHT_MODES = ("off", "on", "auto")
LIGHT_NAMES = {"white": "White light", "ir": "Infrared light"}


def is_dark():
    if CFG.get("sim_on") and time.time() - SIM["t"] < 10:
        return bool(SIM["dark"])                           # the simulated world decides day and night
    now = time.time()
    if now - LIGHTS["dark_t"] > 60:
        LIGHTS["dark_t"] = now
        try:
            d = datetime.now()
            st = sun_times(d.date(), float(CFG["latitude"]), float(CFG["longitude"]))
            if isinstance(st, str):
                LIGHTS["dark"] = st == "dark"
            else:
                m = d.hour * 60 + d.minute
                LIGHTS["dark"] = m < st[0] or m > st[1]
        except Exception:
            pass
    return LIGHTS["dark"]


def light_alarm():
    LIGHTS["alarm_t"] = time.time()


def lights_tick():
    now = time.time(); dark = is_dark()
    alarm = LIGHTS["alarm_t"] > 0 and now - LIGHTS["alarm_t"] < float(CFG["light_hold"])
    res = {}
    for n in ("white", "ir"):
        if PAUSING["on"]:
            res[n] = False; continue
        m, a = CFG["light_" + n], CFG[f"light_{n}_auto"]
        res[n] = (bool(CFG[f"light_{n}_out"]) or bool(CFG["sim_on"])) and (m == "on" or (m == "auto" and (
            (a == "dark" and dark) or (a == "alarm_dark" and alarm and dark) or (a == "alarm" and alarm))))
    strobe = now < LIGHTS.get("strobe_until", 0.0) and not PAUSING["on"]
    if strobe and CFG["light_white_out"]:
        res["white"] = int(now * 5) % 2 == 0                 # deterrence: white light flashes 2.5 times a second
    prev = STATE.get("lights") or {}
    for n in ("white", "ir"):
        if bool(prev.get(n)) != res[n] and not (strobe and n == "white"):
            log_event("relay", f"{LIGHT_NAMES[n]} {'ON' if res[n] else 'OFF'}")
    STATE["lights"] = dict(res, dark=dark)
    return res


def light_set(name, mode):
    if name not in ("white", "ir") or mode not in LIGHT_MODES:
        return False, "invalid value"
    CFG["light_" + name] = mode
    save_settings()
    return True, ""


def light_out_pairs(name):
    """Where a light is connected: a free PCA9685 channel or a free GPIO (not a servo, relay or thermal camera pin)."""
    other = CFG["light_ir_out" if name == "white" else "light_white_out"]
    pairs = [("", "– " + tr("not connected") + " –")]
    used_ch = {int(CFG["pca_pan_ch"]), int(CFG["pca_tilt_ch"])}
    pairs += [(f"pca:{c}", f"PCA9685 {tr('channel')} {c}") for c in range(16) if c not in used_ch and f"pca:{c}" != other]
    used = {r["gpio"] for r in RELAYS} | set(GPIO_RESERVED) | set(thermal_gpios())
    pairs += [(f"gpio:{g}", f"GPIO {g}") for g in sorted(FREE_GPIOS) if g not in used and f"gpio:{g}" != other]
    cur = CFG[f"light_{name}_out"]
    if cur and cur not in [p[0] for p in pairs]:
        pairs.append((cur, cur.replace("pca:", "PCA9685 ").replace("gpio:", "GPIO ")))
    return pairs


def thermal_gpios():
    """GPIOs of the Waveshare thermal camera (reset, data ready, chip select) while it is selected."""
    return (23, 24, 7) if str(CFG.get("thermal_source", "")).startswith("senxor") else ()


# ----------------------------------------------------------------------------
# Waveshare Thermal-90 / Thermal-44 (80 x 62, Meridian MI48 "SenXor"): SPI for the pictures, I2C (0x40) for the settings,
#   GPIO 23 = reset, 24 = data ready, 7 = chip select. Uses the driver of Waveshare (pysenxor, from their wiki:
#   Thermal_Camera_Hat.zip -> pysenxor-master -> pip install -e ./). /boot/firmware/config.txt: dtparam=spi=on +
#   dtoverlay=spi0-0cs, I2C on. The picture is the temperature in degrees per pixel (float).
# ----------------------------------------------------------------------------
class SenxorSource:
    size = (80, 62)

    def __init__(self, i2c_addr=0x40, fps=15):
        try:
            from senxor.mi48 import MI48
            from senxor.interfaces import SPI_Interface, I2C_Interface
            from senxor.utils import data_to_frame
        except ImportError:
            raise RuntimeError("Waveshare driver missing: Thermal_Camera_Hat.zip from the Waveshare wiki, "
                               "then in pysenxor-master: pip install -e ./")
        try:
            from smbus import SMBus
        except ImportError:
            from smbus2 import SMBus
        from spidev import SpiDev
        from gpiozero import DigitalInputDevice, DigitalOutputDevice
        self._to_frame = data_to_frame
        self.cs = DigitalOutputDevice("BCM7", active_high=False, initial_value=False)
        self.ready = DigitalInputDevice("BCM24", pull_up=False)
        self.rst = DigitalOutputDevice("BCM23", active_high=False, initial_value=True)
        spi = SPI_Interface(SpiDev(0, 0), xfer_size=160)
        spi.device.mode = 0b00; spi.device.lsbfirst = False; spi.device.bits_per_word = 8
        spi.device.max_speed_hz = 31200000; spi.device.cshigh = True
        i2c = I2C_Interface(SMBus(1), i2c_addr)
        rst = self.rst

        def reset():
            rst.on(); time.sleep(0.000035); rst.off(); time.sleep(0.05)
        self.mi48 = MI48([i2c, spi], data_ready=self.ready, reset_handler=reset)
        try:
            self.mi48.set_fps(fps)
        except Exception:
            pass
        try:
            if int(str(self.mi48.fw_version[0])) >= 2:
                self.mi48.enable_filter(f1=True, f2=True, f3=False)
                self.mi48.set_offset_corr(0.0)
        except Exception:
            pass
        self.mi48.start(stream=True, with_header=True)
        self.shape = getattr(self.mi48, "fpa_shape", (80, 62))

    def read(self):
        try:
            if not self.ready.wait_for_active(timeout=1.0):
                return False, None
            self.cs.on(); time.sleep(0.0001)
            data, _header = self.mi48.read()
            time.sleep(0.0001); self.cs.off()
        except Exception:
            try:
                self.cs.off()
            except Exception:
                pass
            return False, None
        if data is None:
            return False, None
        fr = np.asarray(self._to_frame(data, self.shape), dtype=np.float32)
        if fr.size and float(np.median(fr)) > 200:          # deci-Kelvin -> degrees Celsius (older driver versions)
            fr = fr / 10.0 - 273.15
        STATE["thermal_max"] = round(float(np.max(fr)), 1)
        return True, fr

    def release(self):
        for f in (lambda: self.mi48.stop(), self.cs.close, self.ready.close, self.rst.close):
            try:
                f()
            except Exception:
                pass


HW_REINIT = {"want": False}


class Hardware:
    """Pan/tilt servos + any number of relay outputs + lights. Servo backends: PCA9685 -> gpiozero -> pigpio -> simulation."""
    def __init__(self):
        self.backend = "simulation"; self.io = "none"        # io = what switches the relays / GPIO lights
        self._OutputDevice = None
        self.pan = self.tilt = self.pi = self.pca = None
        self.outs = {}              # gpio -> {"dev": gpiozero device or None, "on": bool, "al": bool}
        self.fail = {}              # gpio -> time of last error (retried after 5 s)
        self._last_servo = None; self._pca_lights = {}
        self._init_backend()
        threading.Thread(target=self.loop, daemon=True).start()

    def _close_backend(self):
        for d in (self.pan, self.tilt):
            try:
                if d is not None:
                    d.close()
            except Exception:
                pass
        if self.pca is not None:
            self.pca.close()
        self.pan = self.tilt = self.pca = None; self._pca_lights = {}; self._last_servo = None

    def _init_backend(self):
        """PCA9685 (if chosen / found) for the servos; relays and GPIO lights always via gpiozero (or pigpio)."""
        self._close_backend(); self.backend = "simulation"
        drv, msg = CFG["servo_driver"], ""
        try:
            addr = int(str(CFG["pca_address"]), 16)
        except ValueError:
            addr = 0x41
        if drv in ("auto", "pca9685"):
            if drv == "auto" and addr == 0x40 and str(CFG["thermal_source"]).startswith("senxor"):
                msg = "PCA9685 on 0x40 = address of the thermal camera - change the PCA9685 to 0x41"
            elif drv == "pca9685" or pca_present(addr):
                try:
                    self.pca = PCA9685(addr)
                except Exception as e:
                    msg = f"PCA9685 0x{addr:02x}: {e}"
        try:
            from gpiozero import Servo, OutputDevice
            self._OutputDevice = OutputDevice
            self.io = "gpiozero"
            if self.pca is None and drv != "pca9685":
                mn, mx = CFG["servo_min_us"] / 1e6, CFG["servo_max_us"] / 1e6
                self.pan = Servo(GPIO_PAN, min_pulse_width=mn, max_pulse_width=mx)
                self.tilt = Servo(GPIO_TILT, min_pulse_width=mn, max_pulse_width=mx)
                self.backend = "gpiozero"
        except Exception as e1:
            try:
                import pigpio
                if self.pi is None:
                    self.pi = pigpio.pi()
                if not self.pi.connected:
                    raise RuntimeError("pigpiod not running")
                self._pigpio = pigpio; self.io = "pigpio"
                if self.pca is None and drv != "pca9685":
                    self.backend = "pigpio"
            except Exception:
                if self.pca is None:
                    log_event("servo", f"No servo hardware ({type(e1).__name__}) - simulation mode")
        if self.pca is not None:
            self.backend = "pca9685"
        elif self.pan is None and self.backend != "pigpio" or drv == "pca9685":
            self.backend = "simulation"
        STATE["servo_backend"] = self.backend + (f" ({msg})" if msg else "")
        where = (f"PCA9685 0x{self.pca.addr:02x} ch {CFG['pca_pan_ch']}/{CFG['pca_tilt_ch']}" if self.pca is not None
                 else f"pan GPIO{GPIO_PAN}, tilt GPIO{GPIO_TILT}")
        log_event("servo", f"Servo backend: {self.backend}  ({where}, relays GPIO {', '.join(str(r['gpio']) for r in RELAYS) or '-'})"
                           + (f" - {msg}" if msg else ""))

    def _us(self, pct):
        return CFG["servo_min_us"] + (CFG["servo_max_us"] - CFG["servo_min_us"]) * pct / 100.0

    def _servos(self, pan, tilt):
        if CFG["invert_pan"]: pan = 100 - pan
        if CFG["invert_tilt"]: tilt = 100 - tilt
        if self.pca is not None:
            self.pca.pulse_us(int(CFG["pca_pan_ch"]), self._us(pan))
            self.pca.pulse_us(int(CFG["pca_tilt_ch"]), self._us(tilt))
        elif self.backend == "gpiozero":
            self.pan.value = pan / 50.0 - 1.0
            self.tilt.value = tilt / 50.0 - 1.0
        elif self.backend == "pigpio":
            self.pi.set_servo_pulsewidth(GPIO_PAN, self._us(pan))
            self.pi.set_servo_pulsewidth(GPIO_TILT, self._us(tilt))

    def _write(self, gpio, on, al):
        ent = self.outs.get(gpio)
        if self.io == "gpiozero":
            if ent is None or ent["al"] != al:
                if ent is not None and ent["dev"] is not None:
                    ent["dev"].close()
                    self.outs.pop(gpio, None)
                ent = {"dev": self._OutputDevice(gpio, active_high=not al, initial_value=False), "on": False, "al": al}
                self.outs[gpio] = ent
            ent["dev"].on() if on else ent["dev"].off()
        else:
            if ent is None:
                if self.io == "pigpio":
                    self.pi.set_mode(gpio, self._pigpio.OUTPUT)
                ent = {"dev": None, "on": False, "al": al}
                self.outs[gpio] = ent
            if self.io == "pigpio":
                self.pi.write(gpio, int(bool(on)) ^ int(bool(al)))
        ent["on"], ent["al"] = on, al

    def _release(self, gpio):
        ent = self.outs.pop(gpio, None)
        if not ent:
            return
        try:
            if self.io == "gpiozero" and ent["dev"] is not None:
                ent["dev"].off(); ent["dev"].close()
            elif self.io == "pigpio":
                self.pi.write(gpio, 1 if ent["al"] else 0)          # inactive level
        except Exception:
            pass

    @staticmethod
    def limits():
        """(lo, hi) in percent for pan and tilt from the limits in degrees (middle = 50 %, 0..100 % = servo_range degrees)."""
        out = []
        for k in ("pan_limit", "tilt_limit"):
            half = servo_half("pan" if k == "pan_limit" else "tilt")
            d = max(0.0, min(50.0, float(CFG[k]) / half * 50.0))
            out.append((50.0 - d, 50.0 + d))
        return out

    def _lights(self, wanted):
        """Lights: PCA9685 channel (switched here) or GPIO (added to the outputs like a relay)."""
        res = lights_tick()
        for n in ("white", "ir"):
            out, on = CFG[f"light_{n}_out"], res[n]
            prev = self._pca_lights.get(n)
            if prev and prev[0] != out and self.pca is not None:          # output changed: switch the old channel off
                try:
                    self.pca.switch(int(prev[0][4:]), False)
                except Exception:
                    pass
                self._pca_lights.pop(n, None); prev = None
            if out.startswith("pca:"):
                if self.pca is not None and prev != (out, on):
                    try:
                        self.pca.switch(int(out[4:]), on); self._pca_lights[n] = (out, on)
                    except Exception as e:
                        log_event("servo", f"Light error: {e}")
            elif out.startswith("gpio:"):
                g = int(out[5:])
                if g not in wanted:
                    wanted[g] = (on, False)

    def loop(self):
        """50 Hz: push pan/tilt, all relay states and the lights to the hardware when they change."""
        while True:
            if HW_REINIT["want"]:
                HW_REINIT["want"] = False
                try:
                    self._init_backend()
                except Exception as e:
                    log_event("servo", f"Servo driver: {e}")
            (plo, phi), (tlo, thi) = self.limits()
            pan = max(plo, min(phi, float(CFG["pan"])))
            tilt = max(tlo, min(thi, float(CFG["tilt"])))
            if abs(pan - CFG["pan"]) > 0.05:
                CFG["pan"] = round(pan, 2)                # the page / window shows where the camera really is
            if abs(tilt - CFG["tilt"]) > 0.05:
                CFG["tilt"] = round(tilt, 2)
            cur = (round(pan, 1), round(tilt, 1))
            if cur != self._last_servo:
                try:
                    self._servos(pan, tilt)
                except Exception as e:
                    log_event("servo", f"Servo error: {e}")
                self._last_servo = cur; SERVO_MOVE["t"] = time.time()
            wanted = {g: (on, al) for g, on, al in STATE["relay_out"]}
            try:
                self._lights(wanted)
            except Exception as e:
                log_event("servo", f"Light error: {e}")
            for g in [g for g in self.outs if g not in wanted]:
                self._release(g)
            now = time.time()
            for g, (on, al) in wanted.items():
                ent = self.outs.get(g)
                if ent is not None and ent["on"] == on and ent["al"] == al:
                    continue
                if now - self.fail.get(g, 0.0) < 5.0:
                    continue
                try:
                    self._write(g, on, al); self.fail.pop(g, None)
                except Exception as e:
                    self.fail[g] = now
                    log_event("servo", f"Relay GPIO{g} error: {e}")
            time.sleep(0.02)




# ----------------------------------------------------------------------------
# System monitor: CPU load (+ temperature) sampled once per second
# ----------------------------------------------------------------------------
# ----------------------------------------------------------------------------
# Remote access (Tailscale): who watches from outside right now
#   Tailscale addresses are 100.64.0.0/10 and fd7a:115c:a1e0::/48. A device counts as "watching" while it streams the
#   video or has asked the page for news in the last 20 s. Names come from "tailscale status --json" (every 30 s).
# ----------------------------------------------------------------------------
_TS_NETS = (ipaddress.ip_network("100.64.0.0/10"), ipaddress.ip_network("fd7a:115c:a1e0::/48"))
REMOTE = {"seen": {}, "streams": {}, "names": {}}
REMOTE_LOCK = threading.Lock()


def is_remote_ip(ip):
    try:
        a = ipaddress.ip_address((ip or "").split("%")[0])
        if getattr(a, "ipv4_mapped", None):
            a = a.ipv4_mapped
        return any(a.version == n.version and a in n for n in _TS_NETS)
    except ValueError:
        return False


def remote_touch(ip):
    if is_remote_ip(ip):
        with REMOTE_LOCK:
            REMOTE["seen"][ip] = time.time()


def remote_stream(ip, delta):
    if is_remote_ip(ip):
        with REMOTE_LOCK:
            n = REMOTE["streams"].get(ip, 0) + delta
            if n > 0:
                REMOTE["streams"][ip] = n
            else:
                REMOTE["streams"].pop(ip, None)
            REMOTE["seen"][ip] = time.time()


def tailscale_status():
    """{'state': 'Running' | 'NeedsLogin' | 'Stopped' | '' (not installed), 'ip', 'name', 'peers': {ip: name}}"""
    exe = shutil.which("tailscale")
    if not exe:
        return {"state": "", "ip": "", "name": "", "peers": {}}
    try:
        r = subprocess.run([exe, "status", "--json"], capture_output=True, text=True, timeout=8)
        j = json.loads(r.stdout or "{}")
    except (OSError, subprocess.SubprocessError, ValueError):
        return {"state": "error", "ip": "", "name": "", "peers": {}}
    me = j.get("Self") or {}
    ips = me.get("TailscaleIPs") or []
    peers = {}
    for p in (j.get("Peer") or {}).values():
        nm = (p.get("HostName") or (p.get("DNSName") or "").split(".")[0] or "?")[:32]
        for ip in p.get("TailscaleIPs") or []:
            peers[ip] = nm
    return {"state": str(j.get("BackendState") or "")[:20], "ip": next((x for x in ips if ":" not in x), ips[0] if ips else ""),
            "name": (me.get("DNSName") or "").rstrip(".")[:80], "peers": peers}


class RemoteMonitor:
    """Keeps STATE["remote"] (names of devices watching from outside) and STATE["remote_ts"] up to date."""
    HOLD = 20.0

    def __init__(self):
        self._ts_t = 0.0; self._prev = set()
        threading.Thread(target=self.loop, daemon=True).start()

    def loop(self):
        while True:
            try:
                self.tick()
            except Exception as e:                           # never let this thread die
                log_event("sys", f"Remote access check: {e}")
            time.sleep(2.0)

    def tick(self):
        now = time.time()
        if now - self._ts_t > 30:
            self._ts_t = now
            ts = tailscale_status()
            with REMOTE_LOCK:
                REMOTE["names"] = ts.pop("peers")
            STATE["remote_ts"] = ts
        with REMOTE_LOCK:
            for ip in [ip for ip, t in REMOTE["seen"].items() if now - t > self.HOLD and ip not in REMOTE["streams"]]:
                REMOTE["seen"].pop(ip, None)
            active = set(REMOTE["seen"]) | set(REMOTE["streams"])
            names = {ip: REMOTE["names"].get(ip, ip) for ip in active}
        STATE["remote"] = sorted(set(names.values()))
        new = active - self._prev
        for ip in sorted(new):
            log_event("web", f"Remote access from {names[ip]} ({ip})")
        for ip in sorted(self._prev - active):
            log_event("web", f"Remote access ended: {REMOTE['names'].get(ip, ip)}")
        if new and not self._prev and CFG["notify_remote"]:
            w = WATCH_REF["w"]
            if w is not None:
                who = ", ".join(sorted({names[ip] for ip in new}))
                de = CFG["lang"] == "de"
                w.notifier.info(trf("Remote access: {who} is watching", who=who), title="{name}: " + tr("remote access"))
        self._prev = active


# ----------------------------------------------------------------------------
# Sightings: every "visit" of a person, an animal, a warm body or a noise is noted (start, end, best picture).
#   Used by the animal diary (/diary, the best picture of every animal visit) and the night report (push in the morning).
#   A visit ends when the label was not seen for 45 s. Pictures: <recordings>/diary/, list: <data>/sightings.json
# ----------------------------------------------------------------------------
SIGHT = {"list": [], "loaded": False}
SIGHT_LOCK = threading.Lock()
_DIARY_NAME = re.compile(r"^[0-9]{8}_[0-9]{6}_[a-z ]{2,20}_[0-9a-f]{6}\.jpg$")


def diary_dir():
    return os.path.join(rec_dir(), "diary")


def _sight_file():
    return os.path.join(DATA_DIR, "sightings.json")


def sight_kind(label):
    return "animal" if label in ANIMALS or label in SPECIES["labels"] else (label if label in ("person", "warm", "noise") else "object")


def sight_load():
    with SIGHT_LOCK:
        if SIGHT["loaded"]:
            return
        SIGHT["loaded"] = True
        try:
            with open(_sight_file()) as f:
                lst = json.load(f)
            SIGHT["list"] = [e for e in lst if isinstance(e, dict) and isinstance(e.get("label"), str) and isinstance(e.get("start"), str)][-5000:]
        except (OSError, ValueError):
            SIGHT["list"] = []


def _sight_save():
    try:
        tmp = _sight_file() + ".tmp"
        with open(tmp, "w") as f:
            json.dump(SIGHT["list"], f)
        os.replace(tmp, _sight_file())
    except OSError as e:
        log_event("sys", f"Sightings could not be saved: {e}")


def sight_purge():
    """Forget visits older than the keep time (favourites stay) and delete their pictures."""
    keep = max(7, int(CFG["diary_keep_days"]))
    limit = (datetime.now() - timedelta(days=keep)).isoformat(timespec="seconds")
    with SIGHT_LOCK:
        old = [e for e in SIGHT["list"] if e["start"] < limit and not e.get("fav")]
        if not old:
            return 0
        SIGHT["list"] = [e for e in SIGHT["list"] if not (e["start"] < limit and not e.get("fav"))]
        _sight_save()
    for e in old:
        if e.get("img"):
            for p in (os.path.join(diary_dir(), e["img"]), os.path.join(diary_dir(), ".thumbs", e["img"])):
                try:
                    os.remove(p)
                except OSError:
                    pass
    return len(old)


class SightingTracker:
    GAP = 45.0          # s without the label -> the visit is over
    MIN_FRAMES = 3      # seen in at least 3 pictures (a single wrong detection is no visit)

    def __init__(self):
        self.open = {}
        sight_load()
        self._purge_t = 0.0

    def see(self, label, t0, frame=None, box=None, conf=1.0, pw=1, ph=1):
        v = self.open.get(label)
        if v is None:
            v = self.open[label] = {"start": t0, "last": t0, "frames": 0, "score": 0.0, "jpg": None, "conf": 0.0, "img_t": 0.0}
        v["last"] = t0; v["frames"] += 1
        if frame is None or box is None or sight_kind(label) not in ("animal", "person"):
            return
        area = max(0.0, box[2] * box[3] / float(max(1, pw * ph)))
        score = float(conf) * min(1.0, area * 6.0) ** 0.5
        if score <= v["score"] * 1.05 or t0 - v["img_t"] < 0.5:
            return
        try:
            H, W = frame.shape[:2]; sx, sy = W / float(pw), H / float(ph)
            img = frame.copy()
            x, y, w, h = int(box[0] * sx), int(box[1] * sy), int(box[2] * sx), int(box[3] * sy)
            cv2.rectangle(img, (x, y), (x + w, y + h), (80, 200, 255), 2, cv2.LINE_AA)
            if W > 1280:
                img = cv2.resize(img, (1280, int(H * 1280 / W)), interpolation=cv2.INTER_AREA)
            ok, buf = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 85])
            if ok:
                v.update(score=score, jpg=buf.tobytes(), conf=float(conf), img_t=t0)
        except (cv2.error, ValueError):
            pass

    def tick(self, t0, force=False):
        for label in [k for k, v in self.open.items() if force or t0 - v["last"] > self.GAP]:
            v = self.open.pop(label)
            if v["frames"] >= self.MIN_FRAMES:
                self._store(label, v)
        if t0 - self._purge_t > 3600:
            self._purge_t = t0
            n = sight_purge()
            if n:
                log_event("rec", f"Diary: {n} old entries removed")

    def _store(self, label, v):
        st = datetime.fromtimestamp(v["start"])
        e = {"id": uuid.uuid4().hex[:6], "label": label, "kind": sight_kind(label),
             "start": st.isoformat(timespec="seconds"), "end": datetime.fromtimestamp(v["last"]).isoformat(timespec="seconds"),
             "dur": int(round(v["last"] - v["start"])), "conf": round(v["conf"], 2), "img": "", "fav": False}
        if v["jpg"]:
            name = f"{st.strftime('%Y%m%d_%H%M%S')}_{re.sub(r'[^a-z ]', '', label)[:20] or 'x'}_{e['id']}.jpg"
            try:
                os.makedirs(diary_dir(), exist_ok=True)
                with open(os.path.join(diary_dir(), name), "wb") as f:
                    f.write(v["jpg"])
                gps_tag_jpg(os.path.join(diary_dir(), name))
                e["img"] = name
                g = gps_now()
                if g:
                    e["gps"] = [round(g[0], 5), round(g[1], 5)]
            except OSError as ex:
                log_event("rec", f"Diary picture could not be saved: {ex}")
        with SIGHT_LOCK:
            SIGHT["list"].append(e)
            del SIGHT["list"][:-5000]
            _sight_save()
        if e["kind"] == "animal":
            log_event("rec", f"Diary: {label} ({e['dur']} s)")


def diary_items(label="", lang="en", fav=False):
    sight_load()
    with SIGHT_LOCK:
        lst = [dict(e) for e in SIGHT["list"] if e["kind"] == "animal" and e.get("img")]
    counts = {}
    for e in lst:
        counts[e["label"]] = counts.get(e["label"], 0) + 1
    if label:
        lst = [e for e in lst if e["label"] == label]
    if fav:
        lst = [e for e in lst if e.get("fav")]
    lst.sort(key=lambda e: e["start"], reverse=True)
    for e in lst:
        e["name"] = tr_trigger(e["label"], lang)
    labels = sorted(({"key": k, "label": tr_trigger(k, lang), "count": c} for k, c in counts.items()), key=lambda x: -x["count"])
    return {"items": lst[:600], "labels": labels, "total": sum(counts.values())}


def diary_action(action, eid, value=None):
    sight_load()
    with SIGHT_LOCK:
        e = next((x for x in SIGHT["list"] if x.get("id") == eid), None)
        if e is None:
            return False, "unknown entry"
        if action == "fav":
            e["fav"] = bool(value)
        elif action == "delete":
            SIGHT["list"].remove(e)
        else:
            return False, "unknown action"
        _sight_save()
    if action == "delete" and e.get("img"):
        for p in (os.path.join(diary_dir(), e["img"]), os.path.join(diary_dir(), ".thumbs", e["img"])):
            try:
                os.remove(p)
            except OSError:
                pass
    return True, ""


def diary_thumb(name):
    """Path of a 400 px picture of a diary entry (made once), or None."""
    if not _DIARY_NAME.match(name or ""):
        return None
    src = os.path.join(diary_dir(), name)
    if not os.path.isfile(src):
        return None
    tp = os.path.join(diary_dir(), ".thumbs", name)
    if not os.path.isfile(tp):
        try:
            img = cv2.imread(src)
            if img is None:
                return None
            h, w = img.shape[:2]
            os.makedirs(os.path.dirname(tp), exist_ok=True)
            cv2.imwrite(tp, cv2.resize(img, (400, max(1, int(h * 400 / w))), interpolation=cv2.INTER_AREA), [cv2.IMWRITE_JPEG_QUALITY, 75])
        except (OSError, cv2.error):
            return None
    return tp


# ---- night report -----------------------------------------------------------
def report_window(now=None):
    """(start, end) of the night the report is about: from <report_from> o'clock to <report_hour> o'clock.
    Before the report hour: the night so far."""
    now = now or datetime.now()
    hr, fr = int(CFG["report_hour"]) % 24, int(CFG["report_from"]) % 24
    span = (hr - fr) % 24 or 24
    end = now.replace(hour=hr, minute=0, second=0, microsecond=0)
    if now < end:
        return end - timedelta(hours=span), now
    return end - timedelta(hours=span), end


def report_build(lang=None, start=None, end=None):
    """Text + best picture (path) of the night report."""
    lang = cur_lang(lang)
    if start is None:
        start, end = report_window()
    a, b = start.isoformat(timespec="seconds"), end.isoformat(timespec="seconds")
    sight_load()
    with SIGHT_LOCK:
        ev = [dict(e) for e in SIGHT["list"] if a <= e["start"] < b]
    span = f"{start.strftime('%H')}–{end.strftime('%H')} " + tr("o'clock", lang)
    if not ev:
        return {"text": trf("Quiet night – nothing detected ({span}).", lang, span=span),
                "img": "", "count": 0, "from": a, "to": b}
    groups = {}
    for e in sorted(ev, key=lambda e: e["start"]):
        groups.setdefault(e["label"], []).append(e)
    order = sorted(groups, key=lambda k: ({"person": 0, "warm": 2, "noise": 3}.get(k, 1), -len(groups[k])))
    parts = []
    for k in order:
        times = [e["start"][11:16] for e in groups[k]]
        nm = tr_trigger(k, lang) if k not in ("warm", "noise") else (tr("thermal", lang) if k == "warm" else tr("noise", lang))
        nm = nm.split(" (")[0]
        parts.append(f"{nm} {len(times)}× ({', '.join(times[:4])}{' …' if len(times) > 4 else ''})")
    animals = sum(len(v) for k, v in groups.items() if k in ANIMALS)
    persons = len(groups.get("person", []))
    head = []
    if persons:
        head.append(trf("{n} persons" if persons > 1 else "{n} person", lang, n=persons))
    if animals:
        head.append(trf("{n} animals" if animals > 1 else "{n} animal", lang, n=animals))
    text = ((", ".join(head) + " – ") if head else "") + "; ".join(parts) + f" ({span})"
    best = [e for e in ev if e.get("img")]
    best.sort(key=lambda e: (e["label"] == "person", e.get("conf", 0)), reverse=True)
    return {"text": text, "img": best[0]["img"] if best else "", "count": len(ev), "from": a, "to": b}


def report_send(w, manual=False):
    r = report_build()
    STATE["report_last"] = {"t": datetime.now().isoformat(timespec="seconds"), "text": r["text"], "img": r["img"], "sent": False}
    if w is None or not Notifier.configured() or not CFG["notify_on"]:
        return r, False
    jpg = None
    if r["img"]:
        try:
            p = os.path.join(diary_dir(), r["img"])
            img = cv2.imread(p)
            if img is not None:
                h, wd = img.shape[:2]
                if wd > 800:
                    img = cv2.resize(img, (800, int(h * 800 / wd)), interpolation=cv2.INTER_AREA)
                if CFG["share_logo"]:
                    img = brand_image(img, tr("Night report") + " " + datetime.now().strftime("%d.%m.%Y"))
                ok, buf = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 75])
                jpg = buf.tobytes() if ok else None
        except (OSError, cv2.error):
            jpg = None
    de = CFG["lang"] == "de"
    pub = CFG["public_url"].strip().rstrip("/")
    ok = w.notifier.info(r["text"], pub + "/diary" if pub else "", title="{name}: " + tr("night report"),
                         jpg=jpg, fname="nachtbericht.jpg")
    STATE["report_last"]["sent"] = bool(ok)
    log_event("web", ("Night report sent" if ok else "Night report not sent") + (" (by hand)" if manual else "") + f": {r['text'][:80]}")
    return r, ok


class ReportScheduler:
    """Sends the night report once a day at the report hour (also up to 3 h late, e.g. when the Pi was off)."""
    def __init__(self):
        threading.Thread(target=self.loop, daemon=True).start()

    def loop(self):
        while True:
            time.sleep(30)
            try:
                now = datetime.now(); hr = int(CFG["report_hour"]) % 24
                day = now.strftime("%Y-%m-%d")
                if CFG["report_on"] and CFG["report_last_day"] != day and hr <= now.hour < hr + 3:
                    CFG["report_last_day"] = day; save_settings()
                    report_send(WATCH_REF["w"])
            except Exception as e:
                log_event("sys", f"Night report: {e}")


# ---- guest access -------------------------------------------------------------
GUESTS = {"streams": 0}


def guest_ok(token):
    tok = CFG["guest_token"]
    if not tok or not isinstance(token, str) or not hmac.compare_digest(token.encode(), tok.encode()):
        return False
    if CFG["guest_until"] and time.time() > CFG["guest_until"]:
        return False
    return True


def guest_info():
    tok = CFG["guest_token"]
    active = bool(tok) and not (CFG["guest_until"] and time.time() > CFG["guest_until"])
    return {"active": active, "path": f"/g/{tok}" if active else "", "until": CFG["guest_until"] if active else 0,
            "watching": GUESTS["streams"]}


def guest_set(action, hours=24):
    if action == "end":
        CFG["guest_token"] = ""; CFG["guest_until"] = 0.0
        save_settings(); log_event("web", "Guest access ended")
        return True, ""
    if action != "create":
        return False, "unknown action"
    try:
        hours = float(hours)
    except (TypeError, ValueError):
        return False, "not a number"
    if not math.isfinite(hours) or hours < 0 or hours > 24 * 365:
        return False, "not a number"
    CFG["guest_token"] = secrets.token_urlsafe(18)
    CFG["guest_until"] = time.time() + hours * 3600 if hours else 0.0
    save_settings()
    log_event("web", "Guest access created" + (f" for {hours:g} h" if hours else " (no time limit)"))
    return True, ""


# ---- battery (powerbank) runtime estimate ---------------------------------------
def _pmic_watts():
    """Power of the Pi 5 itself from its power chip (all rails, V x A), or None."""
    if not shutil.which("vcgencmd"):
        return None
    rc, txt, _e = _run(["vcgencmd", "pmic_read_adc"], timeout=5)
    if rc != 0 or not txt:
        return None
    amps, volts = {}, {}
    for m in re.finditer(r"(\S+)_A\s+current\(\d+\)=([0-9.]+)A", txt):
        amps[m.group(1)] = float(m.group(2))
    for m in re.finditer(r"(\S+)_V\s+volt\(\d+\)=([0-9.]+)V", txt):
        volts[m.group(1)] = float(m.group(2))
    p = sum(a * volts[k] for k, a in amps.items() if k in volts)
    return p if p > 0.2 else None


# ----------------------------------------------------------------------------
# UPS HAT (Waveshare, 2 x 18650 in series = 2S, 6.0 ... 8.4 V): an INA219 on I2C (0x42) measures the battery voltage and
# the current (shunt 0.1 ohm). Only reads - nothing is written to the chip. Negative current = the battery delivers.
# ----------------------------------------------------------------------------
_CELL_CURVE = [(3.00, 0), (3.30, 5), (3.50, 15), (3.60, 28), (3.70, 45), (3.80, 60), (3.90, 72), (4.00, 83), (4.10, 93), (4.20, 100)]


def cell_pct(v):
    if v <= _CELL_CURVE[0][0]:
        return 0
    for (v0, p0), (v1, p1) in zip(_CELL_CURVE, _CELL_CURVE[1:]):
        if v <= v1:
            return int(round(p0 + (p1 - p0) * (v - v0) / (v1 - v0)))
    return 100


def ups_read(addr, bus=1):
    """(battery voltage V, current A) from the INA219, or None (no chip / no I2C)."""
    import fcntl
    try:
        fd = os.open(f"/dev/i2c-{bus}", os.O_RDWR)
    except OSError:
        return None
    try:
        fcntl.ioctl(fd, I2C_SLAVE, addr)
        def reg(r):
            os.write(fd, bytes([r])); b = os.read(fd, 2)
            return (b[0] << 8) | b[1]
        bus_raw, sh = reg(0x02), reg(0x01)
        if sh & 0x8000:
            sh -= 0x10000
        volt = (bus_raw >> 3) * 0.004
        amps = sh * 0.00001 / 0.1
        if not (2.0 <= volt <= 9.5):                      # not a battery pack (or another chip at this address)
            return None
        return volt, (-amps if CFG["ups_invert"] else amps)
    except OSError:
        return None
    finally:
        os.close(fd)


def ups_read_e(addr=0x2D, bus=1):
    """Waveshare UPS HAT (E): a battery chip at I2C 0x2D (16-bit values, low byte first). None = not there / implausible.
    0x00 ID (0x0A), 0x02 state (0x80 charging, 0x40 fast charging, 0x20 power at the input, bits 0-2: 5 = full),
    0x10 USB-C input mV / mA, 0x20 battery mV, mA (signed, + = charging, - = discharging),
    %, remaining mAh, minutes left (discharging), minutes to full (charging), 0x30 the four cell voltages (mV)."""
    import fcntl
    try:
        fd = os.open(f"/dev/i2c-{bus}", os.O_RDWR)
    except OSError:
        return None
    try:
        fcntl.ioctl(fd, I2C_SLAVE, addr)
        def blk(reg, n):
            os.write(fd, bytes([reg])); return os.read(fd, n)
        u = lambda b, i: b[i] | (b[i + 1] << 8)
        if blk(0x00, 1)[0] != 0x0A:
            return None                                       # not the UPS HAT (E)
        st = blk(0x02, 1)[0]; vb = blk(0x10, 6); bt = blk(0x20, 12); cl = blk(0x30, 8)
        cur = u(bt, 2)
        if cur > 0x7FFF:
            cur -= 0x10000
        r = {"state": st, "vbus": u(vb, 0) / 1000.0, "vbus_a": u(vb, 2) / 1000.0, "v": u(bt, 0) / 1000.0, "a": cur / 1000.0,
             "pct": u(bt, 4), "mah": u(bt, 6), "min_left": u(bt, 8), "min_full": u(bt, 10), "cells": [u(cl, i) / 1000.0 for i in (0, 2, 4, 6)]}
        if not (6.0 <= r["v"] <= 17.6) or r["pct"] > 100:
            return None                                       # another chip at this address
        return r
    except (OSError, IndexError):
        return None
    finally:
        os.close(fd)


class BatteryMonitor:
    """Estimates what is left in the powerbank: capacity (mAh on the label) x 3.7 V x 85 % usable, minus what the Pi used
    since 'Battery full' was pressed. Power = Pi power chip (or an estimate from the CPU load) + extra devices + lights."""
    def __init__(self):
        self.hist = deque(maxlen=60)     # watts, last 10 minutes (every 10 s)
        self.uhist = deque(maxlen=6)     # UPS: voltage / current, last minute
        self._t = time.time(); self._save_t = time.time()
        threading.Thread(target=self.loop, daemon=True).start()

    def watts(self):
        p = _pmic_watts()
        src = "pmic"
        if p is None:
            cpu = STATE.get("cpu") or 0.0
            p = 2.7 + 3.3 * min(100.0, cpu) / 100.0; src = "estimate"
        else:
            p *= 1.15                    # the power chip does not see USB devices, losses
        L = STATE.get("lights") or {}
        p += float(CFG["batt_extra_w"]) + (0.6 if L.get("white") else 0.0) + (0.6 if L.get("ir") else 0.0)
        return p, src

    def loop(self):
        while True:
            time.sleep(10)
            try:
                self.tick()
            except Exception as e:
                log_event("sys", f"Battery estimate: {e}")

    def ups_tick(self):
        """UPS HAT found: charge from the battery voltage, time left from the measured power. Power cut / back,
        warning at 20 %, shutdown at <ups_shutdown_pct> % so the memory card is not damaged."""
        model = CFG["ups_model"]
        if model in ("auto", "e"):
            e = ups_read_e()
            if e is not None:
                return self.ups_e(e)
            if model == "e":
                r = None
        if model != "e":
            try:
                addr = int(str(CFG["ups_addr"]), 16)
            except ValueError:
                addr = 0x42
            r = ups_read(addr)
        if r is None:
            self._ups_miss = getattr(self, "_ups_miss", 0) + 1
            return self._ups_miss < 3 and getattr(self, "_ups_seen", False)      # keep the last values for a short hiccup
        self._ups_miss = 0
        if not getattr(self, "_ups_seen", False):
            self._ups_seen = True; log_event("sys", f"UPS HAT found (I2C {CFG['ups_addr']}): battery {r[0]:.2f} V")
        volt, amps = r
        self.uhist.append((volt, amps))
        v = sum(x[0] for x in self.uhist) / len(self.uhist); a = sum(x[1] for x in self.uhist) / len(self.uhist)
        on_batt = a < -0.10; charging = a > 0.05
        pct = cell_pct(v / 2.0)
        watts = v * abs(a)
        cap_wh = float(CFG["ups_mah"]) / 1000.0 * 7.4 * 0.9
        hours = (pct / 100.0 * cap_wh / max(0.8, watts)) if on_batt else None
        STATE["battery"] = {"on": True, "src": "ups", "model": "ina", "pct": pct, "hours": None if hours is None else round(hours, 1),
                            "cap_wh": round(cap_wh, 1), "use_w": round(watts if on_batt else self.watts()[0], 1), "watts": round(watts, 1), "volt": round(v, 2), "amps": round(a, 2), "on_battery": on_batt,
                            "charging": charging}
        return self.ups_events(v, pct, hours, on_batt, 5.5 <= v <= 8.9)

    def ups_e(self, r):
        """UPS HAT (E): its battery chip knows the charge, the time left and whether it charges."""
        if not getattr(self, "_ups_seen", False):
            self._ups_seen = True
            log_event("sys", f"UPS HAT (E) found (I2C 0x2D): battery {r['v']:.2f} V, {r['pct']} %, cells " + " / ".join(f"{c:.2f}" for c in r["cells"]) + " V")
        self._ups_miss = 0
        st = r["state"]
        charging = bool(st & 0x80) and (st & 0x07) != 5
        on_batt = not (st & 0x20) and r["a"] <= 0.05             # no power at the input: the Pi runs on the cells
        v, a, pct = r["v"], r["a"], int(r["pct"])
        watts = v * abs(a)
        cap_wh = (r["mah"] / max(1.0, pct) * 100.0 / 1000.0 * v * 0.9) if r["mah"] and pct else 0.0
        hours = round(r["min_left"] / 60.0, 1) if on_batt and r["min_left"] and r["min_left"] < 0xFFFF else (
            round(pct / 100.0 * cap_wh / max(0.8, watts), 1) if on_batt and cap_wh else None)
        STATE["battery"] = {"on": True, "src": "ups", "model": "e", "pct": pct, "hours": hours, "cap_wh": round(cap_wh, 1),
                            "use_w": round(watts if on_batt else self.watts()[0], 1), "watts": round(watts, 1), "volt": round(v, 2),
                            "amps": round(a, 2), "on_battery": on_batt, "charging": charging, "fast": bool(st & 0x40), "full": (st & 0x07) == 5,
                            "cells": [round(c, 2) for c in r["cells"]], "vbus": round(r["vbus"], 2), "mah": r["mah"],
                            "full_min": r["min_full"] if charging and r["min_full"] < 0xFFFF else None}
        cl = [c for c in r["cells"] if c > 0.5]
        if cl and max(cl) - min(cl) > 0.3 and not getattr(self, "_cell_warn", False):
            self._cell_warn = True
            log_event("sys", "UPS HAT (E): the cells are uneven (" + " / ".join(f"{c:.2f}" for c in r["cells"]) + " V) - check the batteries")
        return self.ups_events(v, pct, hours, on_batt, 9.0 <= v <= 17.6)

    def ups_events(self, v, pct, hours, on_batt, volt_ok):
        """Power cut / back, almost empty, clean shutdown - the same for every UPS HAT."""
        w = WATCH_REF["w"]; de = CFG["lang"] == "de"
        def push(text_en, **kw):
            if w is not None and CFG["ups_push"]:
                w.notifier.info(trf(text_en, **kw), title="{name}: " + tr("power"))
        was = getattr(self, "_on_batt", None)
        if was is not None and on_batt != was:
            if on_batt:
                log_event("sys", f"Power cut - running on the battery ({pct} %, {v:.2f} V)")
                if CFG["tamper_power"] and is_armed() and TAMPER is not None:
                    TAMPER.alarm("power")                    # armed: a cut cable can mean theft
                else:
                    push("Power cut – running on the battery ({pct} %)", pct=pct)
            else:
                log_event("sys", f"Mains power back - battery {pct} %")
                push("Power back – battery {pct} %", pct=pct)
                CFG["batt_warned"] = False
        self._on_batt = on_batt
        if on_batt and pct <= 20 and not CFG["batt_warned"]:
            CFG["batt_warned"] = True; save_settings()
            log_event("sys", f"Battery almost empty (about {pct} %, {hours or 0:.1f} h left)")
            push("Battery almost empty: about {pct} % ({hours:.1f} h)", pct=pct, hours=hours or 0)
        lim = int(CFG["ups_shutdown_pct"])
        plausible = volt_ok and time.time() - RUNGUARD["t0"] > 180            # a real battery value; never in the first 3 minutes
        self._low = (getattr(self, "_low", 0) + 1) if (on_batt and lim > 0 and pct <= lim and plausible) else 0
        if self._low >= 3 and not POWER.get("pending") and not getattr(self, "_shut", False):   # 30 s below the limit
            self._shut = True
            log_event("sys", f"Battery empty ({pct} %, {v:.2f} V) - shutting down the Pi to protect the memory card")
            push("Battery empty – the Pi shuts down cleanly")
            power_action("poweroff", source="battery")
        return True

    def tick(self):
        now = time.time(); dt = min(60.0, now - self._t); self._t = now
        if CFG["ups_on"] and self.ups_tick():
            return
        cap_wh = float(CFG["batt_mah"]) * 3.7 / 1000.0 * 0.85
        if cap_wh <= 0:
            STATE["battery"] = {"on": False}
            return
        p, src = self.watts(); self.hist.append(p)
        if CFG["batt_full_t"]:
            CFG["batt_used_wh"] = float(CFG["batt_used_wh"]) + p * dt / 3600.0
            sw = (STATE.get("solar") or {}).get("w") if CFG["solar_on"] else None
            if sw:                                        # the panel charges the powerbank (about 85 % arrives)
                CFG["batt_used_wh"] = max(0.0, float(CFG["batt_used_wh"]) - sw * 0.85 * dt / 3600.0)
        avg = sum(self.hist) / len(self.hist)
        left = max(0.0, cap_wh - float(CFG["batt_used_wh"])) if CFG["batt_full_t"] else None
        pct = None if left is None else int(round(100.0 * left / cap_wh))
        hours = None if left is None else left / max(0.5, avg)
        STATE["battery"] = {"on": True, "watts": round(avg, 1), "use_w": round(avg, 1), "src": src, "pct": pct,
                            "hours": None if hours is None else round(hours, 1), "since": CFG["batt_full_t"], "cap_wh": round(cap_wh, 1)}
        if now - self._save_t > 300:
            self._save_t = now; save_settings()
        if pct is not None and pct <= 15 and not CFG["batt_warned"]:
            CFG["batt_warned"] = True; save_settings()
            log_event("sys", f"Battery almost empty (about {pct} %, {hours:.1f} h left)")
            w = WATCH_REF["w"]
            if w is not None:
                de = CFG["lang"] == "de"
                w.notifier.info(trf("Battery almost empty: about {pct} % ({hours:.1f} h) left – please charge or swap", pct=pct, hours=hours),
                                title="{name}: " + tr("battery"))


def battery_full():
    CFG["batt_full_t"] = time.time(); CFG["batt_used_wh"] = 0.0; CFG["batt_warned"] = False
    save_settings(); log_event("sys", "Battery marked as full")
    return True, ""


class SysMonitor:
    def __init__(self):
        self.hist = deque(maxlen=60)          # last 60 seconds
        self._prev = None
        try:
            import psutil
            self.ps = psutil
            psutil.cpu_percent(percpu=True)   # first call only primes the counters
        except ImportError:
            self.ps = None
            log_event("sys", "psutil not installed - using /proc/stat (pip install psutil recommended)")
        STATE["cpu_count"] = os.cpu_count() or 1
        threading.Thread(target=self.loop, daemon=True).start()

    def _cpu(self):
        if self.ps:
            per = self.ps.cpu_percent(percpu=True)
            return sum(per) / len(per) if per else 0.0
        try:                                   # Linux fallback without psutil
            with open("/proc/stat") as f:
                vals = [int(v) for v in f.readline().split()[1:]]
        except Exception:
            return None
        idle = vals[3] + (vals[4] if len(vals) > 4 else 0)
        total = sum(vals[:8])
        prev, self._prev = self._prev, (idle, total)
        if prev is None or total <= prev[1]:
            return 0.0
        return max(0.0, min(100.0, 100.0 * (1.0 - (idle - prev[0]) / (total - prev[1]))))

    def _shares(self):
        """CPU of Motion Watch itself and of the 3D simulator (when it runs on the same computer), in % of the whole
        computer like «cpu» - shown in the small box of the simulator (sim_state «cpu»)."""
        if not self.ps:
            STATE["cpu_mw"] = STATE["cpu_sim"] = None
            return
        n = max(1, STATE.get("cpu_count") or 1)
        try:
            if getattr(self, "me", None) is None:
                self.me = self.ps.Process()
                self.me.cpu_percent(None)
            STATE["cpu_mw"] = round(self.me.cpu_percent(None) / n, 1)
        except Exception:
            STATE["cpu_mw"] = None
        pid = int(SIM.get("pid") or 0) if CFG.get("sim_on") else 0
        if pid <= 0:
            self.sim_p = None
            STATE["cpu_sim"] = None
            return
        try:
            p = getattr(self, "sim_p", None)
            if p is None or p.pid != pid:
                p = self.ps.Process(pid)
                if "motionwatch3d" not in p.name().lower():      # same number on another computer: not our simulator
                    raise ValueError("other process")
                self.sim_p = p
                p.cpu_percent(None)
                STATE["cpu_sim"] = None
                return
            STATE["cpu_sim"] = round(p.cpu_percent(None) / n, 1)
        except Exception:
            self.sim_p = None
            STATE["cpu_sim"] = None
            SIM["pid"] = 0                     # the simulator runs elsewhere (or ended): do not try again

    def _temp(self):
        try:                                   # Raspberry Pi / most Linux boards
            with open("/sys/class/thermal/thermal_zone0/temp") as f:
                return int(f.read().strip()) / 1000.0
        except Exception:
            pass
        if self.ps and hasattr(self.ps, "sensors_temperatures"):
            try:
                for entries in self.ps.sensors_temperatures().values():
                    if entries:
                        return float(entries[0].current)
            except Exception:
                pass
        return None

    # ---- power supply (Pi: under-voltage) + free space on the memory card ----
    def _read_supply(self):
        out = {"volt": None, "uv_now": False, "uv_boot": False, "throttled": False, "known": False}
        if shutil.which("vcgencmd"):
            rc, txt, _e = _run(["vcgencmd", "get_throttled"], timeout=5)
            m = re.search(r"0x([0-9a-fA-F]+)", txt or "")
            if rc == 0 and m:
                v = int(m.group(1), 16)
                out.update(known=True, uv_now=bool(v & 0x1), throttled=bool(v & 0x6), uv_boot=bool(v & 0x10000))
            rc, txt, _e = _run(["vcgencmd", "pmic_read_adc", "EXT5V_V"], timeout=5)        # Pi 5: voltage at the USB-C input
            m = re.search(r"=\s*([0-9.]+)\s*V", txt or "")
            if rc == 0 and m:
                out["volt"] = round(float(m.group(1)), 2)
        if not out["known"]:
            for d in glob.glob("/sys/class/hwmon/hwmon*"):
                try:
                    with open(os.path.join(d, "name")) as f:
                        if f.read().strip() != "rpi_volt":
                            continue
                    with open(os.path.join(d, "in0_lcrit_alarm")) as f:
                        out.update(known=True, uv_now=f.read().strip() == "1")
                except OSError:
                    pass
        return out

    def _supply_disk(self):
        now = time.time()
        if now - getattr(self, "_sd_t", 0.0) < 10.0:
            return
        self._sd_t = now
        w = WATCH_REF["w"]; de = CFG["lang"] == "de"
        sup = self._read_supply(); STATE["supply"] = sup
        if sup["uv_now"]:
            self._uv_last = now
            if not getattr(self, "uv_warned", False):
                self.uv_warned = True
                log_event("sys", "UNDER-VOLTAGE: the power bank / cable delivers too little" + (f" ({sup['volt']} V)" if sup["volt"] else ""))
                if w is not None:
                    w.notifier.info(tr("Under-voltage: power bank almost empty or cable too weak") + (f" ({sup['volt']} V)" if sup["volt"] else ""),
                                    title="{name}: " + tr("power"))
        elif getattr(self, "uv_warned", False) and now - getattr(self, "_uv_last", 0.0) > 600:
            self.uv_warned = False
        try:
            du = shutil.disk_usage(rec_dir() if os.path.isdir(rec_dir()) else DATA_DIR)
            free = int(du.free / 1024 ** 2); STATE["disk"] = {"free_mb": free, "total_mb": int(du.total / 1024 ** 2)}
            try:
                dk = _dev_kind(_mount_of(rec_dir() if os.path.isdir(rec_dir()) else DATA_DIR)[0])
            except Exception:
                dk = "other"
            STATE["disk"]["kind"] = dk
        except OSError:
            return
        lim = float(CFG["disk_warn_mb"])
        if free < lim and not getattr(self, "disk_warned", False):
            self.disk_warned = True
            log_event("sys", f"Memory card almost full: {free} MB free")
            if w is not None:
                w.notifier.info(trf("Memory card almost full: {free} MB free - the oldest recordings are deleted", free=free),
                                title="{name}: " + tr("memory"))
        elif free > lim * 1.5:
            self.disk_warned = False
        if free < 300 and w is not None and now - getattr(self, "_clean_t", 0.0) > 60:
            self._clean_t = now
            w.cleanup_recordings()                  # makes room: oldest recordings first (never favourites)

    def loop(self):
        while True:
            time.sleep(1.0)
            cpu = self._cpu()
            temp = self._temp()
            if cpu is not None:
                self.hist.append(round(cpu, 1))
            STATE["mem"] = mem_info()
            STATE.update(cpu=None if cpu is None else round(cpu, 1),
                         cpu_temp=None if temp is None else round(temp, 1),
                         cpu_hist=list(self.hist))
            self._shares()
            self._supply_disk()
            if temp is not None:
                lim = float(CFG["temp_warn"])
                if temp >= lim and not getattr(self, "warned", False):
                    self.warned = True
                    log_event("sys", f"CPU hot: {temp:.0f} °C (limit {lim:.0f} °C) - check the cooling / ventilation")
                    w = WATCH_REF["w"]
                    if w is not None:
                        de = CFG["lang"] == "de"
                        w.notifier.info(trf("Pi too hot: {temp:.0f} °C (limit {lim:.0f} °C) - check the cooling / ventilation", temp=temp, lim=lim),
                                        title="{name}: " + tr("temperature"))
                elif temp < lim - 5:
                    self.warned = False


# ----------------------------------------------------------------------------
# Network: Wi-Fi signal (e.g. a phone hotspot) and whether the internet can be reached (push messages need it)
#   /proc/net/wireless every 2 s (signal level), "iw dev <if> link" every 15 s (network name, speed), internet check every 30 s
# ----------------------------------------------------------------------------
def _proc_wireless():
    out = {}
    try:
        with open("/proc/net/wireless") as f:
            lines = f.read().splitlines()[2:]
    except OSError:
        return out
    for ln in lines:
        if ":" not in ln:
            continue
        iface, rest = ln.split(":", 1); parts = rest.split()
        try:
            link, level = float(parts[1].rstrip(".")), float(parts[2].rstrip("."))
        except (IndexError, ValueError):
            continue
        if level > 63:                                   # some drivers report an unsigned byte (200 = -56 dBm)
            level -= 256
        out[iface.strip()] = (link, level)
    return out


def _wifi_ifaces():
    names = sorted(set(_proc_wireless()) | {os.path.basename(os.path.dirname(p)) for p in glob.glob("/sys/class/net/*/wireless")})
    return names


def _iw_link(iface):
    """-> dict(ssid, dbm, rate, connected) from 'iw', or None when iw is missing."""
    if shutil.which("iw") is None:
        return None
    try:
        r = subprocess.run(["iw", "dev", iface, "link"], capture_output=True, text=True, timeout=4)
    except (OSError, subprocess.SubprocessError):
        return None
    txt = r.stdout
    if "Not connected" in txt or not txt.strip():
        return {"ssid": "", "dbm": None, "rate": "", "connected": False}
    m_ss = re.search(r"SSID:\s*(.+)", txt); m_sig = re.search(r"signal:\s*(-?\d+)", txt); m_rate = re.search(r"tx bitrate:\s*([\d.]+\s*\S+)", txt)
    return {"ssid": m_ss.group(1).strip()[:40] if m_ss else "", "dbm": int(m_sig.group(1)) if m_sig else None,
            "rate": m_rate.group(1) if m_rate else "", "connected": True}


def wifi_pct(dbm):
    return int(max(0, min(100, 2 * (dbm + 100)))) if dbm is not None else 0


class NetMonitor:
    def __init__(self):
        self.iw = {}; self.weak = False; self.was = None; self.ip = ""; self.announced = None; self.t_start = time.time()
        self.key = None; self.changed_at = 0.0; self.recheck = False
        self.hist = deque(maxlen=150)                    # one value every 2 s = the last 5 minutes (None = no connection)
        threading.Thread(target=self.loop, daemon=True).start()
        threading.Thread(target=self.online_loop, daemon=True).start()

    def sample(self, n):
        if n % 8 == 0 or WIFI.get("refresh") or WIFI.get("hs_busy"):
            try:
                hotspot_refresh()
            except Exception:
                pass
        if STATE["hotspot"].get("on") and not DUAL["on"]:   # the Pi is the access point itself: no signal to measure
            STATE["wifi"] = {"iface": WIFI["iface"], "ssid": STATE["hotspot"]["ssid"], "dbm": None, "pct": 0, "rate": "", "connected": False,
                             "ip": STATE["hotspot"]["ip"], "ap": True}
            self.was = None; WIFI["refresh"] = False
            return
        ifaces = _wifi_ifaces()
        if not ifaces:
            STATE["wifi"] = None; return
        proc = _proc_wireless()
        iface = next((i for i in ifaces if i in proc and proc[i][1] < 0), ifaces[0])
        if DUAL["on"] and DUAL["up"] in ifaces:
            iface = DUAL["up"]
        refresh = WIFI.get("refresh") or WIFI.get("busy")
        if refresh:
            WIFI["refresh"] = False
        if n % 8 == 0 or iface not in self.iw or refresh:
            info = _iw_link(iface)
            if info is not None:
                self.iw[iface] = info
        iw = self.iw.get(iface) or {}
        dbm = int(proc[iface][1]) if iface in proc and proc[iface][1] < 0 else iw.get("dbm")
        connected = (dbm is not None) if not iw else bool(iw.get("connected")) and dbm is not None
        if connected and (n % 8 == 0 or not self.ip or refresh):
            self.ip = wifi_ip(iface)
        elif not connected:
            self.ip = ""
        STATE["wifi"] = {"iface": iface, "ssid": iw.get("ssid", "") if connected else "", "dbm": dbm if connected else None,
                         "pct": wifi_pct(dbm) if connected else 0, "rate": iw.get("rate", "") if connected else "", "connected": connected,
                         "ip": self.ip}
        self.hist.append(dbm if connected else None)
        STATE["wifi_hist"] = list(self.hist)
        self.announce(connected, iw.get("ssid", ""))
        if connected != self.was:
            if self.was is not None:
                log_event("sys", f"Wi-Fi {iface}: " + (f"connected ({dbm} dBm)" if connected else "connection lost"))
            self.was = connected
        if connected:
            if not self.weak and dbm < -77:
                self.weak = True; log_event("sys", f"Wi-Fi signal weak: {dbm} dBm")
            elif self.weak and dbm > -72:
                self.weak = False; log_event("sys", f"Wi-Fi signal ok again: {dbm} dBm")

    def announce(self, connected, ssid):
        """Push message with the address of the page when the Pi is in a (new) network - on a phone hotspot nobody knows
        the address otherwise. Waits until the internet works, because the message needs it."""
        key = (ssid, self.ip)
        if key != self.key:                              # new network / address: check the internet again right away
            self.key = key; self.changed_at = time.time(); self.recheck = True
        net = STATE["net"]
        if not (connected and self.ip and CFG["notify_network"]) or net.get("online") is not True or net.get("t", 0) < self.changed_at:
            return
        if key == self.announced or time.time() - self.t_start < 8:
            return
        w = WATCH_REF.get("w")
        if w is None:
            return
        addr = page_address(self.ip)
        de = CFG["lang"] == "de"
        txt = trf("Motion Watch is online in Wi-Fi {ssid}: {addr}", ssid=ssid or "?", addr=addr)
        if w.notifier.info(txt, addr):
            self.announced = key
            log_event("sys", f"Address sent as push message: {addr}")

    def loop(self):
        n = 0
        while True:
            try:
                self.sample(n)
            except Exception as e:
                STATE["wifi"] = None; log_event("sys", f"Wi-Fi monitor error: {e}"); time.sleep(30)
            n += 1
            time.sleep(2.0)

    def online_loop(self):
        import socket
        while True:
            res = {"online": False, "ms": None}
            # several ways out: some routers / filters block port 53 to outside servers, but never normal web traffic (443)
            targets = []
            try:
                from urllib.parse import urlparse
                h = urlparse(CFG["notify_url"].strip()).hostname if CFG["notify_url"].strip() else ""
                if h:
                    targets.append((h, 443))                 # the push server itself: exactly what matters
            except ValueError:
                pass
            targets += [("1.1.1.1", 443), ("8.8.8.8", 443), ("1.1.1.1", 53), ("8.8.8.8", 53)]
            for host, port in targets:
                t0 = time.time()
                try:
                    socket.create_connection((host, port), timeout=3).close()
                    res = {"online": True, "ms": int((time.time() - t0) * 1000)}
                    break
                except OSError:
                    pass
            if STATE["net"].get("online") is not None and res["online"] != STATE["net"]["online"]:
                log_event("sys", "Internet reachable again" if res["online"] else "Internet not reachable (push messages cannot be sent)")
            res["t"] = time.time()
            STATE["net"] = res
            self.recheck = False
            for _ in range(30 if res["online"] else 10):     # every 30 s (10 s while offline), at once after a network change
                if self.recheck:
                    break
                time.sleep(1.0)


# ----------------------------------------------------------------------------
# Wi-Fi management: search networks (phone hotspots), connect, save for automatic connection, forget.
#   NetworkManager (nmcli, Raspberry Pi OS Bookworm and newer) - or wpa_supplicant (wpa_cli, older systems).
#   "Connect now" falls back to the previous network when the new one does not work.
# ----------------------------------------------------------------------------
WIFI = {"backend": None, "iface": "", "scan": [], "scan_time": 0.0, "job": "", "job_ok": None, "busy": False, "refresh": False}
_WIFI_LOCK = threading.Lock()


def _run(cmd, timeout=30, inp=None):
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, input=inp)
        return r.returncode, r.stdout, (r.stderr or "").strip()
    except subprocess.TimeoutExpired:
        return 124, "", "timeout"
    except OSError as e:
        return 127, "", str(e)


def _nm_split(line):
    """nmcli -t output: fields separated by ':', a literal ':' is written as '\\:'."""
    out, cur, esc = [], [], False
    for ch in line:
        if esc:
            cur.append(ch); esc = False
        elif ch == "\\":
            esc = True
        elif ch == ":":
            out.append("".join(cur)); cur = []
        else:
            cur.append(ch)
    out.append("".join(cur))
    return out


def wifi_backend():
    if WIFI["backend"] is None:
        if shutil.which("nmcli"):
            code, out, _e = _run(["nmcli", "-t", "-f", "RUNNING", "general"], 8)
            if code == 0 and "running" in out:
                WIFI["backend"] = "nm"
        if WIFI["backend"] is None and shutil.which("wpa_cli"):
            WIFI["backend"] = "wpa"
        if WIFI["backend"] is None:
            WIFI["backend"] = ""
    if not WIFI["iface"]:
        ifs = _wifi_ifaces()
        WIFI["iface"] = ifs[0] if ifs else "wlan0"
    return WIFI["backend"]


def _perm_hint(err):
    e = (err or "").lower()
    if "not authorized" in e or "permission" in e or "insufficient privileges" in e or "access denied" in e:
        return ("no permission to change Wi-Fi - start the program with sudo, or allow it once with: "
                f"sudo python3 {os.path.basename(__file__)} --allow-wifi")
    return err or "error"


def _bars_from_pct(p):
    return 4 if p >= 75 else 3 if p >= 50 else 2 if p >= 25 else 1 if p > 0 else 0


def wifi_ip(iface=None):
    iface = iface or WIFI["iface"] or "wlan0"
    code, out, _e = _run(["ip", "-4", "-o", "addr", "show", "dev", iface], 5)
    m = re.search(r"inet (\d+\.\d+\.\d+\.\d+)", out or "")
    return m.group(1) if m else ""


def local_ip():
    """Address of this computer in the local network (no packet is sent)."""
    import socket
    try:
        sk = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            sk.connect(("10.255.255.255", 1)); return sk.getsockname()[0]
        finally:
            sk.close()
    except OSError:
        return wifi_ip()


# ---- QR codes (setup: scan the address / the own Wi-Fi with the phone camera) ----
def qr_matrix(text, ecl="M"):
    """QR code (byte mode) as a list of rows of True (dark) / False. Small own encoder after the standard
    (ISO 18004), so no extra package is needed on the Pi. ecl: L / M / Q / H."""
    E = {"L": 0, "M": 1, "Q": 2, "H": 3}[ecl]
    FMT = (1, 0, 3, 2)[E]
    ECW = ((-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30),
           (-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28),
           (-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30, 28, 30, 30, 30, 30, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30),
           (-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28, 30, 24, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30))
    NBL = ((-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18, 19, 19, 20, 21, 22, 24, 25),
           (-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49),
           (-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20, 23, 23, 25, 27, 29, 34, 34, 35, 38, 40, 43, 45, 48, 51, 53, 56, 59, 62, 65, 68),
           (-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25, 25, 34, 30, 32, 35, 37, 40, 42, 45, 48, 51, 54, 57, 60, 63, 66, 70, 74, 77, 81))

    def raw_modules(v):
        r = (16 * v + 128) * v + 64
        if v >= 2:
            na = v // 7 + 2
            r -= (25 * na - 10) * na - 55
            if v >= 7:
                r -= 36
        return r

    def data_cw(v):
        return raw_modules(v) // 8 - ECW[E][v] * NBL[E][v]
    data = text.encode("utf-8")
    for ver in range(1, 41):
        if 4 + (8 if ver < 10 else 16) + 8 * len(data) <= data_cw(ver) * 8:
            break
    else:
        raise ValueError("text too long for a QR code")
    bits = []
    put = lambda val, n: bits.extend((val >> i) & 1 for i in range(n - 1, -1, -1))
    put(4, 4); put(len(data), 8 if ver < 10 else 16)
    for b in data:
        put(b, 8)
    cap = data_cw(ver) * 8
    put(0, min(4, cap - len(bits)))
    put(0, (-len(bits)) % 8)
    pad = 0xEC
    while len(bits) < cap:
        put(pad, 8); pad ^= 0xEC ^ 0x11
    cws = [int("".join(map(str, bits[i:i + 8])), 2) for i in range(0, len(bits), 8)]

    def gmul(x, y):
        z = 0
        for i in range(7, -1, -1):
            z = (z << 1) ^ ((z >> 7) * 0x11D)
            z ^= ((y >> i) & 1) * x
        return z & 0xFF
    nb, el = NBL[E][ver], ECW[E][ver]
    rawcw = raw_modules(ver) // 8
    nshort = nb - rawcw % nb; slen = rawcw // nb
    div = [0] * (el - 1) + [1]; root = 1
    for _ in range(el):
        for j in range(el):
            div[j] = gmul(div[j], root)
            if j + 1 < el:
                div[j] ^= div[j + 1]
        root = gmul(root, 0x02)
    blocks, k = [], 0
    for i in range(nb):
        dat = cws[k:k + slen - el + (0 if i < nshort else 1)]; k += len(dat)
        rem = [0] * el
        for b in dat:
            f = b ^ rem.pop(0); rem.append(0)
            for j, c in enumerate(div):
                rem[j] ^= gmul(c, f)
        if i < nshort:
            dat = dat + [0]
        blocks.append(dat + rem)
    allcw = [blk[i] for i in range(len(blocks[0])) for j, blk in enumerate(blocks) if i != slen - el or j >= nshort]
    size = ver * 4 + 17
    M = [[False] * size for _ in range(size)]
    F = [[False] * size for _ in range(size)]

    def setf(x, y, dark):
        M[y][x] = dark; F[y][x] = True
    for i in range(size):
        setf(6, i, i % 2 == 0); setf(i, 6, i % 2 == 0)
    for cx, cy in ((3, 3), (size - 4, 3), (3, size - 4)):
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                x, y = cx + dx, cy + dy
                if 0 <= x < size and 0 <= y < size:
                    setf(x, y, max(abs(dx), abs(dy)) not in (2, 4))
    if ver > 1:
        na = ver // 7 + 2
        step = 26 if ver == 32 else (ver * 4 + na * 2 + 1) // (na * 2 - 2) * 2
        pos = [6] + [size - 7 - i * step for i in range(na - 1)][::-1]
        for i, a in enumerate(pos):
            for j, b in enumerate(pos):
                if (i == 0 and j == 0) or (i == 0 and j == na - 1) or (i == na - 1 and j == 0):
                    continue
                for dy in range(-2, 3):
                    for dx in range(-2, 3):
                        setf(a + dx, b + dy, max(abs(dx), abs(dy)) != 1)

    def draw_format(mask):
        d = FMT << 3 | mask; rem = d
        for _ in range(10):
            rem = (rem << 1) ^ ((rem >> 9) * 0x537)
        b = (d << 10 | rem) ^ 0x5412
        g = lambda i: (b >> i) & 1 == 1
        for i in range(6):
            setf(8, i, g(i))
        setf(8, 7, g(6)); setf(8, 8, g(7)); setf(7, 8, g(8))
        for i in range(9, 15):
            setf(14 - i, 8, g(i))
        for i in range(8):
            setf(size - 1 - i, 8, g(i))
        for i in range(8, 15):
            setf(8, size - 15 + i, g(i))
        setf(8, size - 8, True)
    draw_format(0)
    if ver >= 7:
        rem = ver
        for _ in range(12):
            rem = (rem << 1) ^ ((rem >> 11) * 0x1F25)
        b = ver << 12 | rem
        for i in range(18):
            bit = (b >> i) & 1 == 1; a, c = size - 11 + i % 3, i // 3
            setf(a, c, bit); setf(c, a, bit)
    i = 0; right = size - 1
    while right >= 1:
        if right == 6:
            right = 5
        for vert in range(size):
            for j in range(2):
                x = right - j; up = ((right + 1) & 2) == 0
                y = size - 1 - vert if up else vert
                if not F[y][x] and i < len(allcw) * 8:
                    M[y][x] = (allcw[i >> 3] >> (7 - (i & 7))) & 1 == 1
                    i += 1
        right -= 2
    MASKS = (lambda x, y: (x + y) % 2 == 0, lambda x, y: y % 2 == 0, lambda x, y: x % 3 == 0, lambda x, y: (x + y) % 3 == 0,
             lambda x, y: (x // 3 + y // 2) % 2 == 0, lambda x, y: x * y % 2 + x * y % 3 == 0,
             lambda x, y: (x * y % 2 + x * y % 3) % 2 == 0, lambda x, y: ((x + y) % 2 + x * y % 3) % 2 == 0)

    def apply(m):
        for y in range(size):
            for x in range(size):
                if not F[y][x] and MASKS[m](x, y):
                    M[y][x] = not M[y][x]

    def penalty():
        p = 0
        lines = ["".join("1" if c else "0" for c in row) for row in M]
        lines += ["".join("1" if M[y][x] else "0" for y in range(size)) for x in range(size)]
        for ln in lines:
            run, last = 0, ""
            for ch in ln + "x":
                if ch == last:
                    run += 1
                else:
                    if run >= 5:
                        p += 3 + run - 5
                    run, last = 1, ch
            p += 40 * (ln.count("10111010000") + ln.count("00001011101"))
        for y in range(size - 1):
            for x in range(size - 1):
                if M[y][x] == M[y][x + 1] == M[y + 1][x] == M[y + 1][x + 1]:
                    p += 3
        dark = sum(map(sum, M)); tot = size * size
        p += ((abs(dark * 20 - tot * 10) + tot - 1) // tot - 1) * 10
        return p
    best, bm = None, 0
    for m in range(8):
        apply(m); draw_format(m)
        pen = penalty()
        if best is None or pen < best:
            best, bm = pen, m
        apply(m)
    apply(bm); draw_format(bm)
    return M


from html import escape as html_escape


def qr_svg(text, dark="#000", light="#fff"):
    M = qr_matrix(text); n = len(M); q = 4
    path = "".join(f"M{x + q},{y + q}h1v1h-1z" for y in range(n) for x in range(n) if M[y][x])
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {n + 2 * q} {n + 2 * q}" shape-rendering="crispEdges">'
            f'<rect width="100%" height="100%" fill="{light}"/><path d="{path}" fill="{dark}"/></svg>')


def qr_png(text, scale=6):
    M = qr_matrix(text); n = len(M); q = 4
    a = np.full((n + 2 * q, n + 2 * q), 255, np.uint8)
    a[q:q + n, q:q + n][np.array(M, bool)] = 0
    a = cv2.resize(a, ((n + 2 * q) * scale,) * 2, interpolation=cv2.INTER_NEAREST)
    ok, buf = cv2.imencode(".png", a)
    return buf.tobytes() if ok else b""


def wifi_qr_text(ssid, pw):
    esc = lambda v: re.sub(r'([\\;,:"])', r"\\\1", str(v))
    return f"WIFI:T:WPA;S:{esc(ssid)};P:{esc(pw)};;"


def setup_addresses():
    """Addresses to open the page: home / hotspot network, own Wi-Fi of the Pi, Tailscale."""
    out = []
    ip = wifi_ip()
    if ip:
        out.append({"kind": "lan", "url": page_address(ip)})
    if CFG["hotspot_on"] and ip != "10.42.0.1":
        out.append({"kind": "hotspot", "url": page_address("10.42.0.1")})
    try:
        ts = tailscale_status()
        if ts.get("state") == "Running" and ts.get("ip"):
            out.append({"kind": "tailscale", "url": page_address(ts["ip"])})
    except Exception:
        pass
    return out


def page_address(ip=None):
    ip = ip or wifi_ip()
    scheme = "https" if WEB_OPTS.get("https") else "http"
    return f"{scheme}://{ip}:{CFG['web_port']}/" if ip else ""


# ---- NetworkManager ----------------------------------------------------------
def _nm_saved():
    code, out, err = _run(["nmcli", "-t", "-f", "NAME,UUID,TYPE,AUTOCONNECT,AUTOCONNECT-PRIORITY,ACTIVE", "connection", "show"], 15)
    res = []
    if code != 0:
        return res
    for ln in out.splitlines():
        f = _nm_split(ln)
        if len(f) < 6 or f[2] not in ("802-11-wireless", "wifi"):
            continue
        c2, ss, _e = _run(["nmcli", "-t", "-g", "802-11-wireless.ssid,802-11-wireless.mode", "connection", "show", "uuid", f[1]], 10)
        lines = ss.splitlines() if c2 == 0 else []
        ssid = lines[0] if lines else f[0]
        mode = lines[1] if len(lines) > 1 else ""
        if mode == "ap":                                   # a hotspot the Pi itself offers - not a network to join
            continue
        try:
            prio = int(f[4])
        except ValueError:
            prio = 0
        res.append({"name": f[0], "id": f[1], "ssid": ssid, "auto": f[3] == "yes", "prio": prio, "active": f[5] == "yes"})
    return res


def _nm_scan():
    code, out, err = _run(["nmcli", "-t", "-f", "IN-USE,SSID,SIGNAL,SECURITY,CHAN", "device", "wifi", "list", "--rescan", "yes"], 40)
    if code != 0:                                          # rescanning may need more rights: use the cached list
        code, out, err = _run(["nmcli", "-t", "-f", "IN-USE,SSID,SIGNAL,SECURITY,CHAN", "device", "wifi", "list", "--rescan", "no"], 20)
    if code != 0:
        raise RuntimeError(_perm_hint(err))
    nets = {}
    for ln in out.splitlines():
        f = _nm_split(ln)
        if len(f) < 5 or not f[1]:
            continue
        try:
            sig = int(f[2])
        except ValueError:
            sig = 0
        sec = f[3].strip() if f[3].strip() not in ("", "--") else ""
        cur = nets.get(f[1]); act = f[0].strip() == "*"
        if cur is None or sig > cur["signal"]:            # 2.4 + 5 GHz of the same network: show the stronger one
            nets[f[1]] = {"ssid": f[1], "signal": sig, "secure": bool(sec), "security": sec, "chan": f[4],
                          "active": act or bool(cur and cur["active"])}
        elif act:
            cur["active"] = True
    return list(nets.values())


def _nm_connect_now(ssid, password):
    saved = next((s for s in _nm_saved() if s["ssid"] == ssid), None)
    if saved:
        if password:
            _run(["nmcli", "connection", "modify", "uuid", saved["id"], "wifi-sec.key-mgmt", "wpa-psk", "wifi-sec.psk", password], 15)
        code, out, err = _run(["nmcli", "--wait", "40", "connection", "up", "uuid", saved["id"]], 50)
    else:
        cmd = ["nmcli", "--wait", "40", "device", "wifi", "connect", ssid] + (["password", password] if password else []) + ["ifname", WIFI["iface"]]
        code, out, err = _run(cmd, 50)
    return code == 0, _perm_hint(err) if code else ""


def _nm_save(ssid, password, preferred):
    prio = "20" if preferred else "0"
    saved = next((s for s in _nm_saved() if s["ssid"] == ssid), None)
    if saved:
        cmd = ["nmcli", "connection", "modify", "uuid", saved["id"], "connection.autoconnect", "yes", "connection.autoconnect-priority", prio]
        if password:
            cmd += ["wifi-sec.key-mgmt", "wpa-psk", "wifi-sec.psk", password]
    else:
        cmd = ["nmcli", "connection", "add", "type", "wifi", "ifname", WIFI["iface"], "con-name", ssid, "ssid", ssid,
               "connection.autoconnect", "yes", "connection.autoconnect-priority", prio]
        if password:
            cmd += ["wifi-sec.key-mgmt", "wpa-psk", "wifi-sec.psk", password]
    code, out, err = _run(cmd, 20)
    return code == 0, _perm_hint(err) if code else ""


def _nm_forget(sid):
    code, out, err = _run(["nmcli", "connection", "delete", "uuid", sid], 20)
    return code == 0, _perm_hint(err) if code else ""


def _nm_up(sid):
    code, out, err = _run(["nmcli", "--wait", "40", "connection", "up", "uuid", sid], 50)
    return code == 0


# ---- wpa_supplicant (older Raspberry Pi OS) ------------------------------------
def _wpa(*args, timeout=15):
    return _run(["wpa_cli", "-i", WIFI["iface"]] + list(args), timeout)


def _wpa_saved():
    code, out, err = _wpa("list_networks")
    res = []
    for ln in out.splitlines()[1:]:
        f = ln.split("\t")
        if len(f) >= 2 and f[0].isdigit():
            res.append({"name": f[1], "id": f[0], "ssid": f[1], "auto": "[DISABLED]" not in (f[3] if len(f) > 3 else ""),
                        "prio": 0, "active": "[CURRENT]" in (f[3] if len(f) > 3 else "")})
    return res


def _wpa_scan():
    _wpa("scan"); time.sleep(4)
    code, out, err = _wpa("scan_results")
    if code != 0:
        raise RuntimeError(_perm_hint(err))
    cur = next((s["ssid"] for s in _wpa_saved() if s["active"]), "")
    nets = {}
    for ln in out.splitlines()[1:]:
        f = ln.split("\t")
        if len(f) < 5 or not f[4]:
            continue
        try:
            pct = wifi_pct(int(f[2]))
        except ValueError:
            pct = 0
        if f[4] not in nets or pct > nets[f[4]]["signal"]:
            sec = "WPA" if ("WPA" in f[3] or "RSN" in f[3]) else ("WEP" if "WEP" in f[3] else "")
            nets[f[4]] = {"ssid": f[4], "signal": pct, "secure": bool(sec), "security": sec, "chan": f[1], "active": f[4] == cur}
    return list(nets.values())


def _wpa_q(v):
    return '"' + v.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _wpa_save(ssid, password, preferred, select=False):
    saved = next((s for s in _wpa_saved() if s["ssid"] == ssid), None)
    if saved:
        nid = saved["id"]
    else:
        code, out, err = _wpa("add_network")
        nid = out.strip().splitlines()[-1] if out.strip() else ""
        if not nid.isdigit():
            return False, _perm_hint(err or out)
        _wpa("set_network", nid, "ssid", _wpa_q(ssid))
    if password:
        _wpa("set_network", nid, "psk", _wpa_q(password))
    elif not saved:
        _wpa("set_network", nid, "key_mgmt", "NONE")
    _wpa("set_network", nid, "priority", "20" if preferred else "0")
    code, out, err = _wpa("select_network" if select else "enable_network", nid)
    _wpa("save_config")
    return code == 0 and "FAIL" not in out, _perm_hint(err) if code else ("" if "FAIL" not in out else "wpa_supplicant refused it")


# ---- common entry points ---------------------------------------------------------
def wifi_status():
    b = wifi_backend()
    saved = []
    try:
        saved = _nm_saved() if b == "nm" else (_wpa_saved() if b == "wpa" else [])
    except Exception:
        saved = []
    w = STATE["wifi"] or {}
    ip = wifi_ip() if b else ""
    act = next((x for x in saved if x["active"]), None)            # the network manager knows best which network is in use
    import socket
    host = socket.gethostname()
    names = {x["ssid"] for x in saved}
    scan = [dict(n, active=(n["ssid"] == act["ssid"]) if act else n["active"], saved=n["ssid"] in names) for n in WIFI["scan"]]
    scan.sort(key=lambda n: (not n["active"], -n["signal"]))
    return {"backend": b, "iface": WIFI["iface"], "saved": saved, "scan": scan, "scan_time": WIFI["scan_time"],
            "job": WIFI["job"], "job_ok": WIFI["job_ok"], "busy": WIFI["busy"], "ssid": act["ssid"] if act else w.get("ssid", ""),
            "connected": bool(act) or w.get("connected", False),
            "ip": ip, "address": page_address(ip), "local_name": f"{host}.local", "port": CFG["web_port"],
            "https": bool(WEB_OPTS.get("https"))}


def wifi_scan():
    b = wifi_backend()
    if not b:
        return False, "Wi-Fi management not available (NetworkManager / wpa_supplicant not found)"
    if not _WIFI_LOCK.acquire(blocking=False):
        return False, "busy"
    try:
        nets = _nm_scan() if b == "nm" else _wpa_scan()
        saved = {s["ssid"] for s in (_nm_saved() if b == "nm" else _wpa_saved())}
        for n in nets:
            n["saved"] = n["ssid"] in saved; n["bars"] = _bars_from_pct(n["signal"])
        nets.sort(key=lambda n: (not n["active"], -n["signal"]))
        WIFI["scan"] = nets[:40]; WIFI["scan_time"] = time.time()
        log_event("sys", f"Wi-Fi scan: {len(nets)} network(s)")
        return True, ""
    except Exception as e:
        return False, str(e)[:200]
    finally:
        _WIFI_LOCK.release()


def _valid(ssid, password):
    if not isinstance(ssid, str) or not ssid or len(ssid.encode()) > 32 or any(ord(c) < 32 for c in ssid):
        return "invalid network name"
    if password and (not isinstance(password, str) or not 8 <= len(password) <= 63 or any(ord(c) < 32 for c in password)):
        return "the password must have 8 to 63 characters"
    return ""


def wifi_save(ssid, password="", preferred=True):
    err = _valid(ssid, password)
    if err:
        return False, err
    b = wifi_backend()
    if not b:
        return False, "Wi-Fi management not available (NetworkManager / wpa_supplicant not found)"
    with _WIFI_LOCK:
        ok, msg = _nm_save(ssid, password, preferred) if b == "nm" else _wpa_save(ssid, password, preferred)
    if ok:
        log_event("sys", f"Wi-Fi network saved: {ssid} (connects automatically{', preferred' if preferred else ''})")
    return ok, msg


def wifi_forget(sid):
    b = wifi_backend()
    if not b or not isinstance(sid, str) or not re.fullmatch(r"[0-9A-Za-z\-]{1,40}", sid):
        return False, "unknown network"
    with _WIFI_LOCK:
        if b == "nm":
            ok, msg = _nm_forget(sid)
        else:
            code, out, err = _wpa("remove_network", sid); _wpa("save_config")
            ok, msg = code == 0 and "FAIL" not in out, _perm_hint(err)
    if ok:
        log_event("sys", "Wi-Fi network removed")
    return ok, msg


def wifi_connect(ssid, password="", preferred=True):
    """Switch to another network in the background. If it does not work within ~45 s, go back to the previous one."""
    err = _valid(ssid, password)
    if err:
        return False, err
    b = wifi_backend()
    if not b:
        return False, "Wi-Fi management not available (NetworkManager / wpa_supplicant not found)"
    if WIFI["busy"]:
        return False, "busy"
    WIFI["busy"] = True; WIFI["job"] = f"connecting to {ssid}…"; WIFI["job_ok"] = None

    def work():
        try:
            with _WIFI_LOCK:
                prev = next((s for s in (_nm_saved() if b == "nm" else _wpa_saved()) if s["active"]), None)
                log_event("sys", f"Wi-Fi: switching to {ssid}" + (f" (from {prev['ssid']})" if prev else ""))
                if b == "nm":
                    ok, msg = _nm_connect_now(ssid, password)
                    if ok:
                        _nm_save(ssid, "", preferred)          # keep it for automatic connection later
                else:
                    ok, msg = _wpa_save(ssid, password, preferred, select=True)
                    if ok:                                   # wpa_cli returns at once: wait for the association
                        ok = False
                        for _ in range(30):
                            time.sleep(1.5)
                            st = _wpa("status")[1]
                            if f"ssid={ssid}" in st and "wpa_state=COMPLETED" in st:
                                ok = True; break
                        msg = "" if ok else "could not connect (wrong password or too far away?)"
                if ok:
                    for _ in range(10):                      # wait for an address
                        ip = wifi_ip()
                        if ip:
                            break
                        time.sleep(1)
                    WIFI["job"] = f"connected to {ssid}" + (f" · {page_address(ip)}" if ip else ""); WIFI["job_ok"] = True
                    log_event("sys", WIFI["job"])
                else:
                    back = ""
                    if prev and prev["ssid"] != ssid:
                        if b == "nm":
                            back = " - back on " + prev["ssid"] if _nm_up(prev["id"]) else " - previous network did not come back"
                        else:
                            _wpa("select_network", prev["id"]); [_wpa("enable_network", s["id"]) for s in _wpa_saved()]; _wpa("save_config")
                            back = " - back on " + prev["ssid"]
                    WIFI["job"] = f"failed: {msg or 'could not connect'}{back}"; WIFI["job_ok"] = False
                    log_event("sys", f"Wi-Fi: {ssid} failed ({msg}){back}")
        except Exception as e:
            WIFI["job"] = "failed: " + str(e)[:150]; WIFI["job_ok"] = False
        finally:
            WIFI["busy"] = False; WIFI["refresh"] = True
    threading.Thread(target=work, daemon=True).start()
    return True, ""


POLKIT_RULE = """// Motion Watch: allow user "{user}" to manage Wi-Fi / the own hotspot (NetworkManager), the clock (timedated)
// and to shut down / restart the Pi (logind)
polkit.addRule(function(action, subject) {{
    if ((action.id.indexOf("org.freedesktop.NetworkManager.") == 0 || action.id.indexOf("org.freedesktop.timedate1.") == 0
         || action.id == "org.freedesktop.login1.set-self-linger" || action.id.indexOf("org.freedesktop.login1.power-off") == 0
         || action.id.indexOf("org.freedesktop.login1.reboot") == 0) && subject.user == "{user}") {{
        return polkit.Result.YES;
    }}
}});
"""


def allow_wifi():
    """--allow-wifi: one-time permission so Motion Watch may change Wi-Fi without running as root."""
    user = os.environ.get("SUDO_USER") or os.environ.get("USER") or "pi"
    path = "/etc/polkit-1/rules.d/50-motionwatch-wifi.rules"
    if not hasattr(os, "geteuid") or os.geteuid() != 0:
        print(f"Needs root. Run:  sudo {sys.executable} {os.path.abspath(__file__)} --allow-wifi"); return 1
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            f.write(POLKIT_RULE.format(user=user))
    except OSError as e:
        print(f"Could not write {path}: {e}"); return 1
    subprocess.run(["systemctl", "restart", "polkit"], capture_output=True)
    subprocess.run(["loginctl", "enable-linger", user], capture_output=True)       # autostart without login
    try:                                     # hardware watchdog: if the whole Pi freezes, it restarts by itself after 15 s
        os.makedirs("/etc/systemd/system.conf.d", exist_ok=True)
        with open("/etc/systemd/system.conf.d/90-motionwatch-watchdog.conf", "w") as f:
            f.write("# Motion Watch: restart the Pi if it freezes\n[Manager]\nRuntimeWatchdogSec=15s\n")
        subprocess.run(["systemctl", "daemon-reexec"], capture_output=True)
        print("Hardware watchdog on: a frozen Pi restarts by itself.")
    except OSError as e:
        print(f"Hardware watchdog not set: {e}")
    print(f"User '{user}' may now manage Wi-Fi, the own hotspot, the clock, the autostart and shut down / restart the Pi ({path}).")
    return 0


# ----------------------------------------------------------------------------
# Own Wi-Fi of the Pi (access point / hotspot): the phone connects directly to the Pi - works without any mobile network.
#   NetworkManager connection "MotionWatch-Hotspot" (WPA2, 2.4 GHz for range). The page is then at http://10.42.0.1:<port>/
# ----------------------------------------------------------------------------
HOTSPOT_CON = "MotionWatch-Hotspot"
_PW_ALPHA = "abcdefghjkmnpqrstuvwxyz23456789"           # no 0/O, 1/l/i: easy to type on a phone


def hotspot_password():
    pw = CFG["hotspot_password"]
    if not (isinstance(pw, str) and 8 <= len(pw) <= 63):
        import secrets
        pw = "".join(secrets.choice(_PW_ALPHA) for _ in range(10))
        CFG["hotspot_password"] = pw; save_settings()
    return pw


def _nm_active_names():
    code, out, _e = _run(["nmcli", "-t", "-f", "NAME,DEVICE", "connection", "show", "--active"], 10)
    return [_nm_split(l)[0] for l in out.splitlines()] if code == 0 else []


def _hotspot_clients(iface):
    code, out, _e = _run(["iw", "dev", iface, "station", "dump"], 5)
    return sum(1 for l in out.splitlines() if l.startswith("Station")) if code == 0 else 0


def hotspot_refresh():
    b = wifi_backend()
    on = b == "nm" and HOTSPOT_CON in _nm_active_names()
    ap_if = WIFI.get("ap_iface") or WIFI["iface"]
    STATE["hotspot"] = {"on": on, "ssid": CFG["hotspot_ssid"] if on else "", "clients": _hotspot_clients(ap_if) if on else 0,
                        "ip": wifi_ip(ap_if) if on else "", "repeater": bool(on and DUAL["on"]), "busy": WIFI.get("hs_busy", False), "available": b == "nm", "msg": WIFI.get("hs_msg", "")}
    return STATE["hotspot"]


def hotspot_set(on, persist=True):
    """Switch the own Wi-Fi on / off (blocking, a few seconds). Off = NetworkManager goes back to the known networks."""
    b = wifi_backend()
    if b != "nm":
        return False, "the own Wi-Fi needs NetworkManager (Raspberry Pi OS Bookworm or newer)"
    iface, ssid = (WIFI.get("ap_iface") if DUAL["on"] else "") or WIFI["iface"], CFG["hotspot_ssid"] or "MotionWatch"
    with _WIFI_LOCK:
        if on:
            pw = hotspot_password()
            code, out, _e = _run(["nmcli", "-t", "-f", "NAME", "connection", "show"], 10)
            exists = HOTSPOT_CON in [_nm_split(l)[0] for l in out.splitlines()]
            sec = ["wifi-sec.key-mgmt", "wpa-psk", "wifi-sec.psk", pw, "wifi-sec.proto", "rsn", "wifi-sec.pairwise", "ccmp", "wifi-sec.group", "ccmp"]
            if exists:
                code, out, err = _run(["nmcli", "connection", "modify", "id", HOTSPOT_CON, "802-11-wireless.ssid", ssid,
                                       "connection.interface-name", iface] + sec, 20)
            else:
                code, out, err = _run(["nmcli", "connection", "add", "type", "wifi", "ifname", iface, "con-name", HOTSPOT_CON, "autoconnect", "no",
                                       "ssid", ssid, "802-11-wireless.mode", "ap", "802-11-wireless.band", "bg", "ipv4.method", "shared"] + sec, 20)
            if code == 0:
                code, out, err = _run(["nmcli", "--wait", "40", "connection", "up", "id", HOTSPOT_CON], 50)
        else:
            code, out, err = _run(["nmcli", "connection", "down", "id", HOTSPOT_CON], 30)
            if code != 0 and "not an active connection" in (err or "").lower():
                code = 0
    ok = code == 0
    if ok:
        if persist:
            CFG["hotspot_on"] = on; save_settings()
        log_event("sys", f"Own Wi-Fi «{ssid}» switched ON (page: {page_address('10.42.0.1')})" if on else "Own Wi-Fi switched OFF - back to the known networks")
    else:
        log_event("sys", f"Own Wi-Fi could not be switched {'on' if on else 'off'}: {_perm_hint(err)}")
    WIFI["refresh"] = True
    return ok, "" if ok else _perm_hint(err)


def hotspot_switch_later(on, delay=1.5):
    """In the background, a little later: the web page that asked must still get its answer before the network changes."""
    WIFI["hs_busy"] = True; WIFI["hs_msg"] = ""
    def work():
        time.sleep(delay)
        try:
            ok, err = hotspot_set(on)
            WIFI["hs_msg"] = "" if ok else err
        finally:
            WIFI["hs_busy"] = False
            try:
                hotspot_refresh()
            except Exception:
                pass
    threading.Thread(target=work, daemon=True).start()


# ----------------------------------------------------------------------------
# Clock from the phone: the Pi has no clock with a battery (except Pi 5 with battery). Without internet it starts with a
# wrong time, then schedules, sunset and the names of recordings are wrong. Every page sends the time of the phone.
# ----------------------------------------------------------------------------
TIME = {"last": 0.0}


def _ntp_synced():
    code, out, _e = _run(["timedatectl", "show", "-p", "NTPSynchronized", "--value"], 5)
    return code == 0 and out.strip() == "yes"


def _set_timezone(tz):
    if not (isinstance(tz, str) and re.fullmatch(r"[A-Za-z_]+(/[A-Za-z0-9_+\-]+){0,2}", tz) and os.path.isfile(os.path.join("/usr/share/zoneinfo", tz))):
        return ""
    code, out, _e = _run(["timedatectl", "show", "-p", "Timezone", "--value"], 5)
    if code != 0 or out.strip() == tz:
        return ""
    code, out, err = _run(["timedatectl", "set-timezone", tz], 10)
    if code == 0:
        try:
            time.tzset()
        except AttributeError:
            pass
        log_event("sys", f"Time zone set from the phone: {tz}")
        return f"time zone {tz}"
    return ""


def _set_clock(epoch):
    stamp = datetime.fromtimestamp(epoch).strftime("%Y-%m-%d %H:%M:%S")
    if hasattr(os, "geteuid") and os.geteuid() == 0 and shutil.which("date"):
        code, out, err = _run(["date", "-s", "@%d" % int(epoch)], 10)
        return code == 0, err
    code, out, err = _run(["timedatectl", "set-time", stamp], 10)
    if code != 0 and "automatic time synchronization" in (err or "").lower():
        _run(["timedatectl", "set-ntp", "false"], 10)              # allowed to set by hand only while NTP is off ...
        code, out, err = _run(["timedatectl", "set-time", stamp], 10)
        _run(["timedatectl", "set-ntp", "true"], 10)               # ... and it takes over again as soon as there is internet
    return code == 0, err


# ---- location (GPS) from the phone: photos get EXIF GPS data, videos a location tag ----
GPS = {"lat": None, "lon": None, "acc": None, "t": 0.0}
GPSMOD = {"lat": None, "lon": None, "t": 0.0, "sats": None, "status": "off", "via": "", "anchor": None, "away": 0, "alarm_t": 0.0, "upd_t": 0.0}
GPS_DEFAULT = (47.37, 8.54)                      # the factory setting is not a real location


def gps_set(lat, lon, acc=None):
    """A position sent by the browser of a phone (only https pages may read the location)."""
    try:
        lat, lon = float(lat), float(lon); acc = float(acc) if acc is not None else None
    except (TypeError, ValueError):
        return False, "invalid value"
    if not (-90 <= lat <= 90 and -180 <= lon <= 180) or not (math.isfinite(lat) and math.isfinite(lon)):
        return False, "invalid value"
    if not CFG["gps_phone"]:
        return False, "off"
    first = GPS["lat"] is None
    GPS.update(lat=round(lat, 6), lon=round(lon, 6), acc=round(acc) if acc is not None else None, t=time.time())
    if abs(lat - float(CFG["latitude"])) > 0.01 or abs(lon - float(CFG["longitude"])) > 0.01:     # ~1 km: new place
        CFG["latitude"], CFG["longitude"] = round(lat, 4), round(lon, 4); save_settings()
        log_event("sys", f"Location from the phone: {lat:.4f}, {lon:.4f}")
    elif first:
        log_event("sys", f"Location from the phone: {lat:.4f}, {lon:.4f}")
    return True, ""


def gps_now():
    """(lat, lon, source) for the pictures: the phone (the last 6 hours), otherwise the place in the settings
    (not the factory value), otherwise None."""
    if CFG["gpsmod_on"] and GPSMOD["lat"] is not None and time.time() - GPSMOD["t"] < 300:
        return GPSMOD["lat"], GPSMOD["lon"], "module"
    if CFG["gps_phone"] and GPS["lat"] is not None and time.time() - GPS["t"] < 6 * 3600:
        return GPS["lat"], GPS["lon"], "phone"
    lat, lon = float(CFG["latitude"]), float(CFG["longitude"])
    if (round(lat, 2), round(lon, 2)) != GPS_DEFAULT:
        return lat, lon, "fixed"
    return None


def gps_state():
    g = gps_now()
    if g and g[2] == "module":
        return {"lat": g[0], "lon": g[1], "src": "module", "age": int(time.time() - GPSMOD["t"]), "acc": None, "sats": GPSMOD["sats"]}
    return {"lat": g[0], "lon": g[1], "src": g[2], "age": int(time.time() - GPS["t"]) if g[2] == "phone" else None,
            "acc": GPS["acc"] if g[2] == "phone" else None} if g else None


def exif_gps(lat, lon):
    """A small EXIF block (APP1) with the GPS position - photo apps then show the picture on the map."""
    import struct

    def rat(v):
        v = abs(v); d = int(v); m = int((v - d) * 60); sec = round(((v - d) * 60 - m) * 60 * 1000)
        return struct.pack("<6I", d, 1, m, 1, sec, 1000)

    ifd0 = struct.pack("<H", 1) + struct.pack("<HHII", 0x8825, 4, 1, 26) + struct.pack("<I", 0)
    gps = struct.pack("<H", 5)
    gps += struct.pack("<HHI", 0x0000, 1, 4) + bytes((2, 3, 0, 0))
    gps += struct.pack("<HHI", 0x0001, 2, 2) + (b"N" if lat >= 0 else b"S") + b"\0\0\0"
    gps += struct.pack("<HHII", 0x0002, 5, 3, 92)
    gps += struct.pack("<HHI", 0x0003, 2, 2) + (b"E" if lon >= 0 else b"W") + b"\0\0\0"
    gps += struct.pack("<HHII", 0x0004, 5, 3, 116) + struct.pack("<I", 0)
    tiff = b"II*\0" + struct.pack("<I", 8) + ifd0 + gps + rat(lat) + rat(lon)
    body = b"Exif\0\0" + tiff
    return b"\xff\xe1" + struct.pack(">H", len(body) + 2) + body


def gps_tag_jpg(path):
    """Add the GPS position to a saved JPEG (when wanted and known)."""
    g = gps_now() if CFG["gps_tag"] else None
    if not g:
        return
    try:
        with open(path, "rb") as f:
            data = f.read()
        if data[:2] != b"\xff\xd8" or b"Exif\0\0" in data[:64]:
            return
        tmp = path + ".gps"
        with open(tmp, "wb") as f:
            f.write(data[:2] + exif_gps(g[0], g[1]) + data[2:])
        os.replace(tmp, path)
    except OSError:
        pass


def gps_iso6709(g):
    return f"{g[0]:+08.4f}{g[1]:+09.4f}/"


def gps_tag_video(path):
    """Write the location into a finished MP4 (copied, not encoded again)."""
    g = gps_now() if CFG["gps_tag"] else None
    if not g or not shutil.which("ffmpeg") or not os.path.isfile(path):
        return
    name = os.path.basename(path); tmp = os.path.join(os.path.dirname(path), "gps_" + name)
    LIVE_RECS.add(name)
    try:
        r = subprocess.run((["nice", "-n", "10"] if shutil.which("nice") else []) + ["ffmpeg", "-y", "-loglevel", "error", "-i", path, "-map", "0",
                           "-c", "copy", "-metadata", "location=" + gps_iso6709(g), "-metadata", "location-eng=" + gps_iso6709(g),
                           "-movflags", "+faststart", tmp], capture_output=True, timeout=600)
        if r.returncode == 0 and os.path.isfile(tmp) and os.path.getsize(tmp) > 1000:
            os.replace(tmp, path)
    except (OSError, subprocess.SubprocessError):
        pass
    finally:
        LIVE_RECS.discard(name)
        try:
            os.remove(tmp)
        except OSError:
            pass


