def simple_hidden(key, sec=None):
    """True when Simple is on and this setting (or section) belongs to Expert only."""
    if not CFG.get("ui_simple"):
        return False
    return (sec is not None and sec not in SIMPLE_SECTIONS) or (key is not None and key not in SIMPLE_KEYS)


NIGHT_SET = {"detection_on": True, "ai_enabled": True, "record": True, "snapshot_on_person": True, "notify_on": True,
             "notify_prealarm": True, "lowlight_auto": True, "nightvision_auto": True, "report_on": True, "diary_on": True,
             "eco_on": True, "timelapse_on": False}


def night_guard(lang=None):
    """«Guard tonight»: what a night needs on, armed after the countdown; returns what was done and what is missing."""
    L = norm_lang(lang) if lang else cur_lang()
    done = []
    for k, v in NIGHT_SET.items():
        if k in CFG and CFG[k] != v:
            CFG[k] = v; sched_user_changed(k)
    if (STATE.get("audio") or {}).get("status") == "listening" and not CFG["noise_alarm"]:
        CFG["noise_alarm"] = True; done.append(tr("Noise alarm on", L))
    if STATE.get("thermal") == "connected" and not CFG["thermal_alarm"]:
        CFG["thermal_alarm"] = True; done.append(tr("Thermal alarm on", L))
    save_settings()
    done = [tr("Detection, AI and recordings on", L), tr("Push messages on", L), tr("Night vision and low light automatic", L),
            tr("Night report in the morning", L) + f" ({int(CFG['report_hour']):02d}:00)", tr("Power saving on", L)] + done
    arm()
    d = int(float(CFG["arm_delay"]))
    done.append(trf("Armed in {s} s - leave the area now", L, s=d) if d else tr("Armed", L))
    h = health_check(L)
    miss = [{"icon": x["icon"], "title": x["title"], "text": x["text"], "tip": x["tip"], "level": x["level"]}
            for x in h["items"] if x["level"] == "bad" or (x["level"] == "warn" and x["id"] in ("servo", "net", "power", "temp", "disk", "batt"))]
    log_event("sys", "Guard tonight: armed" + (f", {len(miss)} problem(s) open" if miss else ""))
    return {"ok": True, "done": done, "missing": miss}


def camping_set(on, hotspot_delay=2.0):
    netauto_pause()
    if on and not CFG["camping"]:
        prev = {k: CFG[k] for k in list(CAMPING_SET) + ["thermal_alarm", "armed", "hotspot_on"]}
        CFG["camping_prev"] = prev
        for k, v in CAMPING_SET.items():
            CFG[k] = v; sched_user_changed(k)
        if CFG["thermal_source"]:
            CFG["thermal_alarm"] = True
        CFG["camping"] = True
        log_event("sys", "Camping profile ON")
        arm()
        if wifi_backend() == "nm" and not STATE["hotspot"].get("on"):
            hotspot_switch_later(True, hotspot_delay)
    elif not on and CFG["camping"]:
        prev = CFG["camping_prev"] if isinstance(CFG["camping_prev"], dict) else {}
        for k, v in prev.items():
            if k in CFG and k not in ("armed", "hotspot_on") and isinstance(v, type(CFG[k])):
                CFG[k] = v
        CFG["camping"] = False; CFG["camping_prev"] = {}
        log_event("sys", "Camping profile OFF - previous settings restored")
        if prev.get("armed", True):
            CFG["armed"] = True; ARM["at"] = 0.0; ARM["announced"] = True; arm_tick()
        else:
            disarm()
        if not prev.get("hotspot_on", False) and STATE["hotspot"].get("on"):
            hotspot_switch_later(False, hotspot_delay)
    save_settings()
    return True, ""


# ----------------------------------------------------------------------------
# Autostart: when switched on, the Pi starts Motion Watch when it boots (no screen needed) and switches the own Wi-Fi on.
# When switched off, nothing starts at boot and the Pi joins its known networks as usual (the own Wi-Fi never starts by itself).
#   normal user: systemd USER service  ~/.config/systemd/user/motionwatch.service  (+ "linger" so it starts without login)
#   root (sudo): systemd system service /etc/systemd/system/motionwatch.service
# ----------------------------------------------------------------------------
SERVICE_NAME = "motionwatch.service"
AUTOSTART = {"on": False, "mode": "", "msg": "", "path": ""}


def _is_root():
    return hasattr(os, "geteuid") and os.geteuid() == 0


def _run_user():
    import getpass
    return os.environ.get("SUDO_USER") or os.environ.get("USER") or getpass.getuser()


def _unit_path(mode):
    if mode == "system":
        return "/etc/systemd/system/" + SERVICE_NAME
    return os.path.join(os.path.expanduser("~"), ".config", "systemd", "user", SERVICE_NAME)


def _autostart_mode():
    return "system" if (_is_root() or os.path.isfile(_unit_path("system"))) else "user"


def _systemctl(mode, *args, timeout=30):
    return _run(["systemctl"] + (["--user"] if mode == "user" else []) + list(args), timeout)


INSTANCE = {"fd": None, "stopped": None}


def instance_lock(port):
    """Only one Motion Watch per web port (two would fight over camera, servos and port). True = we may run."""
    try:
        import fcntl
    except ImportError:
        return True
    p = os.path.join(tempfile.gettempdir(), f"motionwatch-{int(port)}.lock")
    try:
        fd = os.open(p, os.O_RDWR | os.O_CREAT, 0o666)
    except OSError:
        try:
            fd = os.open(p, os.O_RDONLY)
        except OSError:
            return True
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        os.close(fd); return False
    INSTANCE["fd"] = fd
    try:
        os.chmod(p, 0o666)
    except OSError:
        pass
    return True


def instance_takeover(port, gui):
    """Another Motion Watch holds the port. Started by hand with a window while the autostart service runs: ask and take
    over (the service is stopped now and started again when this window closes). Returns True when we may run."""
    url = f"http://127.0.0.1:{int(port)}/"
    mode = _autostart_mode()
    code, out, _e = _systemctl(mode, "is-active", SERVICE_NAME, timeout=10) if shutil.which("systemctl") else (1, "", "")
    service = out.strip() == "active"
    msg = (tr("Motion Watch is already running") + (" " + tr("in the background (autostart, without a window).") if service else ".")
           + "\n\n" + tr("Web page") + ": " + url)
    if not (gui and GUI_OK and service):
        print(msg.replace("\n\n", " - ")); return False
    try:
        r = tk.Tk(); r.withdraw()
        yes = messagebox.askyesno("Motion Watch", msg + "\n\n" + tr("Open the window here instead? The background service is stopped for "
                                  "that and starts again when you close the window."), parent=r)
        r.destroy()
    except Exception:
        yes = False
    if not yes:
        try:
            import webbrowser
            webbrowser.open(url)
        except Exception:
            pass
        return False
    c2, _o, e2 = _systemctl(mode, "stop", SERVICE_NAME, timeout=40)
    if c2 != 0:
        print(tr("The background service could not be stopped") + ": " + (e2 or "")[:160]); return False
    for _ in range(60):
        if instance_lock(port):
            INSTANCE["stopped"] = mode
            atexit.register(instance_restart_service)
            return True
        time.sleep(0.5)
    return False


def instance_restart_service():
    """The window closes: the autostart service takes over again (not when the Pi is shutting down)."""
    if INSTANCE.get("stopped") and not POWER.get("pending"):
        try:
            subprocess.Popen(["systemctl"] + (["--user"] if INSTANCE["stopped"] == "user" else []) + ["start", "--no-block", SERVICE_NAME],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)
        except OSError:
            pass


def autostart_args():
    """The options this program was started with, for the service (without one-time actions), plus --headless --boot."""
    drop = {"--print-service", "--install-service", "--allow-wifi", "--boot", "--headless", "--no-web", "--web"}
    return [x for x in sys.argv[1:] if x not in drop] + ["--headless", "--boot"]


HEART = {"t": time.time()}           # the camera loop is alive (systemd watchdog)


def sd_notify(msg):
    addr = os.environ.get("NOTIFY_SOCKET")
    if not addr:
        return False
    import socket
    if addr[0] == "@":
        addr = "\0" + addr[1:]
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM) as sk:
            sk.connect(addr); sk.sendall(msg.encode())
        return True
    except OSError:
        return False


def watchdog_loop():
    """Started by the autostart (systemd, WatchdogSec): "still alive" every 20 s while the camera loop runs. If the program
    hangs (e.g. a camera that blocks forever), systemd restarts it after 2 minutes."""
    if not os.environ.get("NOTIFY_SOCKET"):
        return
    while True:
        if time.time() - HEART["t"] < 60:
            sd_notify("WATCHDOG=1")
        time.sleep(20)


def autostart_unit(mode):
    import shlex
    exe = " ".join(shlex.quote(x) for x in [sys.executable, os.path.abspath(__file__)] + autostart_args())
    # StartLimitIntervalSec=0: never give up (e.g. after a power cut the camera / network may need a while)
    if mode == "system":
        head = ("[Unit]\nDescription=Motion Watch (camera surveillance)\nAfter=network.target NetworkManager.service\n"
                "Wants=NetworkManager.service\nStartLimitIntervalSec=0\n\n")
        install = "WantedBy=multi-user.target"
    else:
        head = "[Unit]\nDescription=Motion Watch (camera surveillance)\nStartLimitIntervalSec=0\n\n"
        install = "WantedBy=default.target"
    return (head + "[Service]\nType=simple\n" + f"WorkingDirectory={HERE}\nExecStart={exe}\n"
            + f"Environment=PYTHONUNBUFFERED=1\nEnvironment=MOTIONWATCH_HOME={DATA_DIR}\n"
            + "Restart=always\nRestartSec=5\nWatchdogSec=120\nNotifyAccess=main\n\n[Install]\n" + install + "\n")


def desktop_notice(title, text, wait=300):
    """A small message on the desktop of the Pi (notification bubble), also from the background service (often root, before
    anybody is logged in): waits up to `wait` seconds for the desktop session, then sends it as that user. Background thread."""
    def users():
        out = []
        for d in sorted(glob.glob("/run/user/*")):
            try:
                uid = int(os.path.basename(d))
            except ValueError:
                continue
            if (uid >= 1000 or uid == os.getuid()) and os.path.exists(os.path.join(d, "bus")):
                out.append(uid)
        if os.getuid() != 0:
            out = [u for u in out if u == os.getuid()]
        return out

    def send(uid):
        import pwd
        env = dict(os.environ, DBUS_SESSION_BUS_ADDRESS=f"unix:path=/run/user/{uid}/bus", XDG_RUNTIME_DIR=f"/run/user/{uid}")
        kw = {}
        if os.getuid() == 0 and uid != 0:
            try:
                pw_ = pwd.getpwuid(uid); kw = {"user": uid, "group": pw_.pw_gid}; env["HOME"] = pw_.pw_dir; env["USER"] = pw_.pw_name
            except KeyError:
                return False
        gq = lambda x: "'" + str(x).replace("\\", "\\\\").replace("'", "\\'") + "'"     # GVariant text for gdbus
        icon = os.path.join(tempfile.gettempdir(), "motionwatch_icon.png")
        try:
            if not os.path.exists(icon):
                with open(icon, "wb") as f:
                    f.write(app_icon_png(96))
                os.chmod(icon, 0o644)
        except Exception:
            icon = "camera-web"
        if shutil.which("notify-send"):
            cmd = ["notify-send", "-a", "Motion Watch", "-i", icon, "-t", "12000", title, text]
        elif shutil.which("gdbus"):
            cmd = ["gdbus", "call", "--session", "--dest", "org.freedesktop.Notifications", "--object-path", "/org/freedesktop/Notifications",
                   "--method", "org.freedesktop.Notifications.Notify", gq("Motion Watch"), "0", gq(icon), gq(title), gq(text), "[]", "{}", "12000"]
        else:
            return None                                      # nothing on this system can show a message
        try:
            return subprocess.run(cmd, env=env, capture_output=True, timeout=15, **kw).returncode == 0
        except (OSError, subprocess.SubprocessError, ValueError):
            return False

    def run():
        end = time.time() + wait
        while time.time() < end:
            for uid in users():
                r = send(uid)
                if r:
                    log_event("sys", "Desktop message shown: " + text[:80]); return
                if r is None:
                    return
            time.sleep(10)
    threading.Thread(target=run, daemon=True, name="desktop-notice").start()


def autostart_refresh():
    mode = _autostart_mode()
    path = _unit_path(mode)
    code, out, _e = _systemctl(mode, "is-enabled", SERVICE_NAME, timeout=10)
    AUTOSTART.update(on=out.strip() == "enabled", mode=mode, path=path if os.path.isfile(path) else "")
    STATE["autostart"] = dict(AUTOSTART)
    return STATE["autostart"]


def autostart_set(on):
    if shutil.which("systemctl") is None:
        return False, "autostart needs systemd (Raspberry Pi OS)"
    mode = _autostart_mode()
    path = _unit_path(mode)
    if mode == "system" and not _is_root():
        if on:
            return False, "a system service exists - change it with sudo, or remove it: sudo systemctl disable --now motionwatch"
        code, out, err = _systemctl(mode, "disable", SERVICE_NAME)
        ok = code == 0
        msg = "" if ok else "the system service can only be switched off with sudo: sudo systemctl disable motionwatch"
    elif on:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w") as f:
                f.write(autostart_unit(mode))
            os.chmod(path, 0o600)                         # the web password may be in the command line
        except OSError as e:
            return False, f"could not write {path}: {e}"
        _systemctl(mode, "daemon-reload")
        code, out, err = _systemctl(mode, "enable", SERVICE_NAME)
        ok, msg = code == 0, "" if code == 0 else (err or "systemctl enable failed")[:200]
        if ok and mode == "user":                         # start at boot even when nobody logs in
            c2, o2, e2 = _run(["loginctl", "enable-linger", _run_user()], 15)
            if c2 != 0:
                msg = ("autostart is on, but it only starts after a login until you run once: "
                       f"sudo loginctl enable-linger {_run_user()}   (or: sudo python3 {os.path.basename(__file__)} --allow-wifi)")
    else:
        code, out, err = _systemctl(mode, "disable", SERVICE_NAME)
        ok, msg = code == 0, "" if code == 0 else (err or "systemctl disable failed")[:200]
    if ok:
        CFG["autostart"] = on; save_settings()
        log_event("sys", "Autostart ON: starts at boot and switches the own Wi-Fi on" if on else
                         "Autostart OFF: nothing starts at boot, the Pi joins its known networks")
    AUTOSTART["msg"] = msg
    autostart_refresh()
    return ok, msg


def autostart_check_boot():
    """Autostart as a user service needs 'linger', otherwise it only starts after somebody logs in (e.g. not after a power
    cut without a desktop login). Checked at every start: switched on when allowed, otherwise a clear hint."""
    if not CFG["autostart"] or _autostart_mode() != "user" or shutil.which("loginctl") is None:
        return
    user = _run_user()
    code, out, _e = _run(["loginctl", "show-user", user, "-p", "Linger"], 10)
    if code == 0 and "Linger=yes" in out:
        return
    c2, _o, _e2 = _run(["loginctl", "enable-linger", user], 15)
    if c2 == 0:
        log_event("sys", "Autostart: start at boot without login switched on (linger)")
        return
    AUTOSTART["msg"] = ("autostart is on, but it only starts after a login until you run once: "
                        f"sudo loginctl enable-linger {user}   (or: sudo python3 {os.path.basename(__file__)} --allow-wifi)")
    log_event("sys", "Autostart: " + AUTOSTART["msg"])


def autostart_follow_version():
    """A new version was started by hand while autostart is on: let the service start this file from now on."""
    if not CFG["autostart"]:
        return
    mode = _autostart_mode()
    path = _unit_path(mode)
    if mode == "system" and not _is_root():
        return
    try:
        with open(path) as f:
            old = f.read()
    except OSError:
        return
    if old != autostart_unit(mode):                 # new file or new unit content (e.g. the watchdog of 1.8.2)
        try:
            with open(path, "w") as f:
                f.write(autostart_unit(mode))
            os.chmod(path, 0o600)
            _systemctl(mode, "daemon-reload")
            log_event("sys", f"Autostart now starts this version: {os.path.basename(__file__)}")
        except OSError:
            pass


def boot_hotspot():
    """Started at boot (--boot): switch the own Wi-Fi on. NetworkManager may still be starting, so try a few times."""
    def work():
        time.sleep(3.0)
        for attempt in range(8):
            ok, err = hotspot_set(True, persist=False)
            if ok:
                return
            WIFI["hs_msg"] = err
            time.sleep(10.0)
        log_event("sys", "Own Wi-Fi could not be switched on at boot")
    threading.Thread(target=work, daemon=True).start()


# ----------------------------------------------------------------------------
# Second Wi-Fi adapter (USB stick): one adapter makes the own Wi-Fi, the other one joins a known network (campsite, phone)
# -> repeater: the devices in the own Wi-Fi have internet (NetworkManager "shared" does the routing). Also: automatic change
# to another known network when the internet is gone, devices in the own Wi-Fi without internet (cameras), and a guard
# that listens for Wi-Fi jamming (deauthentication attacks) when the stick can listen ("monitor mode").
# ----------------------------------------------------------------------------
DUAL = {"on": False, "ap": "", "up": "", "adapters": [], "t": 0.0, "msg": "", "log": [], "sig": [], "drops": [], "unstable": False,
        "switch_t": 0.0, "offline_since": None, "iso": "", "iso_msg": ""}
WGUARD = {"state": "off", "iface": "", "phy": "", "msg": "", "deauth_min": [], "deauth_now": 0, "all_now": 0, "frames": 0,
          "last_alarm": 0.0, "alarms": [], "count_on": False, "count_now": None, "count_hist": [], "chan": None}
WIFI_CHIPS = {"brcmfmac": ("Broadcom (built in)", ""),
              "mt76x2u": ("MediaTek MT7612U", "very good: own Wi-Fi, 5 GHz and listening (monitor) work"),
              "mt7921u": ("MediaTek MT7921AU (Wi-Fi 6)", "very good: own Wi-Fi, 5 GHz and listening (monitor) work"),
              "mt76x0u": ("MediaTek MT7610U", "good: 5 GHz and listening (monitor) work"),
              "mt7601u": ("MediaTek MT7601U", "simple stick: only 2.4 GHz"),
              "rt2800usb": ("Ralink RT5370 / RT3070", "only 2.4 GHz, listening (monitor) works"),
              "ath9k_htc": ("Atheros AR9271", "only 2.4 GHz, listening (monitor) works"),
              "rtl8xxxu": ("Realtek (rtl8xxxu)", "simple driver: no own Wi-Fi, no listening"),
              "r8188eu": ("Realtek RTL8188EU", "simple driver: no listening"),
              "rtw88_8821cu": ("Realtek RTL8811CU / RTL8821CU", "listening (monitor) mostly not possible"),
              "rtw88_8822bu": ("Realtek RTL8812BU / RTL8822BU", "listening (monitor) mostly not possible"),
              "rtw88_8723du": ("Realtek RTL8723DU", "only 2.4 GHz"),
              "rtl88xxau": ("Realtek RTL8812AU / RTL8821AU (extra driver)", "extra driver needed"),
              "8812au": ("Realtek RTL8812AU (extra driver)", "extra driver needed"),
              "88XXau": ("Realtek RTL8812AU / RTL8821AU (extra driver)", "extra driver needed")}


def _rd(p):
    try:
        with open(p) as f:
            return f.read().strip()
    except OSError:
        return ""


def _iw_phy(phy):
    """What the radio can do: kinds of use (AP = own Wi-Fi, monitor = listening), 5 GHz."""
    if not phy or shutil.which("iw") is None:
        return [], False, ""
    code, out, _e = _run(["iw", "phy", phy, "info"], 6)
    if code != 0:
        return [], False, ""
    modes, in_modes = [], False
    for ln in out.splitlines():
        s = ln.strip()
        if s.startswith("Supported interface modes"):
            in_modes = True; continue
        if in_modes:
            if s.startswith("* "):
                modes.append(s[2:].strip())
            else:
                in_modes = False
    five = bool(re.search(r"\b5[1-8]\d\d(\.\d+)? MHz \[\d+\](?![^\n]*disabled)", out))
    comb = ""
    m = re.search(r"valid interface combinations:(.*?)(?:\n\t[A-Z]|\Z)", out, re.S)
    if m:
        comb = " ".join(m.group(1).split())[:200]
    return modes, five, comb


def wifi_adapters():
    out = []
    for i in _wifi_ifaces():
        if i.startswith("mwmon"):
            continue
        base = f"/sys/class/net/{i}"
        dev = os.path.realpath(base + "/device") if os.path.exists(base + "/device") else ""
        usb = "/usb" in dev
        drv = os.path.basename(os.path.realpath(base + "/device/driver")) if os.path.exists(base + "/device/driver") else ""
        phy = _rd(base + "/phy80211/name")
        prod, vid = "", ""
        if usb:
            p = os.path.dirname(dev)
            vid = (_rd(p + "/idVendor") + ":" + _rd(p + "/idProduct")).strip(":")
            prod = (_rd(p + "/manufacturer") + " " + _rd(p + "/product")).strip()
        modes, five, comb = _iw_phy(phy)
        chip, note = WIFI_CHIPS.get(drv, (prod or drv or "?", ""))
        out.append({"iface": i, "usb": usb, "driver": drv, "chip": chip, "product": prod[:60], "usb_id": vid, "phy": phy,
                    "mac": _rd(base + "/address"), "ap": ("AP" in modes) if modes else None, "monitor": ("monitor" in modes) if modes else None,
                    "five": five, "note": note, "comb": comb, "up": _rd(base + "/operstate") == "up"})
    return out


def _nm_dev_autoconnect(iface, on):
    if iface and shutil.which("nmcli"):
        _run(["nmcli", "device", "set", iface, "autoconnect", "yes" if on else "no"], 10)


def dual_roles():
    """Which adapter does what. Default: the built-in one makes the own Wi-Fi (devices are near), the USB stick joins the
    campsite / phone network (it often has a better antenna and may hang higher on a cable)."""
    ads = wifi_adapters()
    DUAL["adapters"] = ads; DUAL["t"] = time.time()
    was = (DUAL["on"], DUAL["ap"], DUAL["up"])
    if len(ads) < 2 or not CFG.get("wifi_repeater") or wifi_backend() != "nm":
        DUAL.update(on=False, ap="", up="",
                    msg="" if len(ads) >= 2 or not ads else "only one Wi-Fi adapter")
        if len(ads) >= 2 and wifi_backend() != "nm":
            DUAL["msg"] = "needs NetworkManager"
        if was[0]:
            WIFI["iface"] = ads[0]["iface"] if ads else "wlan0"; WIFI.pop("ap_iface", None)
            for a in ads:
                _nm_dev_autoconnect(a["iface"], True)
            dual_log(tr("Second Wi-Fi adapter: off - back to one adapter"))
        DUAL["choice"] = None
        return DUAL
    names = [a["iface"] for a in ads]
    ch = DUAL.get("choice")
    if ch and ch[0] in names and ch[1] in names and ch[2] == bool(CFG.get("wifi_swap")):
        ap = next(a for a in ads if a["iface"] == ch[0]); up = next(a for a in ads if a["iface"] == ch[1])   # keep the roles once chosen
    else:
        # the adapter that is connected to a network now keeps that connection (the Pi must stay reachable);
        # only when none is connected the USB stick is used for the internet (often the better antenna)
        conn = [a for a in ads if (_iw_link(a["iface"]) or {}).get("connected")]
        intern = next((a for a in ads if not a["usb"]), ads[0])
        stick = next((a for a in ads if a is not intern), ads[1])
        if CFG.get("wifi_swap"):                         # «internet over the USB stick (better antenna)»
            up = stick
        else:
            up = conn[0] if conn else stick
        ap = next(a for a in ads if a is not up)
        if ap["ap"] is False and up["ap"]:
            ap, up = up, ap                                  # this adapter cannot make an own Wi-Fi
        DUAL["choice"] = (ap["iface"], up["iface"], bool(CFG.get("wifi_swap")))
    DUAL.update(on=True, ap=ap["iface"], up=up["iface"], msg="")
    WIFI["iface"] = up["iface"]; WIFI["ap_iface"] = ap["iface"]
    if was != (True, ap["iface"], up["iface"]):
        _nm_unbind(ap["iface"])                              # known networks bound to the own-Wi-Fi adapter may use the other one
        _nm_dev_autoconnect(ap["iface"], False)              # the own Wi-Fi adapter does not join networks by itself
        _nm_dev_autoconnect(up["iface"], True)
        DUAL["since"] = time.time(); DUAL["had_conn"] = bool((STATE.get("wifi") or {}).get("connected"))
        dual_log(trf("Second Wi-Fi adapter: own Wi-Fi on {ap} ({a}), internet over {up} ({b})", ap=ap["iface"], a=ap["chip"], up=up["iface"], b=up["chip"]))
        if STATE["hotspot"].get("on") and was[1] and was[1] != ap["iface"]:
            hotspot_switch_later(True, 0.5)                  # the own Wi-Fi moves to the other adapter
        WIFI["refresh"] = True
    return DUAL


def _nm_unbind(iface):
    """Saved networks that only work on one adapter (connection.interface-name, e.g. made by the Raspberry Pi Imager) may
    then be used by the other adapter too - otherwise the stick cannot join the home Wi-Fi."""
    if not iface or not shutil.which("nmcli"):
        return
    code, out, _e = _run(["nmcli", "-t", "-f", "UUID,TYPE", "connection", "show"], 10)
    if code != 0:
        return
    for ln in out.splitlines():
        f = _nm_split(ln)
        if len(f) < 2 or f[1] not in ("802-11-wireless", "wifi"):
            continue
        c2, o2, _e = _run(["nmcli", "-t", "-g", "connection.interface-name,802-11-wireless.mode,connection.id", "connection", "show", "uuid", f[0]], 10)
        g = o2.splitlines() if c2 == 0 else []
        if len(g) >= 2 and g[0].strip() == iface and g[1].strip() != "ap":
            if _run(["nmcli", "connection", "modify", "uuid", f[0], "connection.interface-name", ""], 10)[0] == 0:
                log_event("sys", f"Wi-Fi «{g[2] if len(g) > 2 else f[0]}» may now be used by every adapter")


def dual_safety():
    """Safety net: the repeater was switched on, but the Pi has had no connection to a network for 2.5 minutes since then
    -> switch it off again by itself, so the Pi becomes reachable again the old way."""
    if not DUAL["on"] or not DUAL.get("had_conn"):
        return
    since = DUAL.get("since") or 0
    if time.time() - since < 150 or time.time() - since > 600:
        return
    w = STATE.get("wifi") or {}
    if w.get("connected") or (STATE.get("net") or {}).get("online"):
        DUAL["had_conn"] = False                             # it works - the safety net is no longer needed
        return
    CFG["wifi_repeater"] = False; save_settings()
    DUAL["choice"] = None
    dual_roles()
    if not CFG.get("hotspot_on"):
        hotspot_set(False, persist=False)
    DUAL["msg"] = "repeater switched off again: no connection to a network"
    dual_log(tr("Repeater switched off again by itself: the Pi had no connection to a network any more"), push=True)


def dual_log(text, push=False):
    DUAL["log"] = ([{"t": time.time(), "text": text}] + DUAL["log"])[:30]
    log_event("sys", text)
    if push and CFG.get("net_inet_notify", True):
        w = WATCH_REF.get("w")
        if w is not None:
            threading.Thread(target=w.notifier.info, args=(text,), kwargs={"title": "{name}: " + tr("Network")}, daemon=True).start()


def _visible_saved(iface):
    """Known networks that can be seen now with this adapter, strongest first."""
    code, out, _e = _run(["nmcli", "-t", "-f", "SSID,SIGNAL", "device", "wifi", "list", "ifname", iface, "--rescan", "auto"], 30)
    if code != 0:
        return []
    sig = {}
    for ln in out.splitlines():
        f = _nm_split(ln)
        if len(f) >= 2 and f[0]:
            try:
                sig[f[0]] = max(sig.get(f[0], 0), int(f[1]))
            except ValueError:
                pass
    saved = [s for s in _nm_saved() if s["ssid"] in sig]
    for s in saved:
        s["signal"] = sig[s["ssid"]]
    return sorted(saved, key=lambda s: (-s["prio"], -s["signal"]))


class UplinkWatch:
    """Every 10 s: internet there? Connection drops? -> after 3 min without internet try another known network (only with two
    adapters - with one adapter the network automatic does it). Push message when the internet is back (with how long it was gone)."""
    def __init__(self):
        self.was_conn = None; self.n = 0; self.warned_unstable = 0.0
        threading.Thread(target=self.loop, daemon=True, name="uplink").start()

    def step(self):
        now = time.time(); self.n += 1
        if self.n % 6 == 1:
            try:
                dual_roles()
            except Exception as e:
                DUAL["msg"] = str(e)[:100]
        try:
            dual_safety()
        except Exception as e:
            DUAL["msg"] = str(e)[:100]
            noinet_apply()
        net = STATE.get("net") or {}; w = STATE.get("wifi") or {}
        online = net.get("online")
        if online is False and DUAL["offline_since"] is None:
            DUAL["offline_since"] = now
        elif online and DUAL["offline_since"] is not None:
            gone = now - DUAL["offline_since"]; DUAL["offline_since"] = None
            if gone > 120:
                dual_log(trf("Internet was gone for {min} min - it is back ({ssid})", min=int(gone / 60 + 0.5), ssid=w.get("ssid") or "?"), push=True)
        conn = bool(w.get("connected")) and not w.get("ap")
        if self.was_conn and not conn:
            DUAL["drops"] = [t_ for t_ in DUAL["drops"] if now - t_ < 600] + [now]
            good = [v for v in list(STATE.get("wifi_hist") or [])[-10:] if v is not None]
            if len(DUAL["drops"]) >= 3 and good and max(good) > -70:
                DUAL["unstable"] = True
                if now - self.warned_unstable > 3600:
                    self.warned_unstable = now
                    dual_log(tr("Wi-Fi connection dropped 3 times in 10 minutes although the signal is good - interference or jamming?"),
                             push=bool(CFG.get("wifi_guard")))
        elif DUAL["drops"] and now - DUAL["drops"][-1] > 1800:
            DUAL["unstable"] = False
        self.was_conn = conn
        if self.n % 6 == 0 and conn and w.get("dbm") is not None:
            DUAL["sig"] = (DUAL["sig"] + [[int(now), w["dbm"]]])[-240:]          # one value per minute, 4 hours
        if (DUAL["on"] and DUAL["offline_since"] and now - DUAL["offline_since"] > 180 and now - DUAL["switch_t"] > 300
                and not WIFI.get("busy")):
            DUAL["switch_t"] = now
            cur = w.get("ssid") if conn else ""
            cand = [s for s in _visible_saved(DUAL["up"]) if s["ssid"] != cur]
            if cand:
                c = cand[0]
                code, _o, err = _run(["nmcli", "--wait", "40", "connection", "up", "uuid", c["id"], "ifname", DUAL["up"]], 50)
                dual_log(trf("No internet over «{a}» - changed to «{b}»", a=cur or "?", b=c["ssid"]) if code == 0
                         else trf("No internet - «{b}» did not work either", b=c["ssid"]))
                WIFI["refresh"] = True

    def loop(self):
        time.sleep(15)
        while True:
            try:
                self.step()
            except Exception as e:
                DUAL["msg"] = ("error: " + str(e))[:120]
            time.sleep(10)


# ---- devices in the own Wi-Fi without internet (e.g. cheap Wi-Fi cameras that "call home") ----
def noinet_apply(force=False):
    macs = sorted(m for m in (CFG.get("net_noinet") or []) if re.fullmatch(r"[0-9a-f]{2}(:[0-9a-f]{2}){5}", m))
    key = ",".join(macs)
    if key == DUAL["iso"] and not force:
        return True
    nft, ipt = shutil.which("nft"), shutil.which("iptables")
    ok, err = False, ""
    if nft:
        _run([nft, "add", "table", "inet", "mw_iso"], 8); _run([nft, "delete", "table", "inet", "mw_iso"], 8)
        if macs:
            rules = ("table inet mw_iso {\n chain mwfwd {\n  type filter hook forward priority -10; policy accept;\n"
                     f"  ether saddr {{ {', '.join(macs)} }} drop\n }}\n}}\n")
            code, _o, e = _run([nft, "-f", "-"], 10, inp=rules)
            ok, err = code == 0, e
        else:
            ok = True
    elif ipt:
        _run([ipt, "-D", "FORWARD", "-j", "MW_ISO"], 8); _run([ipt, "-F", "MW_ISO"], 8); _run([ipt, "-X", "MW_ISO"], 8)
        ok = True
        if macs:
            code, _o, err = _run([ipt, "-N", "MW_ISO"], 8)
            for m in macs:
                c2, _o, e2 = _run([ipt, "-A", "MW_ISO", "-m", "mac", "--mac-source", m, "-j", "DROP"], 8)
                if c2:
                    err = e2
            c3, _o, e3 = _run([ipt, "-I", "FORWARD", "1", "-j", "MW_ISO"], 8)
            ok = code == 0 and c3 == 0 and not err
            err = err or e3
    else:
        err = "nft / iptables missing"
    if ok:
        DUAL["iso"] = key; DUAL["iso_msg"] = ""
        if macs or force:
            log_event("sys", f"Without internet: {len(macs)} device(s)")
    else:
        DUAL["iso_msg"] = _perm_hint((err or "error").strip())[:160]
    return ok


# ---- Wi-Fi guard: listens with the stick ("monitor mode") for deauthentication frames = the usual Wi-Fi jamming attack ----
_PRESENCE_SALT = {"day": "", "salt": b""}


def presence_eval():
    P = TOOLS["presence"]
    if not (CFG.get("presence_macs") or CFG.get("presence_bt")):
        return
    now = time.time()
    is_here = now - P.get("last", 0) < float(CFG.get("presence_gone_min", 10)) * 60
    if is_here != P["here"]:
        was = P["here"]; P.update(here=is_here, since=now)
        if was is not None:
            log_event("sys", "Presence: " + ("your device is back" if is_here else "your device is gone"))
            if CFG.get("presence_auto"):
                if is_here and CFG["armed"]:
                    disarm(); log_event("sys", "Disarmed automatically (your device is here)")
                elif not is_here and not CFG["armed"]:
                    arm(); log_event("sys", "Armed automatically (your device is gone)")


class WifiGuard:
    def __init__(self):
        self.sock = None; self.mon = ""
        threading.Thread(target=self.loop, daemon=True, name="wifiguard").start()

    def want(self):
        return bool(CFG.get("wifi_guard") or CFG.get("wifi_count") or (CFG.get("presence_macs") and CFG.get("wifi_presence")))

    def pick(self):
        ads = DUAL["adapters"] or wifi_adapters()
        cand = [a for a in ads if a["monitor"] and a["driver"] != "brcmfmac" and a["phy"]]
        cand.sort(key=lambda a: (a["iface"] != DUAL.get("up"), not a["usb"]))
        return cand[0] if cand else None

    def open(self):
        import socket
        a = self.pick()
        if a is None:
            WGUARD.update(state="no adapter", msg="no Wi-Fi adapter here can listen (monitor mode) - e.g. a stick with MediaTek MT7612U / MT7921AU")
            return False
        name = "mwmon0"
        if not os.path.exists(f"/sys/class/net/{name}"):
            code, _o, err = _run(["iw", "phy", a["phy"], "interface", "add", name, "type", "monitor"], 8)
            if code != 0:
                WGUARD.update(state="not possible", msg=_perm_hint(err.strip() or "monitor mode not possible")[:160]); return False
        _run(["ip", "link", "set", name, "up"], 8)
        if not a["up"] or (a["iface"] not in (DUAL.get("up"), DUAL.get("ap"), WIFI.get("iface"))):
            ch = None                                         # the stick is free: listen on the channel of the own Wi-Fi
            code, out, _e = _run(["iw", "dev", DUAL.get("ap") or WIFI.get("iface") or "wlan0", "info"], 5)
            m = re.search(r"channel (\d+)", out or "")
            if m:
                ch = m.group(1); _run(["iw", "dev", name, "set", "channel", ch], 5)
        try:
            s_ = socket.socket(socket.AF_PACKET, socket.SOCK_RAW, socket.htons(3))
            s_.bind((name, 0)); s_.settimeout(1.0)
        except (OSError, AttributeError) as e:
            WGUARD.update(state="not possible", msg=str(e)[:160]); return False
        self.sock, self.mon = s_, name
        WGUARD.update(state="listening", iface=a["iface"], phy=a["phy"], msg="")
        log_event("sys", f"Wi-Fi guard: listening with {a['iface']} ({a['chip']})")
        return True

    def close(self):
        if self.sock is not None:
            try:
                self.sock.close()
            except OSError:
                pass
        self.sock = None
        if self.mon:
            _run(["iw", "dev", self.mon, "del"], 8); self.mon = ""
        WGUARD["state"] = "off"

    def own_bssids(self):
        own = set()
        for i in (DUAL.get("ap"), DUAL.get("up"), WIFI.get("iface")):
            if i:
                m = _rd(f"/sys/class/net/{i}/address")
                if m:
                    own.add(m.lower())
                code, out, _e = _run(["iw", "dev", i, "link"], 4)
                mm = re.search(r"Connected to ([0-9a-f:]{17})", out or "")
                if mm:
                    own.add(mm.group(1).lower())
        return own

    def loop(self):
        time.sleep(20)
        minute_t = time.time(); dea = dall = 0; seen = {}; own = set(); own_t = 0.0; mine = set()
        while True:
            if not self.want():
                if self.sock is not None:
                    self.close()
                time.sleep(5); continue
            if self.sock is None:
                if not self.open():
                    time.sleep(120); continue
            now = time.time()
            if now - own_t > 60:
                own = self.own_bssids(); own_t = now; mine = set(CFG.get("presence_macs") or [])
                d_ = datetime.now().strftime("%Y%m%d")
                if _PRESENCE_SALT["day"] != d_:
                    _PRESENCE_SALT.update(day=d_, salt=os.urandom(16)); seen.clear()
            try:
                pkt = self.sock.recv(4096)
            except OSError as e:
                if "timed out" not in str(e):
                    WGUARD.update(state="error", msg=str(e)[:120]); self.close(); time.sleep(30); continue
                pkt = b""
            if len(pkt) > 8:
                rl = pkt[2] | (pkt[3] << 8)
                f = pkt[rl:]
                if len(f) >= 16:
                    fc = f[0]; typ = (fc >> 2) & 3; sub = (fc >> 4) & 15
                    WGUARD["frames"] += 1
                    a2 = f[10:16].hex(":")
                    if typ == 0 and sub in (10, 12) and len(f) >= 22:          # disassociation / deauthentication
                        dall += 1
                        if f[16:22].hex(":") in own or a2 in own or f[4:10].hex(":") in own:
                            dea += 1
                    elif typ == 0 and sub == 4 and CFG.get("wifi_count"):    # probe request: only counted, never stored
                        import hashlib
                        seen[hashlib.sha256(_PRESENCE_SALT["salt"] + f[10:16]).hexdigest()[:12]] = now
                    if mine and a2 in mine:
                        TOOLS["presence"]["last"] = now
            if now - minute_t >= 60:
                minute_t = now
                WGUARD["deauth_min"] = (WGUARD["deauth_min"] + [[int(now), dea, dall]])[-120:]
                WGUARD["deauth_now"], WGUARD["all_now"] = dea, dall
                if CFG.get("wifi_count"):
                    for k in [k for k, t_ in seen.items() if now - t_ > 300]:
                        seen.pop(k, None)
                    WGUARD["count_now"] = len(seen)
                    WGUARD["count_hist"] = (WGUARD["count_hist"] + [[int(now), len(seen)]])[-288:]
                else:
                    seen.clear(); WGUARD["count_now"] = None
                if CFG.get("wifi_guard") and (dea >= int(CFG.get("wifi_guard_thr", 20)) or dall >= 300) and (not WGUARD["last_alarm"] or now - WGUARD["last_alarm"] > 1800):
                    WGUARD["last_alarm"] = now
                    txt = trf("Wi-Fi jamming: {n} disconnect frames in one minute ({all} in total on the channel)", n=dea, all=dall)
                    WGUARD["alarms"] = ([{"t": now, "n": dea, "all": dall}] + WGUARD["alarms"])[:20]
                    log_event("tamper", txt)
                    w = WATCH_REF.get("w")
                    if w is not None:
                        w.notifier.alert("{name}: " + tr("Wi-Fi jamming attack"), txt, getattr(w, "frame_out", None))
                dea = dall = 0
                presence_eval()


def dual_state():
    hs = STATE.get("hotspot") or {}; w = STATE.get("wifi") or {}
    return {"on": DUAL["on"], "ap": DUAL["ap"], "up": DUAL["up"], "adapters": DUAL["adapters"], "msg": DUAL["msg"], "log": DUAL["log"][:12],
            "sig": DUAL["sig"][-120:], "unstable": DUAL["unstable"], "offline_since": DUAL["offline_since"], "iso_msg": DUAL["iso_msg"],
            "repeater": bool(DUAL["on"] and hs.get("on") and w.get("connected")), "hotspot": {"on": hs.get("on"), "ssid": hs.get("ssid"), "clients": hs.get("clients")},
            "uplink": {"ssid": w.get("ssid"), "dbm": w.get("dbm"), "pct": w.get("pct"), "connected": w.get("connected")},
            "online": (STATE.get("net") or {}).get("online"),
            "cfg": {k: CFG.get(k) for k in ("wifi_repeater", "wifi_swap", "wifi_guard", "wifi_guard_thr", "wifi_count", "wifi_presence", "net_inet_notify", "net_noinet")},
            "guard": {k: WGUARD[k] for k in ("state", "iface", "msg", "deauth_min", "deauth_now", "all_now", "frames", "alarms", "count_now", "count_hist")}}


def dual_set(key, value):
    if key in ("wifi_repeater", "wifi_swap"):
        CFG[key] = bool(value); save_settings(); DUAL["choice"] = None; dual_roles()
        if key == "wifi_repeater" and value:
            log_event("sys", "Repeater switched on by hand")
        if STATE["hotspot"].get("on"):
            hotspot_switch_later(True, 0.5)
        return True, ""
    if key in ("wifi_guard", "wifi_count", "wifi_presence", "net_inet_notify"):
        CFG[key] = bool(value); save_settings(); return True, ""
    if key == "wifi_guard_thr":
        try:
            CFG[key] = int(min(500, max(5, int(value)))); save_settings(); return True, ""
        except (TypeError, ValueError):
            return False, "bad value"
    return False, "unknown setting"


def noinet_set(mac, on):
    mac = str(mac or "").lower()
    if not re.fullmatch(r"[0-9a-f]{2}(:[0-9a-f]{2}){5}", mac):
        return False, "bad address"
    L = [m for m in (CFG.get("net_noinet") or []) if m != mac]
    if on:
        L.append(mac)
    CFG["net_noinet"] = L[-30:]; save_settings()
    ok = noinet_apply(force=True)
    return ok, "" if ok else DUAL["iso_msg"]


# ----------------------------------------------------------------------------
# Network automatic: known networks first (e.g. the phone hotspot = internet + push messages), otherwise the own Wi-Fi.
#   start / connection lost: wait auto_wait seconds for a known network, then switch the own Wi-Fi on
#   own Wi-Fi on: every auto_retry minutes look for known networks again - only when no device is connected to the Pi
#   switching by hand (hotspot switch, camping profile) pauses the automatic until the network mode is chosen again
# Timers use time.monotonic(): the clock may jump when it is taken from the phone.
# ----------------------------------------------------------------------------
NETAUTO = {"paused": False, "status": "off"}
NETAUTO_SEARCH = 45.0                                   # seconds the own Wi-Fi stays off while known networks are tried


def netauto_pause():
    if CFG["net_mode"] == "auto" and not NETAUTO["paused"]:
        NETAUTO["paused"] = True
        log_event("sys", "Network automatic paused (switched by hand) - choose the network mode again to resume")


class NetAuto:
    def __init__(self):
        self.lost_since = None; self.next_retry = None
        threading.Thread(target=self.loop, daemon=True).start()

    def _set(self, status):
        if status != NETAUTO["status"]:
            NETAUTO["status"] = status
        STATE["netauto"] = status

    def wait_connected(self, seconds):
        end = time.monotonic() + seconds
        while time.monotonic() < end:
            time.sleep(1.0)
            w = STATE["wifi"] or {}
            if w.get("connected") and not STATE["hotspot"].get("on"):
                return w.get("ssid") or "?"
        return ""

    def step(self):
        if CFG["net_mode"] != "auto":
            self.lost_since = None; self.next_retry = None; self._set("off"); return
        if wifi_backend() != "nm":
            self._set("needs NetworkManager"); return
        if NETAUTO["paused"]:
            self._set("paused (switched by hand)"); return
        if WIFI["busy"] or WIFI.get("hs_busy"):
            return
        now = time.monotonic()
        hs, w = STATE["hotspot"] or {}, STATE["wifi"] or {}
        if DUAL["on"]:
            self.lost_since = None; self.next_retry = None
            if not hs.get("on"):
                ok, err = hotspot_set(True, persist=False); hotspot_refresh()
                self._set("own Wi-Fi on" if ok else "own Wi-Fi failed: " + err[:100]); return
            self._set(f"own Wi-Fi on + internet from «{w.get('ssid') or '?'}»" if w.get("connected")
                      else "own Wi-Fi on - the second adapter looks for known networks")
            return
        retry = max(0.0, float(CFG["auto_retry"])) * 60.0
        if hs.get("on"):
            self.lost_since = None
            if retry <= 0:
                self._set("own Wi-Fi on"); return
            if self.next_retry is None:
                self.next_retry = now + retry
            if now < self.next_retry:
                self._set(f"own Wi-Fi on - next search in {max(1, int((self.next_retry - now) / 60 + 0.99))} min"); return
            if hs.get("clients", 0) > 0:
                self.next_retry = now + min(60.0, retry)
                self._set("own Wi-Fi on - search postponed (a device is connected)"); return
            self._set("searching known networks …")
            log_event("sys", "Network automatic: own Wi-Fi off for a moment, looking for known networks")
            hotspot_set(False, persist=False); hotspot_refresh()
            ssid = self.wait_connected(NETAUTO_SEARCH)
            if ssid:
                self.next_retry = None
                log_event("sys", f"Network automatic: connected with «{ssid}»")
                self._set(f"connected with «{ssid}»")
            else:
                hotspot_set(True, persist=False); hotspot_refresh()
                self.next_retry = time.monotonic() + retry
                log_event("sys", "Network automatic: no known network - own Wi-Fi on again")
            return
        if w.get("connected"):
            self.lost_since = None; self.next_retry = None
            self._set(f"connected with «{w.get('ssid') or '?'}»"); return
        if self.lost_since is None:
            self.lost_since = now
        left = float(CFG["auto_wait"]) - (now - self.lost_since)
        if left > 0:
            self._set(f"no known network - own Wi-Fi in {int(left + 0.99)} s"); return
        log_event("sys", "Network automatic: no known network - switching the own Wi-Fi on")
        ok, err = hotspot_set(True, persist=False); hotspot_refresh()       # state at once, not 2 s later
        self.lost_since = None; self.next_retry = time.monotonic() + retry
        self._set("own Wi-Fi on" if ok else "own Wi-Fi failed: " + err[:100])

    def loop(self):
        while True:
            time.sleep(2.0)
            try:
                self.step()
            except Exception as e:
                self._set("error: " + str(e)[:100])


# ----------------------------------------------------------------------------
# Patrol: pendulum over waypoints  (1-2-3-2-1-2-3 ...)
# ----------------------------------------------------------------------------
class Patrol:
    def __init__(self):
        self.paused_until = 0
        threading.Thread(target=self.loop, daemon=True).start()

    def move_to(self, pan, tilt):
        """Smoothly move pan and tilt together (straight line) at patrol_speed %/s; returns False if interrupted."""
        while True:
            dp, dt = pan - CFG["pan"], tilt - CFG["tilt"]
            dist = math.hypot(dp, dt)
            if dist <= 0.5:
                break
            if not CFG["patrol"] or STATE["tracking"] or servo_hold():
                return False
            f = min(1.0, CFG["patrol_speed"] * 0.02 / dist)
            CFG["pan"] = CFG["pan"] + dp * f
            CFG["tilt"] = CFG["tilt"] + dt * f
            time.sleep(0.02)
        CFG["pan"], CFG["tilt"] = float(pan), float(tilt)
        return True

    def loop(self):
        announced = False
        while True:
            if not CFG["patrol"] or len(WAYPOINTS) < 2:
                STATE["patrol_status"] = "off" if not CFG["patrol"] else "need 2+ waypoints"
                announced = False
                time.sleep(0.3); continue
            if STATE["tracking"]:
                STATE["patrol_status"] = "paused (tracking person)"
                time.sleep(0.2); continue
            if servo_hold():
                STATE["patrol_status"] = "paused (manual control)"
                time.sleep(0.2); continue
            if not announced:
                log_event("patrol", f"Patrol started over {len(WAYPOINTS)} waypoints (pan/tilt): {wp_text()}")
                announced = True
            wps = list(WAYPOINTS)
            # pendulum 1-2-3-2-1 (no doubled end points) or round trip 1-2-3-1-2-3
            path = wps if CFG["patrol_mode"] == "loop" else wps + wps[-2:0:-1]
            for i, wp in enumerate(path):
                STATE["patrol_status"] = f"moving to waypoint {i + 1}/{len(path)} ({wp[0]:.0f}/{wp[1]:.0f})"
                if not self.move_to(wp[0], wp[1]):
                    break
                STATE["patrol_status"] = f"dwelling at {wp[0]:.0f}/{wp[1]:.0f}"
                t_end = time.time() + CFG["patrol_dwell"]
                while time.time() < t_end:
                    if not CFG["patrol"] or STATE["tracking"] or servo_hold():
                        break
                    time.sleep(0.05)
                if not CFG["patrol"] or STATE["tracking"] or servo_hold():
                    break


# ----------------------------------------------------------------------------
# AI person detector (SSD MobileNet V2, COCO class 1 = person)
# ----------------------------------------------------------------------------
AI_MODEL = {"busy": False, "msg": "", "pct": 0}
AI_TGZ_URLS = ("https://storage.googleapis.com/download.tensorflow.org/models/object_detection/ssd_mobilenet_v2_coco_2018_03_29.tar.gz",
               "https://download.tensorflow.org/models/object_detection/ssd_mobilenet_v2_coco_2018_03_29.tar.gz")
AI_PBTXT_URL = "https://raw.githubusercontent.com/opencv/opencv_extra/master/testdata/dnn/ssd_mobilenet_v2_coco_2018_03_29.pbtxt"


def ai_model_dirs():
    return [os.path.dirname(os.path.abspath(__file__)), os.path.join(DATA_DIR, "models")]


def ai_model_paths():
    """(pb, pbtxt) of the first folder that has both files - next to the program or in the data folder."""
    for d in ai_model_dirs():
        pb, pbtxt = os.path.join(d, AIDetector.PB), os.path.join(d, AIDetector.PBTXT)
        if os.path.isfile(pb) and os.path.isfile(pbtxt):
            return pb, pbtxt
    return None, None


def _short_net_err(e):
    """A short, readable reason for a failed download."""
    r = getattr(e, "reason", None) or e
    t = str(r)
    if "CERTIFICATE_VERIFY_FAILED" in t:
        return "certificate not valid (check the clock of the Pi)" if "expired" in t or "not yet valid" in t else "certificate not valid"
    if isinstance(r, TimeoutError) or "timed out" in t:
        return "no answer (internet slow or missing)"
    if "Name or service not known" in t or "getaddrinfo" in t or "Temporary failure in name resolution" in t:
        return "no internet (name not found)"
    if "Connection refused" in t or "Network is unreachable" in t:
        return "no internet connection"
    if getattr(e, "code", None):
        return f"server answered {e.code}"
    return t[:80]


def ai_model_download():
    """Fetch the AI model in the background (about 70 MB), check that OpenCV can read it, switch the AI on."""
    if AI_MODEL["busy"]:
        return False, "already running"
    if DEMO["on"]:
        return False, "not in the demo"
    AI_MODEL.update(busy=True, msg="downloading", pct=0)

    def run():
        import tarfile
        dst = os.path.join(DATA_DIR, "models"); os.makedirs(dst, exist_ok=True)
        tgz = os.path.join(dst, "model.tar.gz.part"); pb_tmp = os.path.join(dst, AIDetector.PB + ".part"); tx_tmp = os.path.join(dst, AIDetector.PBTXT + ".part")
        try:
            errs = []
            for url in AI_TGZ_URLS:                               # first address that works (certificates are always checked)
                try:
                    req = urllib.request.Request(url, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
                    with urllib.request.urlopen(req, timeout=60) as r, open(tgz, "wb") as f:
                        total = int(r.headers.get("Content-Length") or 0); got = 0
                        while True:
                            b = r.read(256 * 1024)
                            if not b:
                                break
                            f.write(b); got += len(b)
                            AI_MODEL["pct"] = int(got * 90 / total) if total else min(89, got // (800 * 1024))
                    errs = []; break
                except Exception as e:
                    errs.append(_short_net_err(e))
            if errs:
                raise RuntimeError(errs[0])
            with tarfile.open(tgz, "r:gz") as t:                 # only the one file, written by us (no paths from the archive)
                m = next((x for x in t.getmembers() if x.isfile() and x.name.endswith("/" + AIDetector.PB)), None)
                if m is None:
                    raise RuntimeError("model file missing in the archive")
                src = t.extractfile(m)
                with open(pb_tmp, "wb") as f:
                    shutil.copyfileobj(src, f)
            req = urllib.request.Request(AI_PBTXT_URL, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
            with urllib.request.urlopen(req, timeout=60) as r:
                txt = r.read(5 * 1024 * 1024)
            if b"node" not in txt[:4096]:
                raise RuntimeError("the description file is not valid")
            with open(tx_tmp, "wb") as f:
                f.write(txt)
            AI_MODEL["pct"] = 95
            try:
                cv2.dnn.readNetFromTensorflow(pb_tmp, tx_tmp)    # raises if the files are damaged
            except cv2.error:
                raise RuntimeError("the model files are damaged - try again")
            os.replace(pb_tmp, os.path.join(dst, AIDetector.PB)); os.replace(tx_tmp, os.path.join(dst, AIDetector.PBTXT))
            CFG["ai_enabled"] = True; save_settings()
            w = WATCH_REF["w"]
            if w is not None:
                w.ai = AIDetector()
            AI_MODEL.update(msg="ready", pct=100)
            log_event("ai", "AI model downloaded and switched on")
        except Exception as e:
            AI_MODEL.update(msg=f"failed: {tr(str(e))}"[:120], pct=0)
            log_event("ai", f"AI model download failed: {e}"[:200])
        finally:
            AI_MODEL["busy"] = False
            for p_ in (tgz, pb_tmp, tx_tmp):
                try:
                    os.remove(p_)
                except OSError:
                    pass
    threading.Thread(target=run, daemon=True, name="ai-model").start()
    return True, ""


# ----------------------------------------------------------------------------
# Animal species: a second AI model (image classifier, ONNX) looks at the animals the first AI finds (COCO only knows
#   "dog", "cat", "bear" ... - a fox is often a "dog"). Files: <data>/models/species/<name>.onnx and <name>.txt with one
#   label per line in the order of the model's outputs, optionally "english;Deutsch" (e.g. "red fox;Fuchs").
# ----------------------------------------------------------------------------
SPECIES = {"net": None, "model": "", "labels": set(), "names": [], "msg": "off", "cache": [], "busy": False, "t": 0.0, "last": None}


def species_dir():
    return os.path.join(DATA_DIR, "models", "species")


def species_models():
    try:
        return sorted(f for f in os.listdir(species_dir()) if f.lower().endswith(".onnx") and REC_NAME_RE.match(f))[:20]
    except OSError:
        return []


def species_load():
    m = str(CFG["species_model"] or "")
    if SPECIES["model"] == m and (SPECIES["net"] is not None or not m):
        return SPECIES["net"]
    SPECIES.update(net=None, model=m, names=[], cache=[])
    if not m:
        SPECIES["msg"] = "no model chosen"; return None
    path = os.path.join(species_dir(), m)
    try:
        net = cv2.dnn.readNetFromONNX(path)
        with open(os.path.splitext(path)[0] + ".txt", encoding="utf-8") as f:
            rows = [ln.strip() for ln in f if ln.strip()]
    except (cv2.error, OSError) as e:
        SPECIES["msg"] = f"load error: {e}"[:120]; log_event("ai", f"Animal species model: {SPECIES['msg']}"); return None
    names = []
    for r in rows:
        en, _, de = r.partition(";")
        en = en.strip()[:40]; names.append(en)
        if de.strip():
            DE.setdefault(en, de.strip()[:40])
    SPECIES.update(net=net, names=names, labels=set(names), msg=f"ready · {len(names)} species")
    log_event("ai", f"Animal species model {m} loaded ({len(names)} species)")
    return net


def species_classify(crop):
    """(label, certainty) for one picture of an animal, or None."""
    net = species_load()
    if net is None or crop is None or crop.size == 0:
        return None
    n = int(CFG["species_size"]); img = cv2.cvtColor(cv2.resize(crop, (n, n), interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2RGB).astype(np.float32) / 255.0
    mode = CFG["species_norm"]
    if mode == "imagenet":
        img = (img - np.array([0.485, 0.456, 0.406], np.float32)) / np.array([0.229, 0.224, 0.225], np.float32)
    elif mode == "-11":
        img = img * 2.0 - 1.0
    net.setInput(img.transpose(2, 0, 1)[None])
    out = net.forward().reshape(-1).astype(np.float64)
    if out.size != len(SPECIES["names"]):
        SPECIES["msg"] = f"the label file has {len(SPECIES['names'])} lines, the model {out.size} outputs"; return None
    if out.min() < 0 or abs(out.sum() - 1.0) > 0.01:          # raw scores -> probabilities
        e = np.exp(out - out.max()); out = e / e.sum()
    i = int(out.argmax())
    return SPECIES["names"][i], float(out[i])


def species_update(objs, frame, pw, ph, t0):
    """Called by the camera loop: the biggest animal is classified in the background (at most every 2 s)."""
    SPECIES["cache"] = [c for c in SPECIES["cache"] if t0 - c[3] < 6]
    if not CFG["species_on"] or not CFG["species_model"] or SPECIES["busy"] or t0 - SPECIES["t"] < 2.0:
        return
    an = [o for o in objs if COCO_LABELS.get(o[5]) in ANIMALS]
    if not an:
        return
    o = max(an, key=lambda b: b[2] * b[3]); H, W = frame.shape[:2]; sx, sy = W / float(pw), H / float(ph)
    x, y, w, h = o[0] * sx, o[1] * sy, o[2] * sx, o[3] * sy
    m = 0.15
    crop = frame[max(0, int(y - h * m)):min(H, int(y + h * (1 + m))), max(0, int(x - w * m)):min(W, int(x + w * (1 + m)))].copy()
    SPECIES["busy"] = True; SPECIES["t"] = t0

    def run():
        try:
            r = species_classify(crop)
            if r and r[1] >= float(CFG["species_conf"]):
                SPECIES["cache"].append((o[:4], r[0], r[1], time.time()))
                if not SPECIES["last"] or SPECIES["last"][0] != r[0] or time.time() - SPECIES["last"][2] > 60:
                    log_event("ai", f"Animal species: {r[0]} {int(r[1] * 100)} % (first AI: {COCO_LABELS.get(o[5])})")
                SPECIES["last"] = (r[0], r[1], time.time())
        except Exception as e:
            SPECIES["msg"] = f"error: {e}"[:120]
        finally:
            SPECIES["busy"] = False
    threading.Thread(target=run, daemon=True, name="species").start()


def species_for(box):
    """The species found for a box of the first AI (overlap), or None."""
    best = None
    for b, lab, conf, _t in SPECIES["cache"]:
        if iou(box, b) > 0.3 and (best is None or conf > best[1]):
            best = (lab, conf)
    return best


def species_install(url):
    """Download a model (.onnx, its labels .txt next to it - or a .zip with both) into the species folder."""
    if not (isinstance(url, str) and re.match(r"^https://[^\s]{4,400}$", url)):
        return False, "address must start with https://"
    os.makedirs(species_dir(), exist_ok=True)
    name = re.sub(r"[^A-Za-z0-9_.\-]", "_", url.rsplit("/", 1)[-1].split("?")[0])[:80] or "model.onnx"

    def get(u, dst, limit=400 * 1024 * 1024):
        req = urllib.request.Request(u, headers={"User-Agent": "MotionWatch/" + APP_VERSION})
        with urllib.request.urlopen(req, timeout=60) as r, open(dst + ".part", "wb") as f:
            n = 0
            for chunk in iter(lambda: r.read(1 << 20), b""):
                n += len(chunk)
                if n > limit:
                    raise ValueError("file too big")
                f.write(chunk)
        os.replace(dst + ".part", dst)
    try:
        if name.lower().endswith(".zip"):
            tmp = os.path.join(species_dir(), name); get(url, tmp)
            with zipfile.ZipFile(tmp) as z:
                for zi in z.infolist():
                    bn = os.path.basename(zi.filename)
                    if bn.lower().endswith((".onnx", ".txt")) and REC_NAME_RE.match(bn):
                        with z.open(zi) as src, open(os.path.join(species_dir(), bn), "wb") as dst:
                            shutil.copyfileobj(src, dst)
            os.remove(tmp)
        elif name.lower().endswith(".onnx"):
            get(url, os.path.join(species_dir(), name))
            try:
                get(url[:url.lower().rfind(".onnx")] + ".txt", os.path.join(species_dir(), name[:-5] + ".txt"), 2 * 1024 * 1024)
            except Exception:
                pass
        else:
            return False, "the address must end with .onnx or .zip"
    except Exception as e:
        return False, _short_net_err(e) if "_short_net_err" in globals() else str(e)[:120]
    ms = species_models()
    if ms and not CFG["species_model"]:
        CFG["species_model"] = ms[0]; save_settings()
    log_event("ai", f"Animal species model installed from {url[:80]}")
    return True, ""


class AIDetector:
    PB, PBTXT = "frozen_inference_graph.pb", "ssd_mobilenet_v2_coco.pbtxt"

    def __init__(self):
        self.net = None
        self.boxes = []          # last persons, in processing-frame coordinates
        self.objects = []        # last non-person objects (x, y, w, h, conf, cls)
        self.frame_counter = 0
        pb, pbtxt = ai_model_paths()
        if pb:
            try:
                self.net = cv2.dnn.readNetFromTensorflow(pb, pbtxt)
                STATE["ai_status"] = "ready"
                log_event("ai", "AI model SSD MobileNet V2 loaded")
            except Exception as e:
                STATE["ai_status"] = "load error"
                log_event("ai", f"AI model could not be loaded: {e}")
        else:
            CFG["ai_enabled"] = False
            STATE["ai_status"] = "no model files"
            log_event("ai", "AI off: model files not found - «Download AI model» in the self-check or the AI settings")

    def detect(self, frame):
        """Run every N frames; returns list of (x, y, w, h, conf) persons."""
        if DEMO["on"]:
            self.boxes, self.objects = demo_ai(frame); STATE["ai_status"] = "demo"
            return self.boxes
        if self.net is None or not CFG["ai_enabled"]:
            STATE["ai_status"] = "off" if self.net else STATE["ai_status"]
            self.boxes = []; self.objects = []
            return self.boxes
        self.frame_counter += 1
        if self.frame_counter % max(1, int(CFG["ai_every"])) != 0:
            return self.boxes
        # at most a few times per second and slower when the Pi gets hot: the AI is the biggest load (power, heat)
        gap = max(0.3, 2.0 * (STATE.get("ai_ms") or 0) / 1000.0)
        ct = STATE.get("cpu_temp") or 0
        gap *= 4.0 if ct >= 80 else 2.0 if ct >= 75 else 1.0
        if CFG.get("sim_on") and CFG.get("sim_eco"):
            gap *= 2.0                                     # simulation with CPU saving: the AI only half as often
        if time.time() - getattr(self, "_last_run", 0.0) < gap:
            return self.boxes
        self._last_run = time.time()
        t0 = time.time()
        h, w = frame.shape[:2]
        blob = cv2.dnn.blobFromImage(frame, size=(300, 300), swapRB=True, crop=False)
        self.net.setInput(blob)
        det = self.net.forward()
        boxes, objects = [], []
        for i in range(det.shape[2]):
            cls, conf = int(det[0, 0, i, 1]), float(det[0, 0, i, 2])
            need = CFG["ai_conf"] if cls == 1 else CFG["object_conf"]
            if cls < 1 or conf < need:
                continue
            x1, y1, x2, y2 = (det[0, 0, i, 3:7] * np.array([w, h, w, h])).astype(int)
            x1, y1 = max(0, x1), max(0, y1); x2, y2 = min(w - 1, x2), min(h - 1, y2)
            if x2 > x1 and y2 > y1:
                if cls == 1:
                    boxes.append((x1, y1, x2 - x1, y2 - y1, conf))
                else:
                    objects.append((int(x1), int(y1), int(x2 - x1), int(y2 - y1), conf, cls))
        self.boxes = boxes; self.objects = objects
        STATE["ai_ms"] = int((time.time() - t0) * 1000)
        STATE["ai_status"] = f"running · {STATE['ai_ms']} ms"
        STATE["ai_persons"] = len(boxes)
        return boxes


